```java
static final class RecordingSinkConduit implements StreamSinkConduit {
    final ByteArrayOutputStream wire = new ByteArrayOutputStream();
    long consumeLimit = Long.MAX_VALUE;
    int writeArrayCalls = 0;
    int writeSingleCalls = 0;
    boolean flushResult = true;
    boolean writeShutdown = false;
    boolean terminated = false;
    boolean truncated = false;
    ByteBuffer lastSingle;

    @Override public long write(ByteBuffer[] srcs, int offset, int length) {
        writeArrayCalls++;
        long budget = consumeLimit;
        long consumed = 0;
        for (int i=0;i<length && budget>0;i++) {
            ByteBuffer b = srcs[offset+i];
            int n = (int)Math.min((long)b.remaining(), budget);
            for (int k=0;k<n;k++) wire.write(b.get());
            budget -= n;
            consumed += n;
        }
        return consumed;
    }
    @Override public int write(ByteBuffer src) {
        writeSingleCalls++;
        int n = (int)Math.min((long)src.remaining(), consumeLimit);
        for (int k=0;k<n;k++) wire.write(src.get());
        return n;
    }
    ...
}
```

