/**
 * Unit tests for the package private {@link ChunkedStreamSinkConduit#doWrite(ByteBuffer[], int, int)}
 * scatter/gather write entry point.
 */
class ChunkedStreamSinkConduitDoWriteTests {

    private static final byte[] CRLF = new byte[] {13, 10};

    // ------------------------------------------------------------------
    // Basic / degenerate inputs
    // ------------------------------------------------------------------

    @Test
    void zeroLengthArrayReturnsZeroAndDoesNotWrite() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);

        long result = conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("ignored")) }, 0, 0);

        assertEquals(0L, result);
        assertEquals(0, next.arrayWriteCalls, "next conduit must not be invoked for zero length");
        assertEquals("", wire(next));
    }

    @Test
    void allBuffersEmptyReturnsZeroAndDoesNotWrite() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);

        ByteBuffer first = ByteBuffer.allocate(0);
        ByteBuffer second = ByteBuffer.allocate(8);
        second.position(8); // no bytes remaining

        long result = conduit.doWrite(new ByteBuffer[] { first, second }, 0, 2);

        assertEquals(0L, result);
        assertEquals(0, next.arrayWriteCalls, "next conduit must not be invoked when nothing remains");
        assertEquals("", wire(next));
        assertEquals(0, first.remaining());
        assertEquals(0, second.remaining());
    }

    // ------------------------------------------------------------------
    // Happy paths
    // ------------------------------------------------------------------

    @Test
    void singleBufferWritesOneChunk() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("hello"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(5L, result);
        assertEquals(0, src.remaining(), "source buffer should be fully consumed");
        assertEquals("5\r\nhello\r\n", wire(next));
    }

    @Test
    void multipleBuffersAreCombinedIntoOneChunk() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer a = ByteBuffer.wrap(bytes("abc"));
        ByteBuffer b = ByteBuffer.wrap(bytes("de"));

        long result = conduit.doWrite(new ByteBuffer[] { a, b }, 0, 2);

        assertEquals(5L, result);
        assertEquals(0, a.remaining());
        assertEquals(0, b.remaining());
        assertEquals("5\r\nabcde\r\n", wire(next));
    }

    @Test
    void bufferPositionIsRespected() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abcdef"));
        src.position(2);
        src.limit(5); // remaining "cde"

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(3L, result);
        assertEquals(0, src.remaining());
        assertEquals(5, src.limit(), "limit must be restored to its original value");
        assertEquals("3\r\ncde\r\n", wire(next));
    }

    @Test
    void offsetAndLengthSelectSubsetOfArray() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer before = ByteBuffer.wrap(bytes("XXXX"));
        ByteBuffer selected = ByteBuffer.wrap(bytes("abcd"));
        ByteBuffer after = ByteBuffer.wrap(bytes("YYYY"));

        long result = conduit.doWrite(new ByteBuffer[] { before, selected, after }, 1, 1);

        assertEquals(4L, result);
        assertEquals(0, selected.remaining(), "selected buffer should be written");
        assertEquals(4, before.remaining(), "buffer before offset must be untouched");
        assertEquals(4, after.remaining(), "buffer after range must be untouched");
        assertEquals("4\r\nabcd\r\n", wire(next));
    }

    // ------------------------------------------------------------------
    // Chunk size hexadecimal encoding boundaries
    // ------------------------------------------------------------------

    @Test
    void chunkSizeOfSixteenUsesTwoHexDigits() throws IOException {
        assertChunkHeaderEncoding(16, "10");
    }

    @Test
    void chunkSizeOfFifteenUsesSingleHexDigit() throws IOException {
        assertChunkHeaderEncoding(15, "f");
    }

    @Test
    void chunkSizeOfTwoHundredFiftyFiveUsesTwoLowercaseHexDigits() throws IOException {
        assertChunkHeaderEncoding(255, "ff");
    }

    @Test
    void chunkSizeOfTwoHundredFiftySixUsesThreeHexDigits() throws IOException {
        assertChunkHeaderEncoding(256, "100");
    }

    private static void assertChunkHeaderEncoding(int size, String expectedHex) throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);
        String payload = "A".repeat(size);

        long result = conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes(payload)) }, 0, 1);

        assertEquals((long) size, result);
        assertEquals(expectedHex + "\r\n" + payload + "\r\n", wire(next));
    }

    // ------------------------------------------------------------------
    // Back pressure / partial writes
    // ------------------------------------------------------------------

    @Test
    void fullyBlockedWriteReturnsZeroAndRetainsData() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 0;
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abc"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(0L, result);
        assertEquals(1, next.arrayWriteCalls, "next conduit is still offered the buffers");
        assertEquals(3, src.remaining(), "no data should be consumed when next accepts nothing");
        assertEquals("", wire(next));
    }

    @Test
    void retryAfterFullyBlockedWriteEmitsWholeChunk() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 0;
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abc"));
        ByteBuffer[] srcs = new ByteBuffer[] { src };

        assertEquals(0L, conduit.doWrite(srcs, 0, 1));

        next.consumeLimit = Long.MAX_VALUE;
        long result = conduit.doWrite(srcs, 0, 1);

        assertEquals(3L, result);
        assertEquals(0, src.remaining());
        assertEquals("3\r\nabc\r\n", wire(next));
    }

    @Test
    void partialChunkHeaderWriteReturnsZero() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 1; // only part of "3\r\n" can be written
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abc"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(0L, result, "when less than the chunk header is written no data progress is reported");
        assertEquals(3, src.remaining(), "no payload byte should be consumed");
        assertEquals("3", wire(next));
    }

    @Test
    void writingExactlyTheChunkHeaderReturnsZeroDataProgress() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 3; // exactly "3\r\n"
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abc"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(0L, result, "header boundary means no payload has been written yet");
        assertEquals(3, src.remaining());
        assertEquals("3\r\n", wire(next));
    }

    @Test
    void partialPayloadWriteReturnsBytesOfPayloadConsumed() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 4; // header "3\r\n" plus a single payload byte
        ChunkedStreamSinkConduit conduit = createConduit(next);
        ByteBuffer src = ByteBuffer.wrap(bytes("abc"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(1L, result, "only the consumed payload byte is reported, not the header bytes");
        assertEquals(2, src.remaining());
        assertEquals("3\r\na", wire(next));
    }

    // ------------------------------------------------------------------
    // Multiple chunks / state carried between calls
    // ------------------------------------------------------------------

    @Test
    void afterFinishedChunkNextWriteStartsANewChunk() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        ChunkedStreamSinkConduit conduit = createConduit(next);

        long first = conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("abc")) }, 0, 1);
        long second = conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("de")) }, 0, 1);

        assertEquals(3L, first);
        assertEquals(2L, second);
        assertEquals("3\r\nabc\r\n2\r\nde\r\n", wire(next));
    }

    @Test
    void continuationCapsNewBufferToRemainingChunkAndRestoresLimit() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 3; // write only the "3\r\n" header of the first chunk
        ChunkedStreamSinkConduit conduit = createConduit(next);

        assertEquals(0L, conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("abc")) }, 0, 1));

        // The previous call left three payload bytes pending on the current chunk.
        next.consumeLimit = Long.MAX_VALUE;
        ByteBuffer src = ByteBuffer.wrap(bytes("0123456789"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(3L, result, "only the remaining bytes of the current chunk may be written");
        assertEquals(3, src.position(), "three bytes should have been consumed");
        assertEquals(10, src.limit(), "the temporary limit must be restored");
        assertEquals(7, src.remaining(), "the rest of the buffer must be left for later");
        assertEquals("\r\n012", wire(next));
    }

    @Test
    void continuationConsumesEntireSmallerBuffer() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 3; // write only the "6\r\n" header
        ChunkedStreamSinkConduit conduit = createConduit(next);

        assertEquals(0L, conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("abcdef")) }, 0, 1));

        next.consumeLimit = Long.MAX_VALUE;
        ByteBuffer src = ByteBuffer.wrap(bytes("xy"));

        long result = conduit.doWrite(new ByteBuffer[] { src }, 0, 1);

        assertEquals(2L, result, "the smaller buffer fits entirely within the remaining chunk");
        assertEquals(0, src.remaining());
        assertEquals("\r\nxy", wire(next));
    }

