        ChunkedStreamSinkConduit conduit = createConduit(next);

        conduit.terminateWrites();

        assertThrows(ClosedChannelException.class,
                () -> conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("abc")) }, 0, 1));
        assertEquals(0, next.arrayWriteCalls, "no write may reach the next conduit after shutdown");
    }

    @Test
    void exceptionFromNextConduitPropagatesAndRestoresLimit() throws IOException {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.consumeLimit = 3; // write only the "3\r\n" header
        ChunkedStreamSinkConduit conduit = createConduit(next);

        assertEquals(0L, conduit.doWrite(new ByteBuffer[] { ByteBuffer.wrap(bytes("abc")) }, 0, 1));

        // The continuation path temporarily reduces the limit; a failure must still restore it.
        next.failOnWrite = true;
        ByteBuffer src = ByteBuffer.wrap(bytes("0123456789"));

        assertThrows(IOException.class, () -> conduit.doWrite(new ByteBuffer[] { src }, 0, 1));

        assertEquals(0, src.position(), "nothing should have been consumed");
        assertEquals(10, src.limit(), "the finally block must restore the original limit");
        assertEquals(10, src.remaining());
    }

