    /**
     * Test double that records the bytes handed to the wrapped conduit and can be told how many
     * bytes it should accept per write invocation.
     */
    private static final class RecordingSinkConduit implements StreamSinkConduit {

        final ByteArrayOutputStream wire = new ByteArrayOutputStream();
        long consumeLimit = Long.MAX_VALUE;
        int arrayWriteCalls;
        int singleWriteCalls;
        boolean failOnWrite;
        boolean flushResult = true;
        boolean writeShutdown;

        @Override
        public long write(ByteBuffer[] srcs, int offset, int length) throws IOException {
            arrayWriteCalls++;
            if (failOnWrite) {
                throw new IOException("simulated write failure");
            }
            long budget = consumeLimit;
            long consumed = 0;
            for (int i = 0; i < length && budget > 0; i++) {
                ByteBuffer buffer = srcs[offset + i];
                int n = (int) Math.min((long) buffer.remaining(), budget);
                for (int j = 0; j < n; j++) {
                    wire.write(buffer.get());
                }
                budget -= n;
                consumed += n;
            }
            return consumed;
        }

        @Override
        public int write(ByteBuffer src) throws IOException {
            singleWriteCalls++;
            if (failOnWrite) {
                throw new IOException("simulated write failure");
            }
            int n = (int) Math.min((long) src.remaining(), consumeLimit);
            for (int j = 0; j < n; j++) {
                wire.write(src.get());
            }
            return n;
        }

