        }

        @Override
        public void terminateWrites() {
            writeShutdown = true;
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }
    }

    private static final class SimpleBufferPool implements ByteBufferPool {

        @Override
        public PooledByteBuffer allocate() {
            return new ImmediatePooledByteBuffer(ByteBuffer.allocate(512));
