static final class RecordingSinkConduit implements StreamSinkConduit {
    final ByteArrayOutputStream wire = new ByteArrayOutputStream();
    long consumeLimit = Long.MAX_VALUE;
    int arrayWriteCalls;
    int singleWriteCalls;
    int flushCalls;
    boolean flushResult = true;
    boolean failOnWrite;
    boolean writeShutdown;
    boolean terminated;
    boolean truncated;

    @Override
    public long write(ByteBuffer[] srcs, int offset, int length) throws IOException {
        arrayWriteCalls++;
        if (failOnWrite) {
            throw new IOException("simulated failure");
        }
        long budget = consumeLimit;
        long consumed = 0;
        for (int i = 0; i < length && budget > 0; i++) {
            ByteBuffer buf = srcs[offset + i];
            int n = (int) Math.min((long) buf.remaining(), budget);
            for (int j = 0; j < n; j++) {
                wire.write(buf.get());
            }
            budget -= n;
            consumed += n;
        }
        return consumed;
    }

    @Override
    public int write(ByteBuffer src) throws IOException {
        singleWriteCalls++;
        if (failOnWrite) {
            throw new IOException("simulated failure");
        }
        int n = (int) Math.min((long) src.remaining(), consumeLimit);
        for (int j = 0; j < n; j++) {
            wire.write(src.get());
        }
        return n;
    }
    ...
}
