    final ByteArrayOutputStream written = new ByteArrayOutputStream();
    int writeLimit = Integer.MAX_VALUE; // max bytes consumed per write call
    boolean failWith; IOException...
    int writeFinalCalls, writeCalls, terminateWritesCalls, truncateWritesCalls;
    boolean writeShutdown;

    RecordingSink() { super(null); }

    @Override public int write(ByteBuffer src) throws IOException {
        writeCalls++;
        if (failure != null) throw failure;
        int n = Math.min(src.remaining(), writeLimit);
        byte[] b = new byte[n];
        src.get(b);
        written.write(b, 0, n);
        return n;
    }
    @Override public long write(ByteBuffer[] srcs, int off, int len) { loop over each calling write(srcs[i]) }
