    @Override public long writeFinal(ByteBuffer[] srcs, int off, int len) { writeFinalCalls++; long t=0; for... t+= write(srcs[i]) }
    @Override public void terminateWrites() { terminateWritesCalls++; writeShutdown = true; }
    @Override public void truncateWrites() { truncateWritesCalls++; }
    @Override public boolean flush() { flushCalls++; return true; }
    @Override public boolean isWriteShutdown() { return writeShutdown; }
