package io.undertow.conduits;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.ClosedChannelException;
import java.nio.charset.StandardCharsets;

import io.undertow.connector.ByteBufferPool;
import io.undertow.connector.PooledByteBuffer;
import io.undertow.util.AbstractAttachable;
import io.undertow.util.Attachable;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.ImmediatePooledByteBuffer;
import org.junit.jupiter.api.Test;
import org.xnio.conduits.AbstractStreamSinkConduit;
import org.xnio.conduits.StreamSinkConduit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link ChunkedStreamSinkConduit#doWrite(ByteBuffer)}.
 */
class ChunkedStreamSinkConduitDoWriteTests {

    private static final String CRLF = "\r\n";

    private RecordingSink sink;
    private HeaderMap responseHeaders;

    private ChunkedStreamSinkConduit createConduit(final boolean passClose) {
        sink = new RecordingSink();
        responseHeaders = new HeaderMap();
        responseHeaders.put(Headers.TRANSFER_ENCODING, Headers.CHUNKED);
        final Attachable attachable = new AbstractAttachable() {
        };
        return new ChunkedStreamSinkConduit(sink, new HeapBufferPool(), true, passClose, responseHeaders, null, attachable);
    }

    private ChunkedStreamSinkConduit createConduit() {
        return createConduit(false);
    }

    private static ByteBuffer buffer(final String data) {
        return ByteBuffer.wrap(data.getBytes(StandardCharsets.US_ASCII));
    }

    @Test
    void doWriteWritesChunkSizeInHexFollowedByDataAndCrlf() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        final ByteBuffer src = buffer("hello");

        final int result = conduit.doWrite(src);

        assertEquals(5, result);
        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteWritesChunkSizeForLargerPayloadInLowerCaseHex() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        final byte[] payload = new byte[300];
        for (int i = 0; i < payload.length; ++i) {
            payload[i] = (byte) ('a' + (i % 26));
        }
        final ByteBuffer src = ByteBuffer.wrap(payload);

        final int result = conduit.doWrite(src);

        assertEquals(300, result);
        final String expected = "12c" + CRLF + new String(payload, StandardCharsets.US_ASCII) + CRLF;
        assertEquals(expected, sink.outputAsString());
    }

    @Test
    void doWriteOnlyWritesRemainingBytesOfBufferAndRestoresLimit() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        final ByteBuffer src = ByteBuffer.wrap("xxhello".getBytes(StandardCharsets.US_ASCII));
        src.position(2);

        final int result = conduit.doWrite(src);

        assertEquals(5, result);
        assertEquals(7, src.position());
        assertEquals(7, src.limit());
        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteReturnsZeroForEmptyBufferWithoutWritingAnything() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        final ByteBuffer src = ByteBuffer.allocate(10);
        src.position(4);
        src.limit(4);

        final int result = conduit.doWrite(src);

        assertEquals(0, result);
        assertEquals(0, sink.totalBytesWritten());
        assertEquals(0, sink.writeCalls);
        assertEquals(0, sink.writeArrayCalls);
        assertEquals(4, src.position());
        assertEquals(4, src.limit());
    }

    @Test
    void emptyWriteDoesNotMarkFirstDataAsWritten() throws Exception {
        final ChunkedStreamSinkConduit conduit = createConduit(true);

        assertEquals(0, conduit.doWrite(ByteBuffer.allocate(0)));

        conduit.terminateWrites();

        // no chunk was ever written, so the transfer encoding is replaced by a zero content length
        assertEquals("0", responseHeaders.get(Headers.CONTENT_LENGTH));
        assertNull(responseHeaders.get(Headers.TRANSFER_ENCODING));
        assertEquals(0, sink.totalBytesWritten());
        assertTrue(sink.writeShutdown);
    }

    @Test
    void doWriteAfterTerminateWritesThrowsClosedChannelException() throws Exception {
        final ChunkedStreamSinkConduit conduit = createConduit();
        assertEquals(5, conduit.doWrite(buffer("hello")));

        conduit.terminateWrites();

        assertEquals("5" + CRLF + "hello" + CRLF + "0" + CRLF + CRLF, sink.outputAsString());
        assertNull(responseHeaders.get(Headers.CONTENT_LENGTH));
        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("again")));
    }

    @Test
    void doWriteStartsANewChunkForEveryBufferThatCompletesThePreviousChunk() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();

        assertEquals(5, conduit.doWrite(buffer("hello")));
        assertEquals(5, conduit.doWrite(buffer("world")));

        assertEquals("5" + CRLF + "hello" + CRLF + "5" + CRLF + "world" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteReturnsZeroWhenNextConduitAcceptsNothingAndRetriesAfterwards() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        sink.writeLimit = 0;
        final ByteBuffer src = buffer("hello");

        assertEquals(0, conduit.doWrite(src));
        assertEquals(0, src.position());
        assertEquals(0, sink.totalBytesWritten());

        sink.writeLimit = Integer.MAX_VALUE;
        assertEquals(5, conduit.doWrite(src));

        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteReturnsZeroWhenOnlyPartOfTheChunkHeaderIsWritten() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        sink.writeLimit = 1;
        final ByteBuffer src = buffer("hello");

        assertEquals(0, conduit.doWrite(src));
        assertEquals(0, src.position());
        assertEquals(5, src.limit());
        assertEquals("5", sink.outputAsString());

        sink.writeLimit = Integer.MAX_VALUE;
        assertEquals(5, conduit.doWrite(src));

        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteReturnsNumberOfSourceBytesWrittenWhenOnlyPartOfTheDataIsAccepted() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        sink.writeLimit = 5;
        final ByteBuffer src = buffer("hello world");

        // the three byte chunk header plus two bytes of data are accepted
        assertEquals(2, conduit.doWrite(src));
        assertEquals(2, src.position());
        assertEquals(11, src.limit());
        assertEquals("b" + CRLF + "he", sink.outputAsString());

        sink.writeLimit = Integer.MAX_VALUE;
        assertEquals(9, conduit.doWrite(src));

        assertFalse(src.hasRemaining());
        assertEquals("b" + CRLF + "hello world" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteOnlyConsumesRemainingChunkDataWhenSourceIsLargerThanCurrentChunk() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        sink.writeLimit = 3;

        // only the chunk header of the first chunk is accepted, so ten bytes are still owed
        assertEquals(0, conduit.doWrite(buffer("0123456789")));
        assertEquals("a" + CRLF, sink.outputAsString());

        sink.writeLimit = Integer.MAX_VALUE;
        final ByteBuffer next = buffer("0123456789abcdefghij");
        assertEquals(10, conduit.doWrite(next));

        // the source was limited to the outstanding chunk data and the limit was restored afterwards
        assertEquals(10, next.position());
        assertEquals(20, next.limit());
        assertEquals("a" + CRLF + "0123456789" + CRLF, sink.outputAsString());

        // the rest of the buffer is written as a new chunk
        assertEquals(10, conduit.doWrite(next));
        assertFalse(next.hasRemaining());
        assertEquals("a" + CRLF + "0123456789" + CRLF + "a" + CRLF + "abcdefghij" + CRLF, sink.outputAsString());
    }

    @Test
    void doWriteReturnsZeroWhenOnlyTheTrailingSeparatorIsOutstanding() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        // chunk header (3) + all five data bytes + a single separator byte
        sink.writeLimit = 9;
        final ByteBuffer src = buffer("hello");

        assertEquals(5, conduit.doWrite(src));
        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + "\r", sink.outputAsString());

        sink.writeLimit = Integer.MAX_VALUE;
        final ByteBuffer next = buffer("XY");
        assertEquals(0, conduit.doWrite(next));

        assertEquals(0, next.position());
        assertEquals(2, next.limit());
        assertEquals("5" + CRLF + "hello" + CRLF, sink.outputAsString());
    }

    @Test
    void doWritePropagatesIOExceptionFromNextConduitAndRestoresLimit() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit();
        final IOException failure = new IOException("write failed");
        sink.failure = failure;
        final ByteBuffer src = buffer("hello");

        final IOException thrown = assertThrows(IOException.class, () -> conduit.doWrite(src));

        assertSame(failure, thrown);
        assertEquals(0, src.position());
        assertEquals(5, src.limit());
    }

    @Test
    void writeFinalWritesTrailingChunkAndShutsDownWrites() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit(true);

        assertEquals(2, conduit.writeFinal(buffer("hi")));

        assertEquals(1, sink.writeFinalArrayCalls);
        assertEquals(0, sink.writeArrayCalls);
        assertEquals("2" + CRLF + "hi" + CRLF + "0" + CRLF + CRLF, sink.outputAsString());
        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("more")));
    }

    @Test
    void writeFinalWithoutPassCloseUsesRegularWrite() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit(false);

        assertEquals(2, conduit.writeFinal(buffer("hi")));

        assertEquals(0, sink.writeFinalArrayCalls);
        assertEquals(1, sink.writeArrayCalls);
        assertEquals("2" + CRLF + "hi" + CRLF + "0" + CRLF + CRLF, sink.outputAsString());
        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("more")));
    }

    @Test
    void doWriteInLastChunkModeReportsZeroUntilTheSourceIsWritten() throws IOException {
        final ChunkedStreamSinkConduit conduit = createConduit(true);
        final ByteBuffer src = buffer("hello");

        // create the trailing chunk but only allow the source chunk header to be written
        sink.writeLimit = 3;
        assertEquals(0, conduit.writeFinal(src));
        assertEquals(0, src.position());

        sink.writeLimit = Integer.MAX_VALUE;
        assertEquals(5, conduit.doWrite(src));

        assertFalse(src.hasRemaining());
        assertEquals("5" + CRLF + "hello" + CRLF + "0" + CRLF + CRLF, sink.outputAsString());
        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("more")));
    }

    /**
     * A heap based buffer pool which hands out immediate pooled buffers for the trailing chunk.
     */
    private static final class HeapBufferPool implements ByteBufferPool {

        @Override
        public PooledByteBuffer allocate() {
            return new ImmediatePooledByteBuffer(ByteBuffer.allocate(1024));
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return 1024;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    /**
     * A stream sink conduit that records everything that is written to it and that can be limited to accept
     * only a fixed number of bytes per write call.
     */
    private static final class RecordingSink extends AbstractStreamSinkConduit<StreamSinkConduit> {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        private int writeLimit = Integer.MAX_VALUE;
        private int remainingLimit = Integer.MAX_VALUE;
        private IOException failure;
        private boolean writeShutdown;
        private int writeCalls;
        private int writeArrayCalls;
        private int writeFinalCalls;
        private int writeFinalArrayCalls;

        RecordingSink() {
            super(null);
        }

        private int consume(final ByteBuffer buffer) throws IOException {
            if (failure != null) {
                throw failure;
            }
            final int count = Math.min(buffer.remaining(), remainingLimit);
            remainingLimit -= count;
            if (count > 0) {
                final byte[] bytes = new byte[count];
                buffer.get(bytes);
                written.write(bytes, 0, count);
            }
            return count;
        }

        private long consume(final ByteBuffer[] buffers, final int offset, final int length) throws IOException {
            long total = 0;
            for (int i = 0; i < length; ++i) {
                total += consume(buffers[offset + i]);
            }
            return total;
        }

        @Override
        public int write(final ByteBuffer src) throws IOException {
            writeCalls++;
            remainingLimit = writeLimit;
            return consume(src);
        }

        @Override
        public long write(final ByteBuffer[] srcs, final int offs, final int len) throws IOException {
            writeArrayCalls++;
            remainingLimit = writeLimit;
            return consume(srcs, offs, len);
        }

        @Override
        public int writeFinal(final ByteBuffer src) throws IOException {
            writeFinalCalls++;
            remainingLimit = writeLimit;
            return consume(src);
        }

        @Override
        public long writeFinal(final ByteBuffer[] srcs, final int offs, final int len) throws IOException {
            writeFinalArrayCalls++;
            remainingLimit = writeLimit;
            return consume(srcs, offs, len);
        }

        @Override
        public void terminateWrites() {
            writeShutdown = true;
        }

        @Override
        public void truncateWrites() {
        }

        @Override
        public boolean flush() {
            return true;
        }

        @Override
        public boolean isWriteShutdown() {
            return writeShutdown;
        }

        int totalBytesWritten() {
            return written.size();
        }

        String outputAsString() {
            return new String(written.toByteArray(), StandardCharsets.ISO_8859_1);
        }
    }
}
