/**
 * Tests for {@link DeflatingStreamSinkConduit#flush()}.
 */
public class DeflatingStreamSinkConduitFlushTests {

    private static final int DEFAULT_BUFFER_SIZE = 64;

    private DefaultByteBufferPool pool;
    private ServerConnection connection;
    private XnioIoThread ioThread;
    private HttpServerExchange exchange;
    private RecordingSinkConduit next;
    private int nextCreated;
    private DeflatingStreamSinkConduit conduit;

    private void init() throws Exception {
        init(DEFAULT_BUFFER_SIZE);
    }

    private void init(int bufferSize) throws Exception {
        pool = new DefaultByteBufferPool(false, bufferSize);
        ioThread = EasyMock.createNiceMock(XnioIoThread.class);
        connection = EasyMock.createNiceMock(ServerConnection.class);
        EasyMock.expect(connection.getByteBufferPool()).andReturn(pool).anyTimes();
        EasyMock.expect(connection.getIoThread()).andReturn(ioThread).anyTimes();
        EasyMock.replay(ioThread);
        EasyMock.replay(connection);
        exchange = new HttpServerExchange(connection);
        exchange.setRequestMethod(Methods.GET);
        next = new RecordingSinkConduit();
        nextCreated = 0;
        conduit = newConduit(next, null);
    }

    @AfterEach
    public void tearDown() {
        if (pool != null) {
            pool.close();
        }
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private DeflatingStreamSinkConduit newConduit(final RecordingSinkConduit sink, byte[] trailer) {
        ConduitFactory<StreamSinkConduit> factory = new ConduitFactory<StreamSinkConduit>() {
            @Override
            public StreamSinkConduit create() {
                nextCreated++;
                return sink;
            }
        };
        if (trailer == null) {
            return new DeflatingStreamSinkConduit(factory, exchange);
        }
        return new TrailerConduit(factory, exchange, trailer);
    }

    private static byte[] bytes(String value) {
        return value.getBytes(StandardCharsets.UTF_8);
    }

    private static byte[] inflate(byte[] data) {
        Inflater inflater = new Inflater(true);
        try {
            inflater.setInput(data);
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buffer = new byte[256];
            while (!inflater.finished()) {
                int count;
                try {
                    count = inflater.inflate(buffer);
                } catch (DataFormatException e) {
                    throw new AssertionError("Data written by the conduit is not a valid deflate stream", e);
                }
                if (count == 0) {
                    if (inflater.needsInput() || inflater.needsDictionary()) {
                        break;
                    }
                }
                out.write(buffer, 0, count);
            }
            return out.toByteArray();
        } finally {
            inflater.end();
        }
    }

    private static byte[] randomBytes(int size, long seed) {
        byte[] data = new byte[size];
        new Random(seed).nextBytes(data);
        return data;
    }

    private static byte[] tail(byte[] data, int length) {
        return Arrays.copyOfRange(data, data.length - length, data.length);
    }

    private static byte[] head(byte[] data, int length) {
        return Arrays.copyOfRange(data, 0, data.length - length);
    }

    // ------------------------------------------------------------------
    // flush() when the conduit is not shut down
    // ------------------------------------------------------------------

    @Test
    public void testFlushWithoutAnyDataCreatesNextAndFlushesSyncBlock() throws Exception {
        init();

        assertTrue(conduit.flush());

        assertEquals(1, nextCreated, "the next conduit must be created on the first flush");
        assertEquals(1, next.flushCalls, "next.flush() must be invoked once");
        assertEquals(0, next.terminateWritesCalls, "terminateWrites must not be invoked while not shut down");
        byte[] written = next.writtenBytes();
        assertTrue(written.length > 0, "a sync flush block must be written to the next conduit");
        assertEquals("", new String(inflate(written), StandardCharsets.UTF_8),
                "flushing without pending data must not produce payload bytes");
    }

    @Test
    public void testFlushWritesBufferedDataToNextConduit() throws Exception {
        init();

        int consumed = conduit.write(ByteBuffer.wrap(bytes("hello world")));
        assertEquals(11, consumed);
        assertEquals(0, next.writtenBytes().length, "data must stay in the buffer until flush is called");

        assertTrue(conduit.flush());

        assertEquals(1, nextCreated);
        assertEquals(1, next.flushCalls);
        assertEquals("hello world", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8));
    }

    @Test
    public void testFlushDeliversDataIncrementallyOverSeveralCalls() throws Exception {
        init();

        conduit.write(ByteBuffer.wrap(bytes("abc")));
        assertTrue(conduit.flush());
        assertEquals("abc", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8));

        conduit.write(ByteBuffer.wrap(bytes("def")));
        assertTrue(conduit.flush());
        assertEquals("abcdef", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8),
                "the buffer must have been reset after the previous flush");
        assertEquals(2, next.flushCalls);
        assertEquals(1, nextCreated);
    }

    @Test
    public void testFlushAfterWriteThatAlreadyOverflowedTheBuffer() throws Exception {
        init(16);

        byte[] payload = randomBytes(300, 3);
        assertEquals(payload.length, conduit.write(ByteBuffer.wrap(payload)));
        assertEquals(1, nextCreated, "the buffer overflow must have created the next conduit already");
        int flushCallsBefore = next.flushCalls;

        assertTrue(conduit.flush());

        assertEquals(1, nextCreated);
        assertEquals(flushCallsBefore + 1, next.flushCalls);
        assertArrayEquals(payload, inflate(next.writtenBytes()));
    }

    @Test
    public void testFlushReturnsFalseWhenNextFlushReturnsFalse() throws Exception {
        init();

        conduit.write(ByteBuffer.wrap(bytes("abc")));
        next.flushResult = false;

        assertFalse(conduit.flush(), "flush must report the result of next.flush()");
        assertEquals(1, next.flushCalls);
        assertEquals("abc", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8));

        next.flushResult = true;
        assertTrue(conduit.flush());
        assertEquals(2, next.flushCalls);
        assertEquals(1, nextCreated, "the next conduit must only be created once");
    }

    @Test
    public void testFlushReturnsFalseWhileNextRejectsDataAndCompletesLater() throws Exception {
        init();

        conduit.write(ByteBuffer.wrap(bytes("payload")));
        next.allowedWrites = 0;

        assertFalse(conduit.flush(), "flush must return false when the next conduit accepts no data");
        assertEquals(0, next.writtenBytes().length);
        assertEquals(0, next.flushCalls, "next.flush() must not be called while data is pending");

        next.allowedWrites = Integer.MAX_VALUE;
        assertTrue(conduit.flush());

        assertEquals("payload", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8));
        assertEquals(1, next.flushCalls);
        assertEquals(1, nextCreated);
    }

    @Test
