// flush() after terminateWrites()
// ------------------------------------------------------------------

@Test
public void testFlushAfterTerminateWritesFinishesDeflaterAndTerminatesNext() throws Exception {
    init();

    byte[] payload = bytes("response body");
    conduit.write(ByteBuffer.wrap(payload));
    conduit.terminateWrites();
    assertTrue(conduit.isWriteShutdown());

    assertTrue(conduit.flush());

    assertEquals(1, nextCreated);
    assertEquals(1, next.terminateWritesCalls, "the next conduit must be terminated after the final flush");
    assertEquals(1, next.flushCalls);
    assertArrayEquals(payload, inflate(next.writtenBytes()));
    assertNotNull(exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH),
            "content length must be set once the deflater is finished");
    assertEquals(String.valueOf(next.writtenBytes().length),
            exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
}

@Test
public void testFlushAfterCompleteShutdownDelegatesToNextFlush() throws Exception {
    init();

    conduit.write(ByteBuffer.wrap(bytes("body")));
    conduit.terminateWrites();
    assertTrue(conduit.flush());

    int flushCallsAfterFirstFlush = next.flushCalls;

    next.flushResult = false;
    assertFalse(conduit.flush(), "after a complete shutdown flush must delegate to next.flush()");
    assertEquals(flushCallsAfterFirstFlush + 1, next.flushCalls);
    assertEquals(1, next.terminateWritesCalls, "next must not be terminated a second time");

    next.flushResult = true;
    assertTrue(conduit.flush());
    assertEquals(flushCallsAfterFirstFlush + 2, next.flushCalls);
    assertEquals("body", new String(inflate(next.writtenBytes()), StandardCharsets.UTF_8));
}

@Test
public void testFlushWhileShutdownWithBlockedPendingBufferReturnsFalse() throws Exception {
    init(16);

    byte[] payload = randomBytes(70000, 7);
    next.allowedWrites = 3;
    int consumed = conduit.write(ByteBuffer.wrap(payload));
    assertTrue(consumed > 0, "some data must have been consumed before the buffer filled up");
    int writtenBefore = next.writtenBytes().length;
    assertTrue(writtenBefore > 0, "the full buffers must have been written during write()");
    conduit.terminateWrites();

    assertFalse(conduit.flush(), "flush must return false when the pending buffer cannot be written");
    assertEquals(writtenBefore, next.writtenBytes().length,
            "no extra data must be written while the next conduit is blocked");

    next.allowedWrites = Integer.MAX_VALUE;
    assertTrue(conduit.flush());
    assertArrayEquals(Arrays.copyOf(payload, consumed), inflate(next.writtenBytes()));
    assertEquals(1, next.terminateWritesCalls);
}

@Test
public void testFlushWhileShutdownReturnsFalseWhenFinishedBufferCannotBeWritten() throws Exception {
    init(16);

    byte[] payload = bytes("hello world");
    assertEquals(payload.length, conduit.write(ByteBuffer.wrap(payload)));
    conduit.terminateWrites();

    next.allowedWrites = 0;
    assertFalse(conduit.flush(),
            "flush must return false while the finished output buffer cannot be written");
    assertEquals(0, next.writtenBytes().length);
    assertEquals(0, next.terminateWritesCalls, "next must not be terminated before everything is written");

    next.allowedWrites = Integer.MAX_VALUE;
    assertTrue(conduit.flush());
    assertArrayEquals(payload, inflate(next.writtenBytes()));
    assertEquals(1, next.terminateWritesCalls);
    assertEquals(String.valueOf(next.writtenBytes().length),
            exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
}

@Test
public void testFlushWhileShutdownReturnsFalseWhenDeflaterCannotFinish() throws Exception {
    init(1);

    byte[] payload = bytes("aaaaaaaaaaaaaaaaaaaa");
    assertEquals(payload.length, conduit.write(ByteBuffer.wrap(payload)));

    conduit.terminateWrites();
    next.allowedWrites = 0;

    assertFalse(conduit.flush(),
            "flush must return false while the deflater has not been fully flushed");

    next.allowedWrites = Integer.MAX_VALUE;
    assertTrue(conduit.flush());
    assertArrayEquals(payload, inflate(next.writtenBytes()));
    assertEquals(1, next.terminateWritesCalls);
    assertEquals(1, next.flushCalls);
}

