    @Test
    public void testFlushPropagatesIOExceptionAndReleasesTheBuffer() throws Exception {
        init();

        conduit.write(ByteBuffer.wrap(bytes("data")));
        next.writeException = new IOException("boom");

        IOException exception = assertThrows(IOException.class, new Executable() {
            @Override
            public void execute() throws Throwable {
                conduit.flush();
            }
        });
        assertEquals("boom", exception.getMessage());

        next.writeException = null;
        int flushCallsBefore = next.flushCalls;
        int writtenBefore = next.writtenBytes().length;
        assertTrue(conduit.flush(), "once the buffer has been freed flush must succeed without touching next");
        assertEquals(flushCallsBefore, next.flushCalls);
        assertEquals(writtenBefore, next.writtenBytes().length);

        assertThrows(ClosedChannelException.class, new Executable() {
            @Override
            public void execute() throws Throwable {
                conduit.write(ByteBuffer.wrap(bytes("x")));
            }
        });
    }

