import org.xnio.XnioWorker;
import org.xnio.channels.StreamSourceChannel;
import org.xnio.conduits.StreamSinkConduit;
import org.xnio.conduits.WriteReadyHandler;

/**
 * Tests for {@link PreChunkedStreamSinkConduit#doWrite(ByteBuffer)}.
 */
public class PreChunkedStreamSinkConduitDoWriteTests {

    private static final int FLAG_WRITES_SHUTDOWN = 1;
    private static final String EXTRA_DATA_MESSAGE = "Attempted to write additional data after the last chunk";

    private static ByteBuffer buffer(final String data) {
        return ByteBuffer.wrap(data.getBytes(StandardCharsets.US_ASCII));
    }

    private static String drainToString(final ByteBuffer buffer) {
        ByteBuffer duplicate = buffer.duplicate();
        byte[] bytes = new byte[duplicate.remaining()];
        duplicate.get(bytes);
        return new String(bytes, StandardCharsets.US_ASCII);
    }

    private static PreChunkedStreamSinkConduit createConduit(final RecordingSinkConduit next,
                                                             final SimpleAttachable attachable) {
        return new PreChunkedStreamSinkConduit(next, null, attachable);
    }

    @Test
    public void doWriteThrowsClosedChannelExceptionWhenWritesAreShutdown() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        conduit.state = FLAG_WRITES_SHUTDOWN;

        ByteBuffer src = buffer("5\r\nhello\r\n");

        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(src));

        assertEquals(0, next.writeCalls, "underlying conduit must not be invoked after shutdown");
        assertEquals(0, src.position(), "source buffer must be left untouched");
        assertEquals(10, src.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteThrowsClosedChannelExceptionEvenWhenChunkStreamIsFinished() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        conduit.state = FLAG_WRITES_SHUTDOWN;
        // drive the chunk reader into the "finished" state as well
        assertEquals(-1L, conduit.chunkReader.readChunk(buffer("0\r\n\r\n")));
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());

        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("x")));
        assertEquals(0, next.writeCalls);
    }

    @Test
    public void doWriteThrowsExtraDataExceptionWhenChunkStreamAlreadyFinished() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        assertEquals(-1L, conduit.chunkReader.readChunk(buffer("0\r\n\r\n")));
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());

        // the "finished" check happens before the empty buffer check, so even an empty write fails
        ByteBuffer src = ByteBuffer.allocate(0);
        IOException exception = assertThrows(IOException.class, () -> conduit.doWrite(src));
        assertTrue(exception.getMessage().contains(EXTRA_DATA_MESSAGE),
                "unexpected message: " + exception.getMessage());
        assertEquals(0, next.writeCalls);
    }

    @Test
    public void doWriteReturnsZeroForEmptySourceWithoutCallingUnderlyingConduit() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = ByteBuffer.allocate(8);
        src.position(3);
        src.limit(3);

        assertEquals(0, conduit.doWrite(src));
        assertEquals(0, next.writeCalls, "no write should be attempted for an empty buffer");
        assertEquals(3, src.position());
        assertEquals(3, src.limit());
        assertEquals("", next.writtenText());
    }

    @Test
    public void doWriteWritesSingleChunkAndReturnsNumberOfBytesWritten() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        String payload = "5\r\nhello\r\n";
        ByteBuffer src = buffer(payload);

        int ret = conduit.doWrite(src);

        assertEquals(payload.length(), ret);
        assertEquals(1, next.writeCalls);
        assertEquals(payload, next.writtenText(), "the whole buffer must be passed through to the underlying conduit");
        assertEquals(payload.length(), src.position(), "buffer must be fully consumed on success");
        assertEquals(payload.length(), src.limit(), "buffer limit must be restored on success");
        assertEquals(0L, conduit.chunkReader.getChunkRemaining(), "chunk data was fully consumed");
    }

    @Test
    public void doWriteParsesMultipleChunksIncludingTerminatingChunk() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        SimpleAttachable attachable = new SimpleAttachable();
        PreChunkedStreamSinkConduit conduit = createConduit(next, attachable);

        String payload = "1\r\na\r\n2\r\nbc\r\n0\r\n\r\n";
        ByteBuffer src = buffer(payload);

        int ret = conduit.doWrite(src);

        assertEquals(payload.length(), ret);
        assertEquals(payload, next.writtenText());
        assertEquals(payload.length(), src.position());
        assertEquals(payload.length(), src.limit());
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining(), "the terminating chunk must be recognized");
        assertNull(attachable.getAttachment(HttpAttachments.RESPONSE_TRAILERS),
                "no trailers were sent, so no attachment should be created");
    }

    @Test
    public void doWriteStopsAtChunkBoundaryWhenChunkDataIsSplitAcrossBuffers() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer first = buffer("4\r\nab");
        int firstRet = conduit.doWrite(first);
        assertEquals(6, firstRet);
        assertEquals("4\r\nab", next.writtenText());
        assertEquals(6, first.position());
        assertEquals(6, first.limit());
        assertEquals(2L, conduit.chunkReader.getChunkRemaining(),
                "two bytes of the declared chunk are still outstanding");

        ByteBuffer second = buffer("cd\r\n");
        int secondRet = conduit.doWrite(second);
        assertEquals(4, secondRet);
        assertEquals("4\r\nabcd\r\n", next.writtenText());
        assertEquals(4, second.position());
        assertEquals(4, second.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteReturnsPartialCountAndRestoresBufferState() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.maxBytesPerWrite = 4;
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("5\r\nhello\r\n");

        int ret = conduit.doWrite(src);

        assertEquals(4, ret);
        assertEquals("5\r\nh", next.writtenText());
        assertEquals(4, src.position(), "position must be advanced by the number of bytes written");
        assertEquals(10, src.limit(), "limit must be restored to its original value");
        assertEquals(4L, conduit.chunkReader.getChunkRemaining(),
                "the remainder of the declared chunk must be tracked");
    }

    @Test
    public void doWriteHandlesPartialChunkDataWithinWrittenRegion() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.maxBytesPerWrite = 7;
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("5\r\nhello\r\n");
        int ret = conduit.doWrite(src);
        assertEquals(7, ret);
        assertEquals("5\r\nhell", next.writtenText());
        assertEquals(7, src.position());
        assertEquals(10, src.limit());
        assertEquals(1L, conduit.chunkReader.getChunkRemaining());

        // the rest of the chunk plus its trailing CRLF must be parsed on the follow up write
        int secondRet = conduit.doWrite(src);
        assertEquals(3, secondRet);
        assertEquals("5\r\nhello\r\n", next.writtenText());
        assertEquals(10, src.position());
        assertEquals(10, src.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteReturnsZeroWhenUnderlyingConduitWritesNothing() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        next.writeReturnsZero = true;
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("5\r\nhello\r\n");

        assertEquals(0, conduit.doWrite(src));
        assertEquals(1, next.writeCalls);
        assertEquals(0, src.position(), "buffer must be untouched when nothing was written");
        assertEquals(10, src.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining(),
                "chunk parsing state is unchanged, so nothing is reported as remaining");
    }

    @Test
    public void doWriteThrowsWhenExtraDataFollowsTheLastChunkInTheSameBuffer() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        String payload = "0\r\n\r\nXYZ";
        ByteBuffer src = buffer(payload);

        IOException exception = assertThrows(IOException.class, () -> conduit.doWrite(src));
        assertTrue(exception.getMessage().contains(EXTRA_DATA_MESSAGE),
                "unexpected message: " + exception.getMessage());
        assertEquals(payload, next.writtenText());
        assertEquals(payload.length(), src.position(),
                "position must be reset to the end of the written region even on failure");
        assertEquals(payload.length(), src.limit(), "limit must be restored even on failure");
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteHandlesIncompleteChunkSizeLineAndContinuesOnNextWrite() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer first = buffer("5");
        assertEquals(1, conduit.doWrite(first));
        assertEquals("5", next.writtenText());
        assertEquals(1, first.position());
        assertEquals(1, first.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining(),
                "an unfinished chunk size line reports nothing remaining");

        ByteBuffer second = buffer("\r\nhello\r\n");
        assertEquals(9, conduit.doWrite(second));
        assertEquals("5\r\nhello\r\n", next.writtenText());
        assertEquals(9, second.position());
        assertEquals(9, second.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteStoresTrailersInTheResponseTrailerAttachment() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        SimpleAttachable attachable = new SimpleAttachable();
        PreChunkedStreamSinkConduit conduit = createConduit(next, attachable);

        String payload = "0\r\nX-Foo: bar\r\n\r\n";
        ByteBuffer src = buffer(payload);

        int ret = conduit.doWrite(src);

        assertEquals(payload.length(), ret);
        assertEquals(payload, next.writtenText());
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());

        HeaderMap trailers = attachable.getAttachment(HttpAttachments.RESPONSE_TRAILERS);
        assertNotNull(trailers, "parsed trailers must be attached to the attachable");
        assertEquals("bar", trailers.getFirst("X-Foo"));
    }

    @Test
    public void doWritePropagatesExceptionFromUnderlyingConduit() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        IOException failure = new IOException("boom");
        next.failure = failure;
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("5\r\nhello\r\n");

        IOException thrown = assertThrows(IOException.class, () -> conduit.doWrite(src));
        assertSame(failure, thrown);
        assertEquals(1, next.writeCalls);
        assertEquals(0, src.position(), "buffer state must not change when the delegate fails first");
        assertEquals(10, src.limit());
    }

    @Test
    public void doWriteDoesNotReportRemainingBytesForCompleteChunk() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("3\r\nabc\r\n");
        assertEquals(8, conduit.doWrite(src));
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
        assertFalse(src.hasRemaining());
        assertEquals("", drainToString(src), "no bytes should be left in the source buffer");

        // further writes start a new chunk
        ByteBuffer nextChunk = buffer("1\r\nz\r\n");
        assertEquals(6, conduit.doWrite(nextChunk));
        assertEquals("3\r\nabc\r\n1\r\nz\r\n", next.writtenText());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    /**
     * Minimal {@link Attachable} backed by a map.
     */
    private static final class SimpleAttachable implements Attachable {

        private final Map<AttachmentKey<?>, Object> attachments = new HashMap<>();

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getAttachment(final AttachmentKey<T> key) {
            return (T) attachments.get(key);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> List<T> getAttachmentList(final AttachmentKey<? extends List<T>> key) {
            List<T> list = (List<T>) attachments.get(key);
            return list == null ? java.util.Collections.emptyList() : list;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T putAttachment(final AttachmentKey<T> key, final T value) {
            if (value == null) {
                return (T) attachments.remove(key);
            }
            return (T) attachments.put(key, value);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T removeAttachment(final AttachmentKey<T> key) {
            return (T) attachments.remove(key);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> void addToAttachmentList(final AttachmentKey<AttachmentList<T>> key, final T value) {
            AttachmentList<T> list = (AttachmentList<T>) attachments.get(key);
            if (list == null) {
                list = new AttachmentList<>(Object.class);
                attachments.put(key, list);
            }
            list.add(value);
        }
    }

    /**
     * Recording {@link StreamSinkConduit} that consumes (at most {@link #maxBytesPerWrite}) bytes from the
     * source buffer and remembers everything it was given.
     */
    private static final class RecordingSinkConduit implements StreamSinkConduit {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        int writeCalls;
        int maxBytesPerWrite = Integer.MAX_VALUE;
        boolean writeReturnsZero;
        IOException failure;
        private boolean writeShutdown;

        String writtenText() {
            return new String(written.toByteArray(), StandardCharsets.US_ASCII);
        }

        @Override
        public int write(final ByteBuffer src) throws IOException {
            writeCalls++;
            if (failure != null) {
                throw failure;
            }
            if (writeReturnsZero) {
                return 0;
            }
            int count = Math.min(src.remaining(), maxBytesPerWrite);
            if (count <= 0) {
                return 0;
            }
            byte[] bytes = new byte[count];
            src.get(bytes);
            written.write(bytes, 0, count);
            return count;
        }

        @Override
        public long write(final ByteBuffer[] srcs, final int offset, final int length) {
            throw new UnsupportedOperationException();
        }

        @Override
        public int writeFinal(final ByteBuffer src) {
            throw new UnsupportedOperationException();
        }

        @Override
        public long writeFinal(final ByteBuffer[] srcs, final int offset, final int length) {
            throw new UnsupportedOperationException();
        }

        @Override
        public long transferFrom(final FileChannel src, final long position, final long count) {
            throw new UnsupportedOperationException();
        }

        @Override
        public long transferFrom(final StreamSourceChannel source, final long count, final ByteBuffer throughBuffer) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void terminateWrites() {
            writeShutdown = true;
        }

        @Override
        public boolean isWriteShutdown() {
            return writeShutdown;
        }

        @Override
