        @SuppressWarnings("unchecked")
        public <T> void addToAttachmentList(final AttachmentKey<AttachmentList<T>> key, final T value) {
            AttachmentList<T> list = (AttachmentList<T>) attachments.get(key);
            if (list == null) {
                list = new AttachmentList<>(Object.class);
                attachments.put(key, list);
            }
            list.add(value);
        }
    }

