    public void doWriteDoesNotReportRemainingBytesForCompleteChunk() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = buffer("3\r\nabc\r\n");
        assertEquals(8, conduit.doWrite(src));
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
        assertFalse(src.hasRemaining());
        assertEquals("", drainToString(src), "no bytes should be left in the source buffer");

        // further writes start a new chunk
        ByteBuffer nextChunk = buffer("1\r\nz\r\n");
        assertEquals(6, conduit.doWrite(nextChunk));
        assertEquals("3\r\nabc\r\n1\r\nz\r\n", next.writtenText());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

