class AsyncSenderImplSendTests {

    private HttpServerExchange exchange;
    private ServerConnection connection;
    private HeaderMap responseHeaders;

    private HttpServerExchange newExchange(final boolean connectionOpen, final boolean responseComplete, final long contentLength) {
        exchange = mock(HttpServerExchange.class);
        connection = mock(ServerConnection.class);
        responseHeaders = new HeaderMap();

        expect(exchange.getConnection()).andReturn(connection).anyTimes();
        expect(connection.isOpen()).andReturn(connectionOpen).anyTimes();
        expect(exchange.isResponseComplete()).andReturn(responseComplete).anyTimes();
        expect(exchange.getResponseContentLength()).andReturn(contentLength).anyTimes();
        expect(exchange.getResponseHeaders()).andReturn(responseHeaders).anyTimes();
        return exchange;
    }

    /**
     * Creates a channel whose single-buffer write consumes at most {@code chunkSize} bytes.
     */
    private static StreamSinkChannel channelConsumingAtMost(final int chunkSize, final AtomicInteger writeCalls) {
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        expect(channel.write(anyObject(ByteBuffer.class))).andAnswer(() -> {
            writeCalls.incrementAndGet();
            final ByteBuffer buffer = (ByteBuffer) getCurrentArguments()[0];
            final int written = Math.min(chunkSize, buffer.remaining());
            buffer.position(buffer.position() + written);
            return written;
        }).anyTimes();
        return channel;
    }

    private static void expectGatheringWriteConsumesAll(final StreamSinkChannel channel, final AtomicInteger writeCalls) {
        expect(channel.write(anyObject(ByteBuffer[].class), anyInt(), anyInt())).andAnswer(() -> {
            writeCalls.incrementAndGet();
            final Object[] arguments = getCurrentArguments();
            final ByteBuffer[] buffers = (ByteBuffer[]) arguments[0];
            final int offset = (Integer) arguments[1];
            final int length = (Integer) arguments[2];
            long total = 0;
            for (int i = offset; i < offset + length; i++) {
                final ByteBuffer buffer = buffers[i];
                total += buffer.remaining();
                buffer.position(buffer.limit());
            }
            return total;
        }).anyTimes();
    }

    private static ByteBuffer bytes(final int... values) {
        final byte[] data = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            data[i] = (byte) values[i];
        }
        return ByteBuffer.wrap(data);
    }

    @Test
    void nullCallbackIsRejectedBeforeAnyExchangeInteraction() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        replay(exchange, connection);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);

        final IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> sender.send(bytes(1), null));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("callback"), exception.getMessage());
        verify(exchange, connection);
    }

    @Test
    void closedConnectionIsReportedAsClosedChannelException() {
        final HttpServerExchange exchange = newExchange(false, false, -1);
        replay(exchange, connection);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3);

        sender.send(buffer, callback);

        assertEquals(1, callback.exceptionCount);
        assertEquals(0, callback.completeCount);
        assertTrue(callback.exception instanceof ClosedChannelException,
                "Expected ClosedChannelException but got " + callback.exception);
        assertSame(exchange, callback.exceptionExchange);
        assertSame(sender, callback.exceptionSender);
        assertEquals(3, buffer.remaining());
        verify(exchange, connection);
    }

    @Test
    void responseAlreadyCompleteIsReportedButCurrentImplementationContinuesWriting() {
        final HttpServerExchange exchange = newExchange(true, true, -1);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(Integer.MAX_VALUE, writes);
        expect(exchange.getResponseChannel()).andReturn(channel).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(9, 8);

        sender.send(buffer, callback);

        assertEquals(1, callback.exceptionCount);
        assertTrue(callback.exception instanceof IOException);
        assertTrue(callback.exception.getMessage().contains("Response has already been sent"),
                callback.exception.getMessage());
        assertEquals(1, callback.completeCount);
        assertEquals(1, writes.get());
        assertFalse(buffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    @Test
    void sendingWhileDataIsAlreadyQueuedThrowsIllegalStateException() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        final ChannelListener.SimpleSetter<StreamSinkChannel> writeSetter = new ChannelListener.SimpleSetter<>();

        expect(exchange.getResponseChannel()).andReturn(channel).once();
        expect(channel.write(anyObject(ByteBuffer.class))).andReturn(0).once();
        expect(channel.getWriteSetter()).andReturn(writeSetter).once();
        channel.resumeWrites();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback firstCallback = new RecordingCallback();
        final RecordingCallback secondCallback = new RecordingCallback();

        sender.send(bytes(1, 2, 3), firstCallback);
        assertEquals(0, firstCallback.completeCount);
        assertEquals(0, firstCallback.exceptionCount);
        assertNotNull(writeSetter.get());

        final IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> sender.send(bytes(4), secondCallback));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("already being sent"), exception.getMessage());
        assertEquals(0, secondCallback.completeCount);
        assertEquals(0, secondCallback.exceptionCount);
        verify(exchange, connection, channel);
    }

    @Test
    void bufferLargerThanDeclaredContentLengthIsReportedThroughCallback() {
        final HttpServerExchange exchange = newExchange(true, false, 3);
        replay(exchange, connection);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3, 4);

        sender.send(buffer, callback);

        assertEquals(1, callback.exceptionCount);
        assertEquals(0, callback.completeCount);
        assertTrue(callback.exception instanceof IOException);
        assertTrue(callback.exception.getMessage().contains("Attempted to write 4 bytes"),
                callback.exception.getMessage());
        assertTrue(callback.exception.getMessage().contains("3"), callback.exception.getMessage());
        assertEquals(4, buffer.remaining());
        verify(exchange, connection);
    }

    @Test
    void bufferExactlyMatchingContentLengthIsAccepted() {
        final HttpServerExchange exchange = newExchange(true, false, 5);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(Integer.MAX_VALUE, writes);
        expect(exchange.getResponseChannel()).andReturn(channel).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = ByteBuffer.allocate(7);
        buffer.position(2); // remaining() is 5, matching the content length
        buffer.limit(7);

        sender.send(buffer, callback);

        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertEquals(1, writes.get());
        assertFalse(buffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    @Test
    void zeroDeclaredContentLengthDoesNotRejectNonEmptyBuffer() {
        final HttpServerExchange exchange = newExchange(true, false, 0);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(Integer.MAX_VALUE, writes);
        expect(exchange.getResponseChannel()).andReturn(channel).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2);

        sender.send(buffer, callback);

        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertEquals(1, writes.get());
        verify(exchange, connection, channel);
    }

