        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertSame(exchange, callback.completeExchange);
        assertSame(sender, callback.completeSender);
        assertEquals(1, writes.get());
        assertFalse(buffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    @Test
    void partialWritesAreRetriedUntilBufferIsDrained() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(2, writes);
        expect(exchange.getResponseChannel()).andReturn(channel).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3, 4);

        sender.send(buffer, callback);

        assertEquals(2, writes.get());
        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertFalse(buffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    @Test
    void zeroLengthWriteQueuesBufferAndWriteListenerCompletesIt() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        final ChannelListener.SimpleSetter<StreamSinkChannel> writeSetter = new ChannelListener.SimpleSetter<>();
        final AtomicInteger singleWrites = new AtomicInteger();
        final AtomicInteger gatheringWrites = new AtomicInteger();

        expect(exchange.getResponseChannel()).andReturn(channel).once();
        expect(channel.write(anyObject(ByteBuffer.class))).andAnswer(() -> {
            singleWrites.incrementAndGet();
            return 0;
        }).once();
        expect(channel.getWriteSetter()).andReturn(writeSetter).once();
        channel.resumeWrites();
        expectGatheringWriteConsumesAll(channel, gatheringWrites);
        channel.suspendWrites();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3, 4);

        sender.send(buffer, callback);

        assertEquals(1, singleWrites.get());
        assertEquals(0, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertEquals(4, buffer.remaining());
        assertNotNull(writeSetter.get(), "write listener should be registered");

        @SuppressWarnings("unchecked")
        final ChannelListener<StreamSinkChannel> listener =
                (ChannelListener<StreamSinkChannel>) writeSetter.get();
        listener.handleEvent(channel);

        assertEquals(1, gatheringWrites.get());
        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertFalse(buffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    @Test
    void ioExceptionFromWriteIsReportedThroughCallback() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        final IOException failure = new IOException("write failed");
        expect(exchange.getResponseChannel()).andReturn(channel).once();
        expect(channel.write(anyObject(ByteBuffer.class))).andThrow(failure).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();

        sender.send(bytes(1, 2), callback);

        assertEquals(1, callback.exceptionCount);
        assertEquals(0, callback.completeCount);
        assertSame(failure, callback.exception);
        assertSame(exchange, callback.exceptionExchange);
        assertSame(sender, callback.exceptionSender);
        verify(exchange, connection, channel);
    }

    @Test
    void secondSendReusesThePreviouslyAcquiredResponseChannel() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(Integer.MAX_VALUE, writes);
        expect(exchange.getResponseChannel()).andReturn(channel).once();

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback firstCallback = new RecordingCallback();
        final RecordingCallback secondCallback = new RecordingCallback();
        final ByteBuffer firstBuffer = bytes(1);
        final ByteBuffer secondBuffer = bytes(2, 3);

        sender.send(firstBuffer, firstCallback);
        sender.send(secondBuffer, secondCallback);

        assertEquals(1, firstCallback.completeCount);
        assertEquals(1, secondCallback.completeCount);
        assertEquals(0, firstCallback.exceptionCount);
        assertEquals(0, secondCallback.exceptionCount);
        assertEquals(2, writes.get());
        assertFalse(firstBuffer.hasRemaining());
        assertFalse(secondBuffer.hasRemaining());
        verify(exchange, connection, channel);
    }

