    @Test
    void sendFromWithinCompletionCallbackIsQueuedAndFlushed() {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        final AtomicInteger singleWrites = new AtomicInteger();
        final AtomicInteger gatheringWrites = new AtomicInteger();

        expect(exchange.getResponseChannel()).andReturn(channel).once();
        expect(channel.write(anyObject(ByteBuffer.class))).andAnswer(() -> {
            singleWrites.incrementAndGet();
            final ByteBuffer buffer = (ByteBuffer) getCurrentArguments()[0];
            final int remaining = buffer.remaining();
            buffer.position(buffer.limit());
            return remaining;
        }).once();
        expectGatheringWriteConsumesAll(channel, gatheringWrites);

        replay(exchange, connection, channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback firstCallback = new RecordingCallback();
        final RecordingCallback secondCallback = new RecordingCallback();
        final ByteBuffer firstBuffer = bytes(1, 2, 3);
        final ByteBuffer secondBuffer = bytes(4, 5);

        firstCallback.onCompleteAction = () -> sender.send(secondBuffer, secondCallback);

        sender.send(firstBuffer, firstCallback);

        assertEquals(1, firstCallback.completeCount);
        assertEquals(1, secondCallback.completeCount);
        assertEquals(0, firstCallback.exceptionCount);
        assertEquals(0, secondCallback.exceptionCount);
        assertEquals(1, singleWrites.get());
        assertEquals(1, gatheringWrites.get());
        assertFalse(firstBuffer.hasRemaining());
        assertFalse(secondBuffer.hasRemaining());
        verify(exchange, connection, channel);
    }

    private static final class RecordingCallback implements IoCallback {

        private int completeCount;
        private int exceptionCount;
        private HttpServerExchange completeExchange;
        private Sender completeSender;
        private HttpServerExchange exceptionExchange;
        private Sender exceptionSender;
        private IOException exception;
        private Runnable onCompleteAction;

        @Override
        public void onComplete(final HttpServerExchange exchange, final Sender sender) {
            completeCount++;
            completeExchange = exchange;
            completeSender = sender;
            if (onCompleteAction != null) {
                onCompleteAction.run();
            }
        }

        @Override
        public void onException(final HttpServerExchange exchange, final Sender sender, final IOException exception) {
            exceptionCount++;
            exceptionExchange = exchange;
            exceptionSender = sender;
            this.exception = exception;
        }
    }
