        sender.send(buffer, callback);

        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertSame(exchange, callback.completeExchange);
        assertSame(sender, callback.completeSender);
        assertEquals(1, writes.get());
        assertFalse(buffer.hasRemaining());
        verify(exchange).getResponseChannel();
        verify(channel).write(any(ByteBuffer.class));
    }

    @Test
    void partialWritesAreRetriedUntilBufferIsDrained() throws IOException {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(2, writes);
        when(exchange.getResponseChannel()).thenReturn(channel);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3, 4);

        sender.send(buffer, callback);

        assertEquals(2, writes.get());
        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertFalse(buffer.hasRemaining());
        verify(exchange).getResponseChannel();
    }

    @Test
    void zeroLengthWriteQueuesBufferAndWriteListenerCompletesIt() throws IOException {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        final ChannelListener.SimpleSetter<StreamSinkChannel> writeSetter = new ChannelListener.SimpleSetter<>();
        final AtomicInteger singleWrites = new AtomicInteger();
        final AtomicInteger gatheringWrites = new AtomicInteger();

        when(exchange.getResponseChannel()).thenReturn(channel);
        when(channel.write(any(ByteBuffer.class))).thenAnswer(invocation -> {
            singleWrites.incrementAndGet();
            return 0;
        });
        stubWriteSetter(channel, writeSetter);
        stubGatheringWriteConsumesAll(channel, gatheringWrites);

        final AsyncSenderImpl sender = new AsyncSenderImpl(exchange);
        final RecordingCallback callback = new RecordingCallback();
        final ByteBuffer buffer = bytes(1, 2, 3, 4);

        sender.send(buffer, callback);

        assertEquals(1, singleWrites.get());
        assertEquals(0, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertEquals(4, buffer.remaining());
        assertNotNull(writeSetter.get(), "write listener should be registered");
        verify(channel).resumeWrites();

        @SuppressWarnings("unchecked")
        final ChannelListener<StreamSinkChannel> listener =
                (ChannelListener<StreamSinkChannel>) writeSetter.get();
        listener.handleEvent(channel);

        assertEquals(1, gatheringWrites.get());
        assertEquals(1, callback.completeCount);
        assertEquals(0, callback.exceptionCount);
        assertFalse(buffer.hasRemaining());
        verify(channel).suspendWrites();
        verify(channel).write(any(ByteBuffer[].class), anyInt(), anyInt());
    }

    @Test
    void ioExceptionFromWriteIsReportedThroughCallback() throws IOException {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
