    @Test
    void partialWritesAreRetriedUntilBufferIsDrained() throws IOException {
        final HttpServerExchange exchange = newExchange(true, false, -1);
        final AtomicInteger writes = new AtomicInteger();
        final StreamSinkChannel channel = channelConsumingAtMost(2, writes);
