        private final List<IOException> exceptions = new ArrayList<>();
        private Runnable onCompleteAction;

        @Override
        public void onComplete(HttpServerExchange exchange, Sender sender) {
            completed.add(exchange);
            senders.add(sender);
            Runnable action = onCompleteAction;
            if (action != null) {
