            for (int i = offset; i < end && count < budget; i++) {
                ByteBuffer src = srcs[i];
                int toWrite = (int) Math.min(src.remaining(), budget - count);
                if (toWrite > 0) {
                    byte[] bytes = new byte[toWrite];
                    src.get(bytes);
                    written.write(bytes, 0, toWrite);
                    count += toWrite;
                }
            }
            totalWritten += count;
            return count;
        }

