    private static final class TestSinkChannel implements StreamSinkChannel {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        private long maxBytesPerWrite = Long.MAX_VALUE;
        private long zeroWritesAfterTotalBytes = Long.MAX_VALUE;
        private long totalWritten;
        private int writeInvocations;
        private IOException failure;
        private boolean writeResumed;
        private int resumeWritesInvocations;
        private int suspendWritesInvocations;
        private ChannelListener<? super StreamSinkChannel> writeListener;
        private ChannelListener<? super StreamSinkChannel> closeListener;

        private final ChannelListener.Setter<StreamSinkChannel> writeSetter = new ChannelListener.Setter<StreamSinkChannel>() {
            @Override
            public void set(ChannelListener<? super StreamSinkChannel> listener) {
                writeListener = listener;
            }
        };

        private final ChannelListener.Setter<StreamSinkChannel> closeSetter = new ChannelListener.Setter<StreamSinkChannel>() {
            @Override
            public void set(ChannelListener<? super StreamSinkChannel> listener) {
                closeListener = listener;
            }
        };

        @SuppressWarnings("unchecked")
        void fireWriteEvent() throws IOException {
            ChannelListener<? super StreamSinkChannel> listener = writeListener;
            assertNotNull(listener, "no write listener registered");
            ((ChannelListener<StreamSinkChannel>) listener).handleEvent(this);
        }

        String writtenAsString() {
            return new String(written.toByteArray(), StandardCharsets.UTF_8);
        }

        private long doWrite(ByteBuffer[] srcs, int offset, int length) throws IOException {
            writeInvocations++;
            if (failure != null) {
                throw failure;
            }
            long budget = Math.min(maxBytesPerWrite, zeroWritesAfterTotalBytes - totalWritten);
            if (budget <= 0) {
                return 0;
            }
            long count = 0;
            int end = offset + length;
            for (int i = offset; i < end && count < budget; i++) {
                ByteBuffer src = srcs[i];
                int toWrite = (int) Math.min(src.remaining(), budget - count);
                if (toWrite > 0) {
                    byte[] bytes = new byte[toWrite];
                    src.get(bytes);
                    written.write(bytes, 0, toWrite);
                    count += toWrite;
                }
            }
            totalWritten += count;
            return count;
        }

        @Override
        public int write(ByteBuffer src) throws IOException {
            return (int) doWrite(new ByteBuffer[]{src}, 0, 1);
        }

        @Override
        public long write(ByteBuffer[] srcs) throws IOException {
            return doWrite(srcs, 0, srcs.length);
        }

        @Override
        public long write(ByteBuffer[] srcs, int offset, int length) throws IOException {
            return doWrite(srcs, offset, length);
        }

        @Override
