    private static final class RecordingCallback implements IoCallback {

        private final List<HttpServerExchange> completed = new ArrayList<>();
        private final List<Sender> senders = new ArrayList<>();
        private final List<IOException> exceptions = new ArrayList<>();
        private Runnable onCompleteAction;

        @Override
        public void onComplete(HttpServerExchange exchange, Sender sender) {
            completed.add(exchange);
            senders.add(sender);
            Runnable action = onCompleteAction;
            if (action != null) {
                onCompleteAction = null;
                action.run();
            }
        }

        @Override
        public void onException(HttpServerExchange exchange, Sender sender, IOException exception) {
            exceptions.add(exception);
        }
    }

