/**
 * Unit tests for {@link BlockingReceiverImpl#receiveFullString(Receiver.FullStringCallback, Receiver.ErrorCallback, Charset)}.
 */
public class BlockingReceiverImplReceiveFullStringTests {

    /**
     * Value of {@code HttpServerExchange.FLAG_REQUEST_TERMINATED}; used to simulate an already
     * fully read request.
     */
    private static final int FLAG_REQUEST_TERMINATED = 1 << 12;

    private static final int POOL_BUFFER_SIZE = 256;

    private TestServerConnection connection;
    private TrackingByteBufferPool pool;
    private HttpServerExchange exchange;
    private RecordingFullStringCallback callback;
    private RecordingErrorCallback errorCallback;

    @BeforeEach
    void setUp() {
        pool = new TrackingByteBufferPool(POOL_BUFFER_SIZE);
        connection = new TestServerConnection(pool);
        exchange = new HttpServerExchange(connection);
        callback = new RecordingFullStringCallback();
        errorCallback = new RecordingErrorCallback();
    }

    // ------------------------------------------------------------------
    // happy paths
    // ------------------------------------------------------------------

    @Test
    void successfulReadInvokesCallbackWithBodyAndNoError() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        BlockingReceiverImpl receiver = receiver("hello", StandardCharsets.ISO_8859_1);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(1, callback.messages.size(), "callback should be invoked exactly once");
        assertEquals("hello", callback.messages.get(0));
        assertSame(exchange, callback.exchanges.get(0), "the current exchange must be passed to the callback");
        assertTrue(errorCallback.errors.isEmpty(), "error callback must not be invoked on success");
    }

    @Test
    void bodyLargerThanThePooledBufferIsFullyAccumulated() {
        StringBuilder body = new StringBuilder();
        for (int i = 0; i < POOL_BUFFER_SIZE * 5; i++) {
            body.append((char) ('a' + (i % 26)));
        }
        String expected = body.toString();
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Integer.toString(expected.length()));
        BlockingReceiverImpl receiver = new BlockingReceiverImpl(exchange,
                new ByteArrayInputStream(expected.getBytes(StandardCharsets.ISO_8859_1)));

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(1, callback.messages.size());
        assertEquals(expected, callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void bodyIsDecodedUsingTheSuppliedCharset() {
        String body = "h\u00e9llo \u00fc";
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Integer.toString(bytes.length));
        BlockingReceiverImpl receiver = new BlockingReceiverImpl(exchange, new ByteArrayInputStream(bytes));

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.UTF_8);

        assertEquals(body, callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void sameBytesDecodedAsIso88591DifferFromUtf8() {
        String body = "\u00e9\u00e9";
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Integer.toString(bytes.length));

        BlockingReceiverImpl receiver = new BlockingReceiverImpl(exchange, new ByteArrayInputStream(bytes));
        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(new String(bytes, StandardCharsets.ISO_8859_1), callback.messages.get(0));
        assertEquals(4, callback.messages.get(0).length());
    }

    @Test
    void emptyBodyWithZeroContentLengthInvokesCallbackWithEmptyString() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "0");
        BlockingReceiverImpl receiver = receiver("", StandardCharsets.ISO_8859_1);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(1, callback.messages.size());
        assertEquals("", callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void bodyIsReadToEndEvenWhenContentLengthIsSmallerThanTheActualBody() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "2");
        BlockingReceiverImpl receiver = receiver("abcdef", StandardCharsets.ISO_8859_1);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals("abcdef", callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    // ------------------------------------------------------------------
    // request complete short circuit
    // ------------------------------------------------------------------

    @Test
    void alreadyCompleteRequestInvokesCallbackWithEmptyStringWithoutReading() {
        markRequestTerminated();
        CountingInputStream stream = new CountingInputStream("ignored");

        new BlockingReceiverImpl(exchange, stream).receiveFullString(callback, errorCallback,
                StandardCharsets.ISO_8859_1);

        assertEquals(1, callback.messages.size());
        assertEquals("", callback.messages.get(0));
        assertEquals(0, stream.readCalls, "the request body must not be read when the request is already complete");
        assertEquals(0, pool.allocations, "no buffer should be allocated when the request is already complete");
        assertTrue(errorCallback.errors.isEmpty());
    }

    // ------------------------------------------------------------------
    // header handling
    // ------------------------------------------------------------------

    @Test
    void xContentLengthOnlyIsPromotedToContentLengthUsingDecodedCharacterCount() {
        String body = "h\u00e9llo";
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.getRequestHeaders().put(Headers.X_CONTENT_LENGTH, Integer.toString(bytes.length));

        new BlockingReceiverImpl(exchange, new ByteArrayInputStream(bytes))
                .receiveFullString(callback, errorCallback, StandardCharsets.UTF_8);

        assertEquals(body, callback.messages.get(0));
        assertEquals("5", exchange.getRequestHeaders().getFirst(Headers.CONTENT_LENGTH),
                "CONTENT_LENGTH should be derived from the decoded character count");
    }

    @Test
    void existingContentLengthIsNotOverwrittenWhenXContentLengthIsAlsoPresent() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "6");
        exchange.getRequestHeaders().put(Headers.X_CONTENT_LENGTH, "6");
        byte[] bytes = "h\u00e9llo".getBytes(StandardCharsets.UTF_8);

        new BlockingReceiverImpl(exchange, new ByteArrayInputStream(bytes))
                .receiveFullString(callback, errorCallback, StandardCharsets.UTF_8);

        assertEquals("h\u00e9llo", callback.messages.get(0));
        assertEquals("6", exchange.getRequestHeaders().getFirst(Headers.CONTENT_LENGTH));
    }

    @Test
    void noContentLengthHeadersMeansNoContentLengthHeaderIsAdded() {
        BlockingReceiverImpl receiver = receiver("abc", StandardCharsets.ISO_8859_1);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals("abc", callback.messages.get(0));
        assertFalse(exchange.getRequestHeaders().contains(Headers.CONTENT_LENGTH));
        assertFalse(exchange.getRequestHeaders().contains(Headers.X_CONTENT_LENGTH));
    }

    @Test
    void nonNumericContentLengthIsRejectedWithNumberFormatException() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "not-a-number");
        CountingInputStream stream = new CountingInputStream("abc");

        assertThrows(NumberFormatException.class,
                () -> new BlockingReceiverImpl(exchange, stream)
                        .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1));

        assertTrue(callback.messages.isEmpty());
        assertTrue(errorCallback.errors.isEmpty(), "the error callback is not used for a NumberFormatException");
        assertEquals(0, stream.readCalls);
    }

    // ------------------------------------------------------------------
    // size limits
    // ------------------------------------------------------------------

    @Test
    void contentLengthAboveIntegerMaxValueIsReportedAsTooLarge() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Long.toString((long) Integer.MAX_VALUE + 1));
        CountingInputStream stream = new CountingInputStream("abc");

        new BlockingReceiverImpl(exchange, stream)
                .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty(), "the success callback must not be invoked");
        assertEquals(1, errorCallback.errors.size());
        assertTrue(errorCallback.errors.get(0) instanceof Receiver.RequestToLargeException,
                "expected a RequestToLargeException but got " + errorCallback.errors.get(0));
        assertEquals(0, stream.readCalls);
        assertEquals(0, pool.allocations);
    }

    @Test
    void contentLengthAboveMaxBufferSizeIsReportedAsTooLarge() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "11");
        CountingInputStream stream = new CountingInputStream("0123456789A");
        BlockingReceiverImpl receiver = new BlockingReceiverImpl(exchange, stream);
        receiver.setMaxBufferSize(10);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty());
        assertEquals(1, errorCallback.errors.size());
        assertTrue(errorCallback.errors.get(0) instanceof Receiver.RequestToLargeException);
        assertEquals(0, stream.readCalls);
    }

    @Test
    void contentLengthEqualToMaxBufferSizeIsAccepted() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "10");
        BlockingReceiverImpl receiver = receiver("0123456789", StandardCharsets.ISO_8859_1);
        receiver.setMaxBufferSize(10);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals("0123456789", callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void maxBufferSizeIsIgnoredWhenContentLengthIsUnknown() {
        BlockingReceiverImpl receiver = receiver("0123456789", StandardCharsets.ISO_8859_1);
        receiver.setMaxBufferSize(4);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals("0123456789", callback.messages.get(0),
                "without a content length header the size is not known up front so the limit is not applied");
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void defaultMaxBufferSizeDoesNotRestrictLargeContentLength() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Long.toString(2L * 1024 * 1024));
        BlockingReceiverImpl receiver = receiver("abc", StandardCharsets.ISO_8859_1);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals("abc", callback.messages.get(0));
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void xContentLengthAboveMaxBufferSizeIsReportedAsTooLarge() {
        exchange.getRequestHeaders().put(Headers.X_CONTENT_LENGTH, "11");
        BlockingReceiverImpl receiver = receiver("0123456789A", StandardCharsets.ISO_8859_1);
        receiver.setMaxBufferSize(10);

        receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty());
        assertEquals(1, errorCallback.errors.size());
        assertTrue(errorCallback.errors.get(0) instanceof Receiver.RequestToLargeException);
    }

    // ------------------------------------------------------------------
    // argument validation and state
    // ------------------------------------------------------------------

    @Test
    void nullCallbackIsRejectedWithIllegalArgumentException() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> receiver("abc", StandardCharsets.ISO_8859_1)
                        .receiveFullString(null, errorCallback, StandardCharsets.ISO_8859_1));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("callback"),
                "unexpected message: " + exception.getMessage());
        assertTrue(errorCallback.errors.isEmpty());
    }

    @Test
    void receiverThatWasAlreadyReadRejectsAnotherRead() throws Exception {
        BlockingReceiverImpl receiver = receiver("abc", StandardCharsets.ISO_8859_1);
        setDone(receiver);

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> receiver.receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().toLowerCase().contains("already"),
                "unexpected message: " + exception.getMessage());
        assertTrue(callback.messages.isEmpty());
        assertTrue(errorCallback.errors.isEmpty());
    }

    // ------------------------------------------------------------------
    // error handling
    // ------------------------------------------------------------------

    @Test
    void ioExceptionFromTheInputStreamIsPassedToTheErrorCallback() {
        final IOException failure = new IOException("boom");
        InputStream failing = new InputStream() {
            @Override
            public int read() throws IOException {
                throw failure;
            }
        };

        new BlockingReceiverImpl(exchange, failing)
                .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty());
        assertEquals(1, errorCallback.errors.size());
        assertSame(failure, errorCallback.errors.get(0),
                "the original IOException must be handed to the error callback");
    }

    @Test
    void pooledBufferIsReleasedAfterAnIoFailure() {
        InputStream failing = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("boom");
            }
        };

        new BlockingReceiverImpl(exchange, failing)
                .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(1, pool.allocations);
        assertEquals(1, pool.closes, "the pooled buffer must be closed even when reading fails");
    }

    @Test
    void pooledBufferIsReleasedAfterASuccessfulRead() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");

        receiver("hello", StandardCharsets.ISO_8859_1)
                .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertEquals(1, pool.allocations);
        assertEquals(1, pool.closes, "the pooled buffer must be closed after a successful read");
    }

    @Test
    void allocationFailureIsReportedThroughTheErrorCallback() {
        pool.returnNullBuffer = true;

        receiver("abc", StandardCharsets.ISO_8859_1)
                .receiveFullString(callback, errorCallback, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty());
        assertEquals(1, errorCallback.errors.size());
        IOException error = errorCallback.errors.get(0);
        assertFalse(error instanceof Receiver.RequestToLargeException);
        assertTrue(error.getMessage().toLowerCase().contains("allocat"),
                "unexpected message: " + error.getMessage());
    }

    @Test
    void nullErrorCallbackEndsTheExchangeWithServerError() {
        exchange.getRequestHeaders().put(Headers.CONTENT_LENGTH, Long.toString((long) Integer.MAX_VALUE + 1));

        receiver("abc", StandardCharsets.ISO_8859_1)
                .receiveFullString(callback, null, StandardCharsets.ISO_8859_1);

        assertTrue(callback.messages.isEmpty(), "the success callback must not be invoked");
        assertEquals(500, exchange.getStatusCode(), "the default error callback sets a 500 status");
        assertFalse(exchange.isPersistent(), "the default error callback makes the connection non persistent");
        assertTrue(exchange.isComplete(), "the default error callback ends the exchange");
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private BlockingReceiverImpl receiver(String body, Charset charset) {
        return new BlockingReceiverImpl(exchange, new ByteArrayInputStream(body.getBytes(charset)));
    }

    private void markRequestTerminated() {
        try {
            Field state = HttpServerExchange.class.getDeclaredField("state");
            state.setAccessible(true);
            state.setInt(exchange, state.getInt(exchange) | FLAG_REQUEST_TERMINATED);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException(e);
        }
    }

    private static void setDone(BlockingReceiverImpl receiver) throws Exception {
        Field done = BlockingReceiverImpl.class.getDeclaredField("done");
        done.setAccessible(true);
        done.setBoolean(receiver, true);
    }

    private static final class RecordingFullStringCallback implements Receiver.FullStringCallback {
        final List<String> messages = new ArrayList<>();
        final List<HttpServerExchange> exchanges = new ArrayList<>();

        @Override
        public void handle(HttpServerExchange exchange, String message) {
            exchanges.add(exchange);
            messages.add(message);
        }
    }

    private static final class RecordingErrorCallback implements Receiver.ErrorCallback {
        final List<IOException> errors = new ArrayList<>();

        @Override
        public void error(HttpServerExchange exchange, IOException e) {
            errors.add(e);
        }
    }

    private static final class CountingInputStream extends InputStream {
        private final byte[] data;
        private int position;
        int readCalls;

        CountingInputStream(String value) {
            this.data = value.getBytes(StandardCharsets.ISO_8859_1);
        }

        @Override
        public int read() {
            readCalls++;
            if (position == data.length) {
                return -1;
            }
            return data[position++] & 0xFF;
        }

        @Override
        public int read(byte[] b, int off, int len) {
            readCalls++;
            if (position == data.length) {
                return -1;
            }
            int count = Math.min(len, data.length - position);
            System.arraycopy(data, position, b, off, count);
            position += count;
            return count;
        }
    }

    /**
     * A byte buffer pool that can be configured to fail allocations and that tracks allocation/close counts.
     */
    private static final class TrackingByteBufferPool implements ByteBufferPool {

        private final DefaultByteBufferPool delegate;
        int allocations;
        int closes;
        boolean returnNullBuffer;

        TrackingByteBufferPool(int bufferSize) {
            this.delegate = new DefaultByteBufferPool(false, bufferSize);
        }

        @Override
        public PooledByteBuffer allocate() {
            allocations++;
            if (returnNullBuffer) {
                return null;
            }
            final PooledByteBuffer pooled = delegate.allocate();
            return new PooledByteBuffer() {
                @Override
                public ByteBuffer getBuffer() {
                    return pooled.getBuffer();
                }

                @Override
                public void close() {
                    closes++;
                    pooled.close();
                }

                @Override
                public boolean isOpen() {
                    return pooled.isOpen();
                }
            };
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
            delegate.close();
        }

        @Override
        public int getBufferSize() {
            return delegate.getBufferSize();
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

