class BlockingReceiverImplReceivePartialStringTests {

    private static final Charset ISO_8859_1 = StandardCharsets.ISO_8859_1;

    private HttpServerExchange exchange;
    private ServerConnection connection;
    private HeaderMap requestHeaders;
    private DefaultByteBufferPool bufferPool;
    private RecordingStringCallback callback;
    private RecordingErrorCallback errorCallback;

    @BeforeEach
    void setUp() {
        exchange = mock(HttpServerExchange.class);
        connection = mock(ServerConnection.class);
        requestHeaders = new HeaderMap();
        bufferPool = new DefaultByteBufferPool(false, 1024);
        when(exchange.getRequestHeaders()).thenReturn(requestHeaders);
        when(exchange.getConnection()).thenReturn(connection);
        when(exchange.isRequestComplete()).thenReturn(false);
        when(connection.getByteBufferPool()).thenReturn(bufferPool);
        callback = new RecordingStringCallback();
        errorCallback = new RecordingErrorCallback();
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    // ------------------------------------------------------------------
    // argument validation / state guard
    // ------------------------------------------------------------------

    @Test
    void nullCallbackThrowsIllegalArgumentException() {
        final BlockingReceiverImpl receiver = receiver(new byte[] { 1, 2, 3 });

        final IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> receiver.receivePartialString(null, errorCallback, ISO_8859_1));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("callback"), exception.getMessage());
        assertTrue(callback.calls.isEmpty());
        assertTrue(errorCallback.errors.isEmpty());
        verify(exchange, never()).isRequestComplete();
        verify(connection, never()).getByteBufferPool();
    }

    @Test
    void nullCallbackWithNullErrorCallbackStillThrowsIllegalArgumentException() {
        final BlockingReceiverImpl receiver = receiver(new byte[] { 1, 2, 3 });

        final IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> receiver.receivePartialString(null, null, ISO_8859_1));

        assertTrue(exception.getMessage().contains("callback"), exception.getMessage());
        verify(exchange, never()).isRequestComplete();
    }

    @Test
    void readingBodyTwiceThrowsIllegalStateException() throws Exception {
        final BlockingReceiverImpl receiver = receiver("payload".getBytes(ISO_8859_1));
        markDone(receiver);

        final IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> receiver.receivePartialString(callback, errorCallback, ISO_8859_1));

        assertNotNull(exception.getMessage());
        assertTrue(callback.calls.isEmpty());
        assertTrue(errorCallback.errors.isEmpty());
        verify(exchange, never()).isRequestComplete();
        verify(connection, never()).getByteBufferPool();
    }

    @Test
    void alreadyReadCheckTakesPrecedenceOverNullCallbackCheck() throws Exception {
        final BlockingReceiverImpl receiver = receiver(new byte[] { 1 });
        markDone(receiver);

        assertThrows(IllegalStateException.class,
                () -> receiver.receivePartialString(null, errorCallback, ISO_8859_1));

        assertTrue(errorCallback.errors.isEmpty());
    }

