    @Test
    void completeRequestDeliversOnlyFinalEmptyChunk() {
        when(exchange.isRequestComplete()).thenReturn(true);
        final BlockingReceiverImpl receiver = receiver(new ThrowingInputStream());

        receiver.receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals(1, callback.calls.size());
        assertEquals("", callback.messages.get(0));
        assertEquals(Boolean.TRUE, callback.lastFlags.get(0));
        assertSame(exchange, callback.exchanges.get(0), "callback must receive the exchange");
        assertTrue(errorCallback.errors.isEmpty());
        verify(connection, never()).getByteBufferPool();
    }

    @Test
    void completeRequestDoesNotConsultContentLengthHeaders() {
        when(exchange.isRequestComplete()).thenReturn(true);
        requestHeaders.put(Headers.CONTENT_LENGTH, Long.toString(Integer.MAX_VALUE + 1L));

