    @Test
    void deliversWholeBodyThenFinalEmptyChunk() {
        final byte[] body = "Hello, Undertow!".getBytes(ISO_8859_1);

        receiver(body).receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals("Hello, Undertow!", callback.joined());
        assertEquals("", callback.lastMessage());
        assertEquals(1, callback.finalCallCount(), "exactly one chunk must be marked as the last one");
        assertEquals(callback.calls.size() - 1, callback.lastFlagIndex(),
                "the final empty chunk must be the last callback invocation");
        assertTrue(errorCallback.errors.isEmpty());
        for (HttpServerExchange seen : callback.exchanges) {
            assertSame(exchange, seen, "callback must receive the exchange");
        }
    }

