        receiver(body.getBytes(ISO_8859_1)).receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals(body, callback.joined());
        assertTrue(callback.calls.size() > 2,
                "a body larger than the pooled buffer must be split, got " + callback.calls.size() + " chunk(s)");
        assertEquals("", callback.lastMessage());
        assertEquals(1, callback.finalCallCount());
        assertTrue(errorCallback.errors.isEmpty());
        for (int i = 0; i < callback.calls.size() - 1; i++) {
            assertFalse(callback.lastFlags.get(i), "non final chunks must not be flagged as last");
