        receiver.receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals(1, errorCallback.errors.size());
        assertSame(failure, errorCallback.errors.get(0));
        assertSame(exchange, errorCallback.exchanges.get(0));
        assertTrue(callback.calls.isEmpty());
