    void chunksDeliveredBeforeFailureAreKeptAndNoFinalChunkIsSent() {
        final IOException failure = new IOException("boom");
        final BlockingReceiverImpl receiver = receiver(new InputStream() {
            private int invocations;

            @Override
            public int read() {
                throw new AssertionError("single byte read is not expected");
            }

            @Override
            public int read(final byte[] b, final int off, final int len) throws IOException {
                if (invocations++ == 0) {
                    b[off] = (byte) 'a';
                    return 1;
