        receiver.receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals(1, callback.calls.size());
        assertEquals("a", callback.messages.get(0));
        assertEquals(Boolean.FALSE, callback.lastFlags.get(0));
        assertEquals(1, errorCallback.errors.size());
        assertSame(failure, errorCallback.errors.get(0));
    }

    @Test
    void allocationFailureIsReportedToErrorCallback() {
        final ByteBufferPool pool = mock(ByteBufferPool.class);
        when(pool.getArrayBackedPool()).thenReturn(pool);
        when(connection.getByteBufferPool()).thenReturn(pool);
        final BlockingReceiverImpl receiver = receiver("abc".getBytes(ISO_8859_1));

        receiver.receivePartialString(callback, errorCallback, ISO_8859_1);

        assertEquals(1, errorCallback.errors.size());
        final IOException error = errorCallback.errors.get(0);
        assertNotNull(error.getMessage());
