@Timeout(30)
class UndertowOutputStreamWriteTests {

    private static final int BUFFER_SIZE = 16;

    /** A length of zero is a no-op and must not even look at the exchange. */
    @Test
    void writeWithZeroLengthIsIgnored() throws IOException {
        HttpServerExchange exchange = createStrictMock(HttpServerExchange.class);
        expect(exchange.getResponseContentLength()).andReturn(-1L);
        replay(exchange);

        UndertowOutputStream stream = new UndertowOutputStream(exchange);
        stream.write(new byte[] { 1, 2, 3, 4 }, 1, 0);

        assertEquals(0, stream.getBytesWritten());
        verify(exchange);
    }

    /** A negative length is a no-op and must not even look at the exchange. */
    @Test
    void writeWithNegativeLengthIsIgnored() throws IOException {
        HttpServerExchange exchange = createStrictMock(HttpServerExchange.class);
        expect(exchange.getResponseContentLength()).andReturn(10L);
        replay(exchange);

        UndertowOutputStream stream = new UndertowOutputStream(exchange);
        stream.write(new byte[] { 1, 2, 3, 4 }, 0, -3);

        assertEquals(0, stream.getBytesWritten());
        verify(exchange);
    }

    /** Blocking IO from an IO thread is rejected before anything is buffered. */
    @Test
    void writeFromIoThreadIsRejected() {
        Environment env = new Environment(-1, BUFFER_SIZE, true);

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> env.stream.write(payload(4, 0), 0, 4));

        assertTrue(exception.getMessage().contains("UT000126"), exception.getMessage());
        assertTrue(exception.getMessage().contains("blocking IO from the IO thread"), exception.getMessage());
        assertEquals(0, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.isEmpty(), "no buffer may be allocated when the write is rejected");
        assertEquals(0, env.recorder.receivedBytes().length);
    }

    /** Once the stream is closed every write is rejected. */
    @Test
    void writeOnClosedStreamIsRejected() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] data = payload(5, 7);
        env.stream.write(data, 0, 5);
        env.stream.close();
        assertEquals(5, env.stream.getBytesWritten());
        assertEquals(5, env.recorder.receivedBytes().length);

        IOException exception = assertThrows(IOException.class,
                () -> env.stream.write(payload(2, 0), 0, 2));

        assertTrue(exception.getMessage().contains("UT000034"), exception.getMessage());
        assertEquals(5, env.stream.getBytesWritten(), "a rejected write must not be counted");
        assertEquals(5, env.recorder.receivedBytes().length, "a rejected write must not reach the channel");
    }

    /** Data that fits into the buffer stays buffered (only the requested slice is copied). */
    @Test
    void writeThatFitsIsBufferedAndHonoursOffsetAndLength() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] data = payload(10, 3);

        env.stream.write(data, 2, 5);

        assertEquals(5, env.stream.getBytesWritten());
        assertEquals(0, env.recorder.receivedBytes().length, "the data must stay in the stream buffer");
        assertEquals(1, env.pool.allocated.size(), "exactly one buffer is allocated for the stream");

        env.stream.close();

        assertArrayEquals(Arrays.copyOfRange(data, 2, 7), env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown, "the channel is shut down when the stream is closed");
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A write that fills the buffer up completely flushes it to the channel. */
    @Test
    void writeThatFillsTheBufferFlushesIt() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] first = payload(BUFFER_SIZE, 0);
        byte[] second = payload(4, 90);

        env.stream.write(first, 0, BUFFER_SIZE);

        assertArrayEquals(first, env.recorder.receivedBytes());
        assertFalse(env.recorder.shutdown, "a full buffer must not shut the channel down");
        assertEquals(BUFFER_SIZE, env.stream.getBytesWritten());

        env.stream.write(second, 0, 4);

        assertEquals(BUFFER_SIZE, env.recorder.receivedBytes().length, "the second write must still be buffered");
        assertEquals(BUFFER_SIZE + 4, env.stream.getBytesWritten());

        env.stream.close();

        assertArrayEquals(concatenate(first, second), env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown);
        assertAllPooledBuffersClosed(env.pool);
    }

