        UndertowOutputStream stream = new UndertowOutputStream(exchange);
        stream.write(new byte[] { 1, 2, 3, 4 }, 1, 0);

        assertEquals(0, stream.getBytesWritten());
        verify(exchange);
    }

    /** A negative length is a no-op and must not even look at the exchange. */
