    void writeWithNegativeLengthIsIgnored() throws IOException {
        HttpServerExchange exchange = createStrictMock(HttpServerExchange.class);
        expect(exchange.getResponseContentLength()).andReturn(10L);
        replay(exchange);

        UndertowOutputStream stream = new UndertowOutputStream(exchange);
        stream.write(new byte[] { 1, 2, 3, 4 }, 0, -3);

        assertEquals(0, stream.getBytesWritten());
        verify(exchange);
    }

