        byte[] data = payload(10, 3);

        env.stream.write(data, 2, 5);

        assertEquals(5, env.stream.getBytesWritten());
        assertEquals(0, env.recorder.receivedBytes().length, "the data must stay in the stream buffer");
        assertEquals(1, env.pool.allocated.size(), "exactly one buffer is allocated for the stream");

        env.stream.close();

        assertArrayEquals(Arrays.copyOfRange(data, 2, 7), env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown, "the channel is shut down when the stream is closed");
