        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] data = payload(100, 0);

        env.stream.write(data, 0, 100);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertEquals(100, env.stream.getBytesWritten());
        assertFalse(env.recorder.shutdown, "an unknown content length must not close the stream");
        assertTrue(env.pool.allocated.size() > 1, "the payload does not fit into a single buffer");
        assertTrue(env.pool.allocated.size() <= 11, "at most MAX_BUFFERS_TO_ALLOCATE buffers are used");
        assertScratchBuffersClosed(env.pool);
    }

