        assertArrayEquals(Arrays.copyOfRange(data, 2, 7), env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown, "the channel is shut down when the stream is closed");
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A write that fills the buffer up completely flushes it to the channel. */
    @Test
    void writeThatFillsTheBufferFlushesIt() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] first = payload(BUFFER_SIZE, 0);
        byte[] second = payload(4, 90);

        env.stream.write(first, 0, BUFFER_SIZE);

        assertArrayEquals(first, env.recorder.receivedBytes());
        assertFalse(env.recorder.shutdown, "a full buffer must not shut the channel down");
        assertEquals(BUFFER_SIZE, env.stream.getBytesWritten());

        env.stream.write(second, 0, 4);

        assertEquals(BUFFER_SIZE, env.recorder.receivedBytes().length, "the second write must still be buffered");
        assertEquals(BUFFER_SIZE + 4, env.stream.getBytesWritten());

        env.stream.close();

        assertArrayEquals(concatenate(first, second), env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown);
        assertAllPooledBuffersClosed(env.pool);
    }

    /** Closing a stream that only holds buffered data publishes the buffered length. */
    @Test
    void closePublishesTheBufferedContentLength() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        env.stream.write(payload(3, 1), 0, 3);

        env.stream.close();

        assertEquals("3", env.headers.getFirst(Headers.CONTENT_LENGTH));
        assertEquals(3, env.recorder.receivedBytes().length);
    }

    /** Writing the final content-length sized chunk flushes and closes the stream. */
    @Test
    void writeOfLastChunkWithContentLengthClosesTheStream() throws IOException {
        Environment env = new Environment(4, BUFFER_SIZE, false);
        byte[] data = payload(4, 11);

        env.stream.write(data, 0, 4);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown, "the stream closes itself once the content length is written");
        assertEquals(4, env.stream.getBytesWritten());
        assertNull(env.headers.getFirst(Headers.CONTENT_LENGTH),
                "the content length header must not be rewritten after the response started");

        IOException exception = assertThrows(IOException.class, () -> env.stream.write(payload(1, 0), 0, 1));
        assertTrue(exception.getMessage().contains("UT000034"), exception.getMessage());
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A non final chunk of a content-length response is buffered without closing the stream. */
    @Test
    void intermediateChunkWithContentLengthStaysBuffered() throws IOException {
        Environment env = new Environment(10, BUFFER_SIZE, false);
        byte[] data = payload(10, 21);

        env.stream.write(data, 0, 4);

        assertEquals(4, env.stream.getBytesWritten());
        assertEquals(0, env.recorder.receivedBytes().length);
        assertFalse(env.recorder.shutdown);

        env.stream.write(data, 4, 6);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown);
        assertEquals(10, env.stream.getBytesWritten());
    }

    /** A write larger than the buffer is spread over several buffers and written at once. */
    @Test
    void writeLargerThanTheBufferUsesAdditionalBuffers() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] data = payload(100, 0);

        env.stream.write(data, 0, 100);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertEquals(100, env.stream.getBytesWritten());
        assertFalse(env.recorder.shutdown, "an unknown content length must not close the stream");
        assertTrue(env.pool.allocated.size() > 1, "the payload does not fit into a single buffer");
        assertTrue(env.pool.allocated.size() <= 11, "at most MAX_BUFFERS_TO_ALLOCATE buffers are used");
        assertScratchBuffersClosed(env.pool);
    }

    /** Payloads larger than all scratch buffers are written by re-using the buffers. */
    @Test
    void writeMuchLargerThanTheBuffersReusesThem() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        byte[] data = payload(400, 5);

        env.stream.write(data, 0, 400);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertEquals(400, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.size() <= 11,
                "buffers are re-used instead of allocating one buffer per chunk, allocated: "
                        + env.pool.allocated.size());
        assertScratchBuffersClosed(env.pool);
    }

    /** The final content-length chunk is written together with the still buffered data. */
    @Test
    void writeOfLastChunkLargerThanTheBufferFlushesPreviousDataToo() throws IOException {
        Environment env = new Environment(100, BUFFER_SIZE, false);
        byte[] data = payload(100, 0);

        env.stream.write(data, 0, 10);
        assertEquals(0, env.recorder.receivedBytes().length, "the first chunk must stay buffered");

        env.stream.write(data, 10, 90);

        assertArrayEquals(data, env.recorder.receivedBytes());
        assertTrue(env.recorder.shutdown, "the response is complete after the last chunk");
        assertEquals(100, env.stream.getBytesWritten());
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A failing channel is reported to the caller and no byte is accounted for. */
    @Test
    void channelFailureIsPropagated() {
        Environment env = new Environment(-1, BUFFER_SIZE, false);
        IOException failure = new IOException("write failed");
        env.recorder.failure = failure;

        IOException exception = assertThrows(IOException.class,
                () -> env.stream.write(payload(BUFFER_SIZE, 0), 0, BUFFER_SIZE));

        assertEquals("write failed", exception.getMessage());
        assertEquals(0, env.stream.getBytesWritten(), "a failed write must not be counted");
    }

    /** The single byte convenience method funnels through the array based write. */
    @Test
    void singleByteWriteReachesTheChannel() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE, false);

        env.stream.write(0x41);

        assertEquals(1, env.stream.getBytesWritten());

        env.stream.close();

        assertArrayEquals(new byte[] { 0x41 }, env.recorder.receivedBytes());
    }

    private static void assertAllPooledBuffersClosed(TestByteBufferPool pool) {
        for (TestPooledBuffer pooled : pool.allocated) {
            assertFalse(pooled.isOpen(), "pooled buffer was not returned to the pool");
        }
    }

    private static void assertScratchBuffersClosed(TestByteBufferPool pool) {
        // the first allocated buffer belongs to the stream itself, the others are scratch buffers
        for (int i = 1; i < pool.allocated.size(); ++i) {
            assertFalse(pool.allocated.get(i).isOpen(), "scratch buffer " + i + " was not returned to the pool");
        }
    }

    private static byte[] payload(final int length, final int seed) {
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; ++i) {
            bytes[i] = (byte) (seed + i);
        }
        return bytes;
    }

    private static byte[] concatenate(final byte[] first, final byte[] second) {
        byte[] result = Arrays.copyOf(first, first.length + second.length);
        System.arraycopy(second, 0, result, first.length, second.length);
        return result;
    }

    /**
     * Collects the exchange, its connection, the buffer pool and the channel used by a stream.
     */
    private static final class Environment {

        private final TestByteBufferPool pool;
        private final RecordingChannel recorder;
        private final HeaderMap headers = new HeaderMap();
        private final HttpServerExchange exchange;
        private final UndertowOutputStream stream;

        private Environment(final long contentLength, final int bufferSize, final boolean inIoThread) {
            this.pool = new TestByteBufferPool(bufferSize);
            this.recorder = new RecordingChannel();

            ServerConnection connection = createNiceMock(ServerConnection.class);
            expect(connection.getByteBufferPool()).andReturn(pool).anyTimes();

            this.exchange = createNiceMock(HttpServerExchange.class);
            expect(exchange.getResponseContentLength()).andReturn(contentLength).anyTimes();
            expect(exchange.isInIoThread()).andReturn(inIoThread).anyTimes();
            expect(exchange.getConnection()).andReturn(connection).anyTimes();
            expect(exchange.getResponseChannel()).andReturn(recorder.channel).anyTimes();
            expect(exchange.getResponseHeaders()).andReturn(headers).anyTimes();
            expect(exchange.getRequestMethod()).andReturn(Methods.POST).anyTimes();

            replay(connection, exchange);

            this.stream = new UndertowOutputStream(exchange);
        }
    }

    /**
     * A {@link StreamSinkChannel} mock that records every byte handed to it.
     */
    private static final class RecordingChannel {

        private final ByteArrayOutputStream received = new ByteArrayOutputStream();
        private final StreamSinkChannel channel;
        private boolean shutdown;
        private IOException failure;

        private RecordingChannel() {
            this.channel = createMock(StreamSinkChannel.class);
            expect(channel.write(anyObject(ByteBuffer[].class), anyInt(), anyInt()))
                    .andAnswer(this::consumeBuffers).anyTimes();
            expect(channel.write(anyObject(ByteBuffer.class))).andAnswer(this::consumeBuffer).anyTimes();
            expect(channel.writeFinal(anyObject(ByteBuffer.class))).andAnswer(this::consumeFinalBuffer).anyTimes();
            expect(channel.flush()).andAnswer(() -> true).anyTimes();
            channel.shutdownWrites();
            expectLastCall().andAnswer(() -> {
                shutdown = true;
                return null;
            }).anyTimes();
            replay(channel);
        }

        private byte[] receivedBytes() {
            return received.toByteArray();
        }

        private Long consumeBuffers() throws Throwable {
            checkFailure();
            Object[] arguments = getCurrentArguments();
            ByteBuffer[] buffers = (ByteBuffer[]) arguments[0];
            int offset = (Integer) arguments[1];
            int length = (Integer) arguments[2];
            long written = 0;
            for (int i = offset; i < offset + length; ++i) {
                written += drain(buffers[i]);
            }
            return written;
        }

        private Integer consumeBuffer() throws Throwable {
            checkFailure();
            return (int) drain((ByteBuffer) getCurrentArguments()[0]);
        }

        private Integer consumeFinalBuffer() throws Throwable {
            checkFailure();
            return (int) drain((ByteBuffer) getCurrentArguments()[0]);
        }

        private void checkFailure() throws IOException {
            if (failure != null) {
                throw failure;
            }
        }

        private long drain(final ByteBuffer buffer) {
            int remaining = buffer.remaining();
            byte[] bytes = new byte[remaining];
            buffer.get(bytes);
            received.write(bytes, 0, remaining);
            return remaining;
        }
    }

    private static final class TestByteBufferPool implements ByteBufferPool {

        private final int bufferSize;
        private final List<TestPooledBuffer> allocated = new ArrayList<>();

        private TestByteBufferPool(final int bufferSize) {
            this.bufferSize = bufferSize;
        }

        @Override
        public PooledByteBuffer allocate() {
            TestPooledBuffer pooled = new TestPooledBuffer(ByteBuffer.allocate(bufferSize));
            allocated.add(pooled);
            return pooled;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return bufferSize;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static final class TestPooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean open = true;

        private TestPooledBuffer(final ByteBuffer buffer) {
            this.buffer = buffer;
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            open = false;
        }

        @Override
        public boolean isOpen() {
            return open;
        }
    }
