/**
 * Unit tests for {@link PredicatesHandler#handleRequest(HttpServerExchange)}.
 *
 * The tests only use the public API for driving the handler and observe the
 * externally visible effects: which handlers/predicates run, in which order,
 * which attachments are left behind on the exchange and how the (private)
 * CURRENT_POSITION attachment drives a resumed invocation.
 */
public class PredicatesHandlerHandleRequestTests {

    private List<String> log;

    @BeforeEach
    void setUp() {
        log = new ArrayList<>();
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private static HttpServerExchange newExchange() {
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.setRequestMethod(new HttpString("GET"));
        exchange.setRequestScheme("http");
        exchange.setRequestPath("/some/path");
        exchange.setRelativePath("/some/path");
        return exchange;
    }

    /** handler that simply records the fact that it was invoked. */
    private HttpHandler terminalNext() {
        return exchange -> log.add("next");
    }

    private Predicate pred(String name, boolean result) {
        return exchange -> {
            log.add(name);
            return result;
        };
    }

    private Predicate predChecksExchange(String name, boolean result, AtomicReference<HttpServerExchange> observed) {
        return exchange -> {
            log.add(name);
            observed.set(exchange);
            return result;
        };
    }

    private Predicate throwingPredicate(String name, RuntimeException failure) {
        return exchange -> {
            log.add(name);
            throw failure;
        };
    }

    /** A {@link HandlerWrapper} producing a handler that records its execution. */
    private HandlerWrapper rec(String name) {
        return next -> exchange -> log.add(name);
    }

    /** A {@link HandlerWrapper} producing a handler that records its execution and runs an action. */
    private HandlerWrapper rec(String name, Consumer<HttpServerExchange> action) {
        return next -> exchange -> {
            log.add(name);
            action.accept(exchange);
        };
    }

    private void assertLog(String... expected) {
        assertEquals(List.of(expected), log);
    }

    /**
     * Reads the non static CURRENT_POSITION attachment key of the given handler instance so that the
     * position bookkeeping of the (otherwise unobservable) attachment can be asserted.
     */
    @SuppressWarnings("unchecked")
    private static AttachmentKey<Integer> positionKey(PredicatesHandler handler) {
        try {
            Field field = PredicatesHandler.class.getDeclaredField("CURRENT_POSITION");
            field.setAccessible(true);
            return (AttachmentKey<Integer>) field.get(handler);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to read CURRENT_POSITION from " + handler, e);
        }
    }

    // ------------------------------------------------------------------
    // next handler / attachment initialisation
    // ------------------------------------------------------------------

    @Test
    void noPredicatesInvokesNextHandlerAndResetsMarkerAttachments() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        HttpServerExchange exchange = newExchange();
        exchange.putAttachment(PredicatesHandler.DONE, Boolean.TRUE);
        exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);

        handler.handleRequest(exchange);

        assertLog("next");
        assertNull(exchange.getAttachment(PredicatesHandler.DONE), "an outer handler must clear a stale DONE marker");
        assertNull(exchange.getAttachment(PredicatesHandler.RESTART), "an outer handler must clear a stale RESTART marker");

        Map<String, Object> context = exchange.getAttachment(Predicate.PREDICATE_CONTEXT);
        assertNotNull(context, "an outer handler must install the predicate context");
        assertTrue(context.isEmpty());
        assertNull(exchange.getAttachment(positionKey(handler)), "the position must not be recorded when nothing ran");
    }

    @Test
    void existingPredicateContextIsReused() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        TreeMap<String, Object> existing = new TreeMap<>();
        existing.put("match", "value");

        HttpServerExchange exchange = newExchange();
        exchange.putAttachment(Predicate.PREDICATE_CONTEXT, existing);

        handler.handleRequest(exchange);

        assertLog("next");
        assertSame(existing, exchange.getAttachment(Predicate.PREDICATE_CONTEXT),
                "an already present predicate context must not be replaced");
    }

    @Test
    void innerHandlerDoesNotInitialisePredicateContext() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext(), false);
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));

        HttpServerExchange exchange = newExchange();
        exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
        exchange.putAttachment(PredicatesHandler.DONE, Boolean.TRUE);

        handler.handleRequest(exchange);

        assertLog("p0", "h0");
        assertNull(exchange.getAttachment(Predicate.PREDICATE_CONTEXT),
                "a non outer handler must not create the predicate context");
        assertNotNull(exchange.getAttachment(PredicatesHandler.RESTART),
                "a non outer handler must not clear the stale RESTART marker");
        assertNotNull(exchange.getAttachment(PredicatesHandler.DONE),
                "a non outer handler must not clear the stale DONE marker");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void nextHandlerReceivesTheSameExchangeInstance() throws Exception {
        AtomicReference<HttpServerExchange> seen = new AtomicReference<>();
        PredicatesHandler handler = new PredicatesHandler(exchange -> seen.set(exchange));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertSame(exchange, seen.get());
    }

    @Test
    void exceptionFromNextHandlerIsPropagated() {
        IllegalStateException failure = new IllegalStateException("next failed");
        PredicatesHandler handler = new PredicatesHandler(exchange -> {
            throw failure;
        });

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> handler.handleRequest(newExchange()));
        assertSame(failure, thrown);
    }

