    // ------------------------------------------------------------------

    @Test
    void matchingPredicateRunsItsHandlerAndSkipsNextHandler() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)),
                "the position must be advanced past the executed predicate");
    }

    @Test
    void nonMatchingPredicateWithoutElseBranchFallsThroughToNextHandler() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "next");
        assertNull(exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void nonMatchingPredicateWithElseBranchRunsOnlyTheElseBranch() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"), rec("else0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "else0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void matchingPredicateIgnoresItsElseBranch() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"), rec("else0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void resolutionStopsAtTheFirstMatchingPredicate() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));
        handler.addPredicatedHandler(pred("p1", true), rec("h1"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void nonMatchingPredicatesAreSkippedUntilOneMatches() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        handler.addPredicatedHandler(pred("p1", false), rec("h1"));
        handler.addPredicatedHandler(pred("p2", true), rec("h2"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "p1", "p2", "h2");
        assertEquals(Integer.valueOf(3), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void elseBranchStopsTheChain() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"), rec("else0"));
        handler.addPredicatedHandler(pred("p1", true), rec("h1"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "else0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void allPredicatesNotMatchingRunsNextHandler() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        handler.addPredicatedHandler(pred("p1", false), rec("h1"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "p1", "next");
        assertNull(exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void predicatesAndHandlersSeeTheSameExchange() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        AtomicReference<HttpServerExchange> predicateSaw = new AtomicReference<>();
        AtomicReference<HttpServerExchange> handlerSaw = new AtomicReference<>();
        handler.addPredicatedHandler(predChecksExchange("p0", true, predicateSaw),
                rec("h0", exchange -> handlerSaw.set(exchange)));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertSame(exchange, predicateSaw.get());
        assertSame(exchange, handlerSaw.get());
    }

    @Test
    void exceptionFromPredicateIsPropagatedAndNextHandlerIsNotRun() {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        IllegalStateException failure = new IllegalStateException("predicate failed");
        handler.addPredicatedHandler(throwingPredicate("p0", failure), rec("h0"));
        HttpServerExchange exchange = newExchange();

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> handler.handleRequest(exchange));
        assertSame(failure, thrown);
        assertLog("p0");
        assertNull(exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void exceptionFromHandlerIsPropagatedAndNextHandlerIsNotRun() {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        IllegalStateException failure = new IllegalStateException("handler failed");
        handler.addPredicatedHandler(pred("p0", true), next -> exchange -> {
            log.add("h0");
            throw failure;
        });
        HttpServerExchange exchange = newExchange();

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> handler.handleRequest(exchange));
        assertSame(failure, thrown);
        assertLog("p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    // ------------------------------------------------------------------
    // restart handling
    // ------------------------------------------------------------------

    @Test
    void restartReResolvesPredicatesFromTheBeginningOfTheChain() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        AtomicInteger restartRequests = new AtomicInteger();
        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        handler.addPredicatedHandler(pred("p1", true), rec("h1", exchange -> {
            if (restartRequests.getAndIncrement() == 0) {
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
            }
        }));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "p1", "h1", "p0", "p1", "h1");
        assertEquals(Integer.valueOf(2), exchange.getAttachment(positionKey(handler)));
        assertNull(exchange.getAttachment(PredicatesHandler.RESTART),
                "the restart marker is consumed at the start of every pass");
    }

    @Test
    void chainIsRestartedAsOftenAsTheHandlerRequestsIt() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        AtomicInteger restartRequests = new AtomicInteger();
        handler.addPredicatedHandler(pred("p0", true), rec("h0", exchange -> {
            if (restartRequests.incrementAndGet() <= 2) {
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
            }
        }));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "h0", "p0", "h0", "p0", "h0");
        assertEquals(3, restartRequests.get());
    }

    @Test
    void restartFromAnElseBranchIsHonoured() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        AtomicInteger restartRequests = new AtomicInteger();
        handler.addPredicatedHandler(pred("p0", false), rec("h0"), rec("else0", exchange -> {
            if (restartRequests.getAndIncrement() == 0) {
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
            }
        }));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "else0", "p0", "else0");
        assertEquals(2, restartRequests.get());
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void restartReResolvesPredicatesWithTheirCurrentOutcome() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        AtomicBoolean firstPass = new AtomicBoolean(true);
        handler.addPredicatedHandler(exchange -> {
            log.add("p0");
            return !firstPass.get();
        }, rec("h0", exchange -> {
            firstPass.set(false);
            exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
        }));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        // first pass: predicate false, second pass (after restart): predicate true
        assertLog("p0", "p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void nonOuterHandlerIgnoresTheRestartMarker() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext(), false);
        AtomicInteger invocations = new AtomicInteger();
        handler.addPredicatedHandler(pred("p0", true), rec("h0", exchange ->
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE)));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertEquals(1, invocations.get() + 1); // sanity: single pass
        assertLog("p0", "h0");
        assertNotNull(exchange.getAttachment(PredicatesHandler.RESTART),
