        handler.handleRequest(exchange);

        assertLog("p1", "h1");
        assertEquals(Integer.valueOf(2), exchange.getAttachment(positionKey(handler)));
        assertNotNull(exchange.getAttachment(PredicatesHandler.RESTART),
                "a resumed invocation (position present) must not consume the restart marker");
    }

