    private static HttpServerExchange newExchange() {
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.setRequestMethod(new HttpString("GET"));
        exchange.setRequestScheme("http");
        exchange.setRequestPath("/some/path");
        exchange.setRelativePath("/some/path");
        return exchange;
    }

    /** handler that simply records the fact that it was invoked. */
    private HttpHandler terminalNext() {
        return exchange -> log.add("next");
    }

    private Predicate pred(String name, boolean result) {
        return exchange -> {
            log.add(name);
            return result;
        };
    }

    private Predicate predChecksExchange(String name, boolean result, AtomicReference<HttpServerExchange> observed) {
        return exchange -> {
            log.add(name);
            observed.set(exchange);
            return result;
        };
    }

    private Predicate throwingPredicate(String name, RuntimeException failure) {
        return exchange -> {
            log.add(name);
            throw failure;
        };
    }

    /** A {@link HandlerWrapper} producing a handler that records its execution. */
    private HandlerWrapper rec(String name) {
        return next -> exchange -> log.add(name);
    }

    /** A {@link HandlerWrapper} producing a handler that records its execution and runs an action. */
    private HandlerWrapper rec(String name, Consumer<HttpServerExchange> action) {
        return next -> exchange -> {
            log.add(name);
            action.accept(exchange);
        };
    }

    private void assertLog(String... expected) {
        assertEquals(List.of(expected), log);
    }

    /**
     * Reads the non static CURRENT_POSITION attachment key of the given handler instance so that the
     * position bookkeeping of the (otherwise unobservable) attachment can be asserted.
     */
    @SuppressWarnings("unchecked")
    private static AttachmentKey<Integer> positionKey(PredicatesHandler handler) {
        try {
            Field field = PredicatesHandler.class.getDeclaredField("CURRENT_POSITION");
            field.setAccessible(true);
            return (AttachmentKey<Integer>) field.get(handler);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to read CURRENT_POSITION from " + handler, e);
        }
    }

