    // next handler / attachment initialisation
    // ------------------------------------------------------------------

    @Test
    void noPredicatesInvokesNextHandlerAndResetsMarkerAttachments() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        HttpServerExchange exchange = newExchange();
        exchange.putAttachment(PredicatesHandler.DONE, Boolean.TRUE);
        exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);

        handler.handleRequest(exchange);

        assertLog("next");
        assertNull(exchange.getAttachment(PredicatesHandler.DONE), "an outer handler must clear a stale DONE marker");
        assertNull(exchange.getAttachment(PredicatesHandler.RESTART), "an outer handler must clear a stale RESTART marker");

        Map<String, Object> context = exchange.getAttachment(Predicate.PREDICATE_CONTEXT);
        assertNotNull(context, "an outer handler must install the predicate context");
        assertTrue(context.isEmpty());
        assertNull(exchange.getAttachment(positionKey(handler)), "the position must not be recorded when nothing ran");
    }

    @Test
    void existingPredicateContextIsReused() throws Exception {
