class AjpResponseParserParseStringTests {

    private static ByteBuffer buffer(int... bytes) {
        byte[] array = new byte[bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            array[i] = (byte) bytes[i];
        }
        return ByteBuffer.wrap(array);
    }

    private static ByteBuffer asciiString(int lengthHigh, int lengthLow, String value, boolean terminator) {
        byte[] valueBytes = value.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        byte[] array = new byte[2 + valueBytes.length + (terminator ? 1 : 0)];
        array[0] = (byte) lengthHigh;
        array[1] = (byte) lengthLow;
        System.arraycopy(valueBytes, 0, array, 2, valueBytes.length);
        if (terminator) {
            array[array.length - 1] = 0;
        }
        return ByteBuffer.wrap(array);
    }

    @Test
    void emptyBufferReturnsIncompleteAndLeavesStateUntouched() {
        AjpResponseParser parser = new AjpResponseParser();

        AjpResponseParser.StringHolder result = parser.parseString(buffer(), false);

        assertNull(result.value);
        assertNull(result.header);
        assertFalse(result.readComplete);
        assertFalse(result.containsUrlCharacters);
        assertEquals(-1, parser.stringLength);
        assertNull(parser.currentString);
        assertFalse(parser.containsUrlCharacters);
    }

    @Test
    void parsesSimpleNullTerminatedString() {
