        ByteBuffer buf = buffer(0x00, 0x03, 'f', 'o', 'o', 0x00);

        AjpResponseParser.StringHolder result = parser.parseString(buf, false);

        assertNull(result.header);
        assertEquals("foo", result.value);
        assertTrue(result.readComplete);
        assertFalse(result.containsUrlCharacters);
        // the terminating null byte is consumed
        assertEquals(6, buf.position());
        assertEquals(-1, parser.stringLength);
        assertNull(parser.currentString);
        assertFalse(parser.containsUrlCharacters);
    }

    @Test
    void parsesEmptyNullTerminatedString() {
        AjpResponseParser parser = new AjpResponseParser();
        ByteBuffer buf = buffer(0x00, 0x00, 0x00);

        AjpResponseParser.StringHolder result = parser.parseString(buf, false);

        assertNull(result.header);
        assertEquals("", result.value);
        assertTrue(result.readComplete);
        assertFalse(result.containsUrlCharacters);
        assertEquals(3, buf.position());
        assertEquals(-1, parser.stringLength);
        assertNull(parser.currentString);
    }

    @Test
    void detectsUrlCharactersAndResetsFlagAfterCompletion() {
        AjpResponseParser parser = new AjpResponseParser();
        ByteBuffer urlBuffer = buffer(0x00, 0x06, 'a', '+', 'b', '%', '2', '0', 0x00);

        AjpResponseParser.StringHolder urlResult = parser.parseString(urlBuffer, false);

        assertEquals("a+b%20", urlResult.value);
        assertTrue(urlResult.readComplete);
        assertTrue(urlResult.containsUrlCharacters);
        assertFalse(parser.containsUrlCharacters, "the parser flag must be reset after a complete string");

        AjpResponseParser.StringHolder plainResult = parser.parseString(buffer(0x00, 0x01, 'x', 0x00), false);

        assertEquals("x", plainResult.value);
        assertTrue(plainResult.readComplete);
        assertFalse(plainResult.containsUrlCharacters);
        assertFalse(parser.containsUrlCharacters);
    }

    @Test
    void detectsPercentCharacterAlone() {
        AjpResponseParser parser = new AjpResponseParser();
