import io.undertow.protocols.http2.HPackHuffman;
import java.nio.ByteBuffer;

public class Explore {
    static String hex(ByteBuffer b) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < b.limit(); i++) sb.append(String.format("%02x ", b.get(i) & 0xFF));
        return sb.toString().trim();
    }
    static String rep(char c, int n) { StringBuilder sb = new StringBuilder(); for (int i=0;i<n;i++) sb.append(c); return sb.toString(); }
    public static void main(String[] a) throws Exception {
        // case: char 1 repeated
        for (int n : new int[]{1,2,3,5}) {
            String s = rep('\u0001', n);
            ByteBuffer bb = ByteBuffer.allocate(200);
            boolean ok = HPackHuffman.encode(bb, s, false);
            System.out.println("nul1 n=" + n + " ok=" + ok + " pos=" + bb.position() + " content=" + hex(bb));
        }
        // tight buffers around threshold for '0' repeated
        String z = rep('0', 10); // encoded 7 bytes data + 1 header
        for (int cap : new int[]{10, 11, 8, 7}) {
            ByteBuffer bb = ByteBuffer.allocate(cap);
            boolean ok = HPackHuffman.encode(bb, z, false);
            System.out.println("zero10 cap=" + cap + " ok=" + ok + " pos=" + bb.position() + " content=" + hex(bb));
        }
        // non-zero start position, failure
        ByteBuffer bb = ByteBuffer.allocate(50);
        bb.put((byte) 0x42); bb.put((byte) 0x43);
        int start = bb.position();
        boolean ok = HPackHuffman.encode(bb, rep('\u0001', 5), false);
        System.out.println("nonzero-start ok=" + ok + " pos=" + bb.position() + " start=" + start + " content=" + hex(bb));
        // prefix + success
        ByteBuffer ok2 = ByteBuffer.allocate(50);
        ok2.put((byte) 0x42); ok2.put((byte) 0x43);
        int st = ok2.position();
        boolean o2 = HPackHuffman.encode(ok2, "www.example.com", false);
        System.out.println("prefix-success ok=" + o2 + " pos=" + ok2.position() + " start=" + st + " content=" + hex(ok2));
        // empty string
        ByteBuffer e1 = ByteBuffer.allocate(1);
        System.out.println("empty cap1 ok=" + HPackHuffman.encode(e1, "", false) + " pos=" + e1.position() + " content=" + hex(e1));
        ByteBuffer e0 = ByteBuffer.allocate(0);
        System.out.println("empty cap0 ok=" + HPackHuffman.encode(e0, "", false));
        // remaining == length
        ByteBuffer rl = ByteBuffer.allocate(3);
        System.out.println("rem==len ok=" + HPackHuffman.encode(rl, "abc", false) + " pos=" + rl.position() + " content=" + hex(rl));
        // big string requiring multibyte length
        ByteBuffer big = ByteBuffer.allocate(1000);
        String zz = rep('0', 204);
        boolean okb = HPackHuffman.encode(big, zz, false);
        big.flip();
        System.out.println("big204 ok=" + okb + " len=" + big.remaining() + " first4=" + String.format("%02x %02x %02x %02x", big.get(0)&0xFF, big.get(1)&0xFF, big.get(2)&0xFF, big.get(3)&0xFF));
        // 100 '0'
        ByteBuffer b100 = ByteBuffer.allocate(1000);
        boolean ok100 = HPackHuffman.encode(b100, rep('0', 100), false);
        b100.flip();
        System.out.println("big100 ok=" + ok100 + " len=" + b100.remaining() + " first3=" + String.format("%02x %02x %02x", b100.get(0)&0xFF, b100.get(1)&0xFF, b100.get(2)&0xFF));
        // forceLowercase
        ByteBuffer lc = ByteBuffer.allocate(100);
        System.out.println("lower ok=" + HPackHuffman.encode(lc, "ABCDEF", true));
        lc.flip();
        System.out.println("lower content=" + hex(lc));
        ByteBuffer up = ByteBuffer.allocate(100);
        System.out.println("upper ok=" + HPackHuffman.encode(up, "ABCDEF", false));
        up.flip();
        System.out.println("upper content=" + hex(up));
        // decode roundtrip
        ByteBuffer rt = ByteBuffer.allocate(100);
        HPackHuffman.encode(rt, "www.example.com", false);
        rt.flip();
        int lenByte = rt.get() & 0xFF;
        System.out.println("lenByte=" + lenByte);
        StringBuilder sb = new StringBuilder();
        HPackHuffman.decode(rt, 12, sb);
        System.out.println("decoded=" + sb);
    }
}
