import org.junit.jupiter.params.provider.ValueSource;

/**
 * Tests for {@link HPackHuffman#encode(ByteBuffer, String, boolean)}.
 *
 * <p>Expected byte sequences are the HPACK (RFC 7541) Huffman encodings of the strings used,
 * prefixed with the string literal header byte (huffman flag set, 7 bit prefix length) used by
 * this implementation.</p>
 */
public class HPackHuffmanEncodeTests {

    private static final String WWW_EXAMPLE_COM = "www.example.com";

    private static byte[] bytes(int... values) {
        byte[] result = new byte[values.length];
        for (int i = 0; i < values.length; ++i) {
            result[i] = (byte) values[i];
        }
        return result;
    }

    /**
     * Returns the bytes that were written into the buffer, i.e. everything between index 0 and the
     * current position.
     */
    private static byte[] writtenBytes(ByteBuffer buffer) {
        byte[] result = new byte[buffer.position()];
        for (int i = 0; i < result.length; ++i) {
            result[i] = buffer.get(i);
        }
        return result;
    }

    /**
     * Returns the whole backing content of a heap buffer, independently of its position.
     */
    private static byte[] wholeContent(ByteBuffer buffer) {
        byte[] result = new byte[buffer.capacity()];
        for (int i = 0; i < result.length; ++i) {
            result[i] = buffer.get(i);
        }
        return result;
    }

    private static String repeat(char c, int count) {
        StringBuilder sb = new StringBuilder(count);
        for (int i = 0; i < count; ++i) {
            sb.append(c);
        }
        return sb.toString();
    }

    private static String hex(byte... data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    /**
     * Encodes the value into a buffer that is large enough and verifies that the written bytes match
     * the given Huffman encoding.
     */
    private static void assertEncodesTo(byte[] expected, String value, boolean forceLowercase) {
        ByteBuffer buffer = ByteBuffer.allocate(expected.length + 64);
        assertTrue(HPackHuffman.encode(buffer, value, forceLowercase), "encoding of '" + value + "' should succeed");
        assertEquals(expected.length, buffer.position(), "unexpected number of bytes written for '" + value + "'");
        assertArrayEquals(expected, writtenBytes(buffer), "unexpected encoding of '" + value + "', was: " + hex(writtenBytes(buffer)));
    }

    /**
     * Reads the huffman flag and the 7 bit prefixed length of the string literal preceded by it and
     * leaves the buffer positioned on the first Huffman encoded byte.
     */
    private static int readLengthPrefix(ByteBuffer buffer) {
        int first = buffer.get() & 0xFF;
        assertEquals(0x80, first & 0x80, "the huffman encoding flag must be set");
        int prefix = first & 0x7F;
        if (prefix < 0x7F) {
            return prefix;
        }
        int value = 0;
        int shift = 0;
        int next;
        do {
            next = buffer.get() & 0xFF;
            value += (next & 0x7F) << shift;
            shift += 7;
        } while ((next & 0x80) != 0);
        return 0x7F + value;
    }

    private static String decode(String encoded, int capacity) throws Exception {
        ByteBuffer buffer = ByteBuffer.allocate(capacity);
        assertTrue(HPackHuffman.encode(buffer, encoded, false), "encoding of '" + encoded + "' should succeed");
        buffer.flip();
        int length = readLengthPrefix(buffer);
        StringBuilder target = new StringBuilder();
        HPackHuffman.decode(buffer, length, target);
        return target.toString();
    }

    static Stream<Arguments> knownVectors() {
        return Stream.of(
                // RFC 7541, appendix C.4 and C.5 / C.6 examples
                Arguments.of(bytes(0x8c, 0xf1, 0xe3, 0xc2, 0xe5, 0xf2, 0x3a, 0x6b, 0xa0, 0xab, 0x90, 0xf4, 0xff),
                        "www.example.com"),
                Arguments.of(bytes(0x86, 0xa8, 0xeb, 0x10, 0x64, 0x9c, 0xbf), "no-cache"),
                Arguments.of(bytes(0x88, 0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xa9, 0x7d, 0x7f), "custom-key"),
                Arguments.of(bytes(0x89, 0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xb8, 0xe8, 0xb4, 0xbf), "custom-value"),
                Arguments.of(bytes(0x82, 0x64, 0x02), "302"),
                Arguments.of(bytes(0x85, 0xae, 0xc3, 0x77, 0x1a, 0x4b), "private"),
                Arguments.of(bytes(0x96, 0xd0, 0x7a, 0xbe, 0x94, 0x10, 0x54, 0xd4, 0x44, 0xa8, 0x20, 0x05, 0x95, 0x04,
                        0x0b, 0x81, 0x66, 0xe0, 0x82, 0xa6, 0x2d, 0x1b, 0xff), "Mon, 21 Oct 2013 20:13:21 GMT"),
                Arguments.of(bytes(0x91, 0x9d, 0x29, 0xad, 0x17, 0x18, 0x63, 0xc7, 0x8f, 0x0b, 0x97, 0xc8, 0xe9, 0xae,
                        0x82, 0xae, 0x43, 0xd3), "https://www.example.com"),
                // single characters, the last byte contains the EOS padding bits
                Arguments.of(bytes(0x81, 0x1f), "a"),
                Arguments.of(bytes(0x81, 0x07), "0"),
                // strings that contain upper case characters, encoded without forcing lower case
                Arguments.of(bytes(0x83, 0x86, 0xed, 0xef), "ABC"),
                Arguments.of(bytes(0x8d, 0xe5, 0xcb, 0x92, 0xf8, 0x3f, 0x21, 0xd1, 0xaf, 0x3e, 0x05, 0xef, 0x6a, 0xd1),
                        "WWW.EXAMPLE.COM"),
                Arguments.of(bytes(0x8e, 0xc6, 0x5a, 0x28, 0x3f, 0xd2, 0x9c, 0x8f, 0x65, 0x12, 0x7f, 0x0a, 0x04, 0x4c,
                        0xff), "Hello, World! 123"));
    }

    @ParameterizedTest
    @MethodSource("knownVectors")
    void encodesKnownVectors(byte[] expected, String value) {
        assertEncodesTo(expected, value, false);
    }

    @Test
    void encodesEmptyStringToOnlyTheHeaderByte() {
        ByteBuffer buffer = ByteBuffer.allocate(10);
        assertTrue(HPackHuffman.encode(buffer, "", false));
        assertEquals(1, buffer.position());
        assertArrayEquals(bytes(0x80), writtenBytes(buffer));
        assertArrayEquals(bytes(0x80, 0, 0, 0, 0, 0, 0, 0, 0, 0), wholeContent(buffer),
                "nothing beyond the header byte may be written");
    }

    @Test
    void failsToEncodeEmptyStringWhenBufferIsFull() {
        ByteBuffer buffer = ByteBuffer.allocate(0);
        assertFalse(HPackHuffman.encode(buffer, "", false));
        assertEquals(0, buffer.position());
    }

    @Test
    void returnsFalseAndLeavesBufferUntouchedWhenRemainingSpaceEqualsInputLength() {
        ByteBuffer buffer = ByteBuffer.allocate(3);
        assertFalse(HPackHuffman.encode(buffer, "abc", false));
        assertEquals(0, buffer.position(), "the position must not change");
        assertArrayEquals(new byte[3], wholeContent(buffer), "the buffer must not be modified");
    }

    @Test
    void returnsFalseAndLeavesBufferUntouchedWhenRemainingSpaceIsSmallerThanInputLength() {
        ByteBuffer buffer = ByteBuffer.allocate(2);
        assertFalse(HPackHuffman.encode(buffer, "abc", false));
        assertEquals(0, buffer.position());
        assertArrayEquals(new byte[2], wholeContent(buffer));
    }

    @Test
    void returnsFalseWithoutMovingPositionWhenNoSpaceIsRemaining() {
        ByteBuffer buffer = ByteBuffer.allocate(5);
        buffer.position(5);
        assertFalse(HPackHuffman.encode(buffer, "abc", false));
        assertEquals(5, buffer.position());
    }

    @Test
    void encodesLongStringWithSingleByteLengthPrefix() {
        // 201 '0' characters occupy 201 * 5 = 1005 bits -> 126 bytes, which still fits into the
        // 7 bit prefix of the header byte
        String value = repeat('0', 201);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(127, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xfe, content[0], "header byte should be 0x80 | 126");
        assertEquals((byte) 0x07, content[126], "the trailing byte holds 7 zero bits plus 1 EOS padding bit");
        for (int i = 1; i < 126; ++i) {
            assertEquals(0, content[i], "payload byte " + i + " should be zero");
        }
    }

    @Test
    void encodesLongStringWithMultiByteLengthPrefixFor127Bytes() {
        // 202 '0' characters occupy 1010 bits -> 127 bytes, the first value that needs a
        // continuation byte in the length prefix
        String value = repeat('0', 202);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(129, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xff, content[0], "header byte should be 0x80 | 127");
        assertEquals((byte) 0x00, content[1], "the length remainder is encoded in a continuation byte");
        assertEquals((byte) 0x3f, content[128], "the trailing byte holds 6 zero bits plus 2 EOS padding bits");
    }

    @Test
    void encodesLongStringWithMultiByteLengthPrefixFor128Bytes() {
        // 204 '0' characters occupy 1020 bits -> 128 bytes
        String value = repeat('0', 204);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(130, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xff, content[0], "header byte should be 0x80 | 127");
        assertEquals((byte) 0x01, content[1], "128 - 127 leaves a remainder of 1");
        assertEquals((byte) 0x0f, content[129], "the trailing byte holds 4 zero bits plus 4 EOS padding bits");
    }

    @ParameterizedTest
    @ValueSource(strings = { "", "a", "0123456789", "abc123", "www.example.com", "no-cache", "custom-value",
            "Mon, 21 Oct 2013 20:13:21 GMT", "https://www.example.com", "Hello, World! 123" })
