        TestHttp2Channel channel = newChannel();
        HeaderMap headers = headers();
        int flags = Http2Channel.HEADERS_FLAG_END_STREAM | Http2Channel.HEADERS_FLAG_END_HEADERS;
        Http2HeadersParser parser = headersParser(channel, 1, flags, headers);
        Http2FrameHeaderParser header = frameHeader(channel, Http2Channel.FRAME_TYPE_HEADERS, flags, 1, 0);
        header.parser = parser;
        TrackingPooledByteBuffer frameData = frameData();

        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(header, frameData);

        Http2StreamSourceChannel stream = assertInstanceOf(Http2StreamSourceChannel.class, result);
        assertEquals(1, stream.getStreamId());
        assertSame(headers, stream.getHeaders());
        assertTrue(frameData.isOpen(), "The stream owns the frame data");
        assertEquals(1, getIntField(channel, "lastGoodStreamId"));
        assertEquals(1, getIntField(channel, "lastAssignedStreamOtherSide"));
        assertEquals(1, getIntField(channel, "receiveConcurrentStreams"));
        Object holder = currentStreams(channel).get(1);
        assertNotNull(holder);
        assertTrue(getBooleanField(holder, "sourceClosed"));
        assertNull(getField(holder, "sourceChannel"));
        assertTrue(channel.goAwayStatuses.isEmpty());
