        int flags = Http2Channel.HEADERS_FLAG_END_STREAM | Http2Channel.HEADERS_FLAG_END_HEADERS;
        Http2FrameHeaderParser secondHeader = frameHeader(channel, Http2Channel.FRAME_TYPE_HEADERS, flags, 1, 0);
