        assertSame(replacementHeaders, replacement.getHeaders());
        assertNull(currentStreams(channel).get(1));
        assertEquals(0, getIntField(channel, "receiveConcurrentStreams"));
        assertTrue(channel.goAwayStatuses.isEmpty());
    }

