    @Test
    public void goAwayMarksPeerGoneAwayRstExistingStreamsAndAcknowledges() throws Exception {
        TestHttp2Channel channel = newChannel();
        Http2StreamSourceChannel existing = receiveHeaders(channel, 1, Http2Channel.HEADERS_FLAG_END_HEADERS, false);
        Http2GoAwayParser parser = new Http2GoAwayParser(8);
        setField(parser, "statusCode", Http2Channel.ERROR_NO_ERROR);
        setField(parser, "lastGoodStreamId", 1);
        Http2FrameHeaderParser header = frameHeader(channel, Http2Channel.FRAME_TYPE_GOAWAY, 0, 0, 8);
        header.parser = parser;
        TrackingPooledByteBuffer frameData = frameData();

        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(header, frameData);

        Http2GoAwayStreamSourceChannel goAway = assertInstanceOf(Http2GoAwayStreamSourceChannel.class, result);
        assertEquals(Http2Channel.ERROR_NO_ERROR, goAway.getStatus());
        assertEquals(1, goAway.getLastGoodStreamId());
        assertTrue(channel.isPeerGoneAway());
        assertTrue(getBooleanField(existing, "rst"));
        assertFalse(frameData.isOpen());
        assertEquals(List.of(Http2Channel.ERROR_NO_ERROR), channel.goAwayStatuses);
    }

    private static TestHttp2Channel newChannel() {
        StreamSourceConduit sourceConduit = createNiceMock(StreamSourceConduit.class);
        replay(sourceConduit);
        StreamSinkConduit sinkConduit = createNiceMock(StreamSinkConduit.class);
        replay(sinkConduit);
        ConduitStreamSourceChannel source = new ConduitStreamSourceChannel(Configurable.EMPTY, sourceConduit);
        ConduitStreamSinkChannel sink = new ConduitStreamSinkChannel(Configurable.EMPTY, sinkConduit);
        StreamConnection connection = createNiceMock(StreamConnection.class);
        expect(connection.getSourceChannel()).andReturn(source).anyTimes();
        expect(connection.getSinkChannel()).andReturn(sink).anyTimes();
        replay(connection);
        ByteBufferPool pool = createNiceMock(ByteBufferPool.class);
        replay(pool);
        return new TestHttp2Channel(connection, pool);
    }

    private static Http2StreamSourceChannel receiveHeaders(TestHttp2Channel channel, int streamId, int flags,
            boolean endStream) throws Exception {
        int actualFlags = endStream ? flags | Http2Channel.HEADERS_FLAG_END_STREAM : flags;
        Http2FrameHeaderParser header = frameHeader(channel, Http2Channel.FRAME_TYPE_HEADERS, actualFlags, streamId, 0);
        header.parser = headersParser(channel, streamId, actualFlags, headers());
        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(header, frameData());
        return assertInstanceOf(Http2StreamSourceChannel.class, result);
    }

    private static HeaderMap headers() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        headers.put(Headers.CONTENT_TYPE, "text/plain");
        return headers;
    }

    private static Http2HeadersParser headersParser(TestHttp2Channel channel, int streamId, int flags,
            HeaderMap headers) throws Exception {
        Http2HeadersParser parser = new Http2HeadersParser(0, new HpackDecoder(), channel.isClient(), 100,
                streamId, 10000);
        Http2FrameHeaderParser context = frameHeader(channel, Http2Channel.FRAME_TYPE_HEADERS, flags, streamId, 0);
        parser.parse(ByteBuffer.allocate(0), context);
        HeaderMap parserHeaders = (HeaderMap) getField(parser, "headerMap");
        parserHeaders.putAll(headers);
        return parser;
    }

    private static Http2PushPromiseParser pushPromiseParser(HeaderMap headers, int promisedStreamId) throws Exception {
        Http2PushPromiseParser parser = new Http2PushPromiseParser(0, new HpackDecoder(), true, 100, 1, 10000);
        ((HeaderMap) getField(parser, "headerMap")).putAll(headers);
        setField(parser, "promisedStreamId", promisedStreamId);
        return parser;
    }

    private static Http2PingParser pingParser(byte[] payload) throws Exception {
        Http2PingParser parser = new Http2PingParser(Http2Channel.PING_FRAME_LENGTH);
        System.arraycopy(payload, 0, (byte[]) getField(parser, "data"), 0, payload.length);
        return parser;
    }

    private static Http2PriorityParser priorityParser(int streamDependency) throws Exception {
        Http2PriorityParser parser = new Http2PriorityParser(5);
        setField(parser, "streamDependency", streamDependency);
        return parser;
    }

    private static Http2RstStreamParser rstParser(int errorCode) throws Exception {
        Http2RstStreamParser parser = new Http2RstStreamParser(4);
        setField(parser, "errorCode", errorCode);
        return parser;
    }

    @SuppressWarnings("unchecked")
    private static List<Http2Setting> settings(Http2SettingsParser parser) throws Exception {
        return (List<Http2Setting>) getField(parser, "settings");
    }

    private static Http2FrameHeaderParser frameHeader(TestHttp2Channel channel, int type, int flags, int streamId,
            int length) {
        Http2FrameHeaderParser header = new Http2FrameHeaderParser(channel, null);
        header.type = type;
        header.flags = flags;
        header.streamId = streamId;
        header.length = length;
        return header;
    }

    private static Http2FrameHeaderParser frameHeaderWithActualLength(TestHttp2Channel channel, int type, int flags,
            int streamId, int length) {
        ExtendedFrameHeaderParser header = new ExtendedFrameHeaderParser(channel);
        header.type = type;
        header.flags = flags;
        header.streamId = streamId;
        header.length = length;
        return header;
    }

    private static TrackingPooledByteBuffer frameData() {
