package io.undertow.protocols.http2;

import io.undertow.server.DefaultByteBufferPool;
import org.xnio.OptionMap;
import org.xnio.StreamConnection;
import org.xnio.XnioIoThread;

import java.io.IOException;
import java.net.SocketAddress;
import java.nio.ByteBuffer;

public class Exp {

    static class FakeConnection extends StreamConnection {
        FakeConnection(XnioIoThread thread) { super(thread); }
        @Override public SocketAddress getPeerAddress() { return null; }
        @Override public SocketAddress getLocalAddress() { return null; }
        @Override protected void notifyWriteClosed() {}
        @Override protected void notifyReadClosed() {}
        @Override void invokeCloseListener() {}
    }

    public static void main(String[] args) throws Exception {
        StreamConnection conn = new FakeConnection(null);
        Http2Channel channel = new Http2Channel(conn, null, new DefaultByteBufferPool(false, 1024), null, false, false, true, OptionMap.EMPTY);
        System.out.println("channel created: " + channel + " client=" + channel.isClient() + " maxHeaders=" + channel.getMaxHeaders() + " maxHeaderListSize=" + channel.getMaxHeaderListSize() + " decoder=" + channel.getDecoder());

        Http2FrameHeaderParser p = new Http2FrameHeaderParser(channel, null);
        ByteBuffer buf = ByteBuffer.allocate(64);
        // DATA frame, length 5, streamId 1
        buf.put((byte)0).put((byte)0).put((byte)5).put((byte)0).put((byte)0).put((byte)0).put((byte)0).put((byte)0).put((byte)1);
        buf.put(new byte[]{1,2,3,4,5});
        buf.flip();
        System.out.println("handle -> " + p.handle(buf) + " parser=" + p.getParser() + " remaining=" + buf.remaining());

        // continuation without parser
        Http2FrameHeaderParser p2 = new Http2FrameHeaderParser(channel, null);
        ByteBuffer buf2 = ByteBuffer.allocate(16);
        buf2.put((byte)0).put((byte)0).put((byte)0).put((byte)9).put((byte)0).put((byte)0).put((byte)0).put((byte)0).put((byte)1);
        buf2.flip();
        try {
            System.out.println("cont -> " + p2.handle(buf2));
        } catch (Throwable t) {
            System.out.println("cont threw " + t.getClass().getName() + ": " + t.getMessage());
        }
    }
}
