            }

            // 3 push promise no end headers
            Http2FrameHeaderParser p3 = new Http2FrameHeaderParser(channel, null);
            try {
                p3.handle(frame(4, 5, 0, 1, new byte[]{0, 0, 0, 2}));
            } catch (Throwable t) {
                System.out.println("3 " + t.getClass().getName() + " msg=" + t.getMessage());
            }

            // 4 push promise with end headers
            Http2FrameHeaderParser p4 = new Http2FrameHeaderParser(channel, null);
            System.out.println("4 push end: " + p4.handle(frame(4, 5, 4, 1, new byte[]{0, 0, 0, 2})) + " parser=" + p4.getParser().getClass().getSimpleName() + " cont=" + p4.getContinuationParser());

            // 5 data padded bad padding
            Http2FrameHeaderParser p5 = new Http2FrameHeaderParser(channel, null);
            try {
                p5.handle(frame(2, 0, 0x8, 1, new byte[]{5, 0}));
            } catch (Throwable t) {
                System.out.println("5 " + t.getClass().getName() + " code=" + ((t instanceof ConnectionErrorException) ? ((ConnectionErrorException) t).getCode() : -1));
            }

            // 6 discard
            Http2FrameHeaderParser p6 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b6 = frame(3, 10, 0, 0, new byte[]{1, 2, 3});
            System.out.println("6 unknown: " + p6.handle(b6) + " parser=" + p6.getParser().getClass().getSimpleName() + " remaining=" + b6.remaining());

            // 7 reserved bit
            Http2FrameHeaderParser p7 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b7 = frame(0, 4, 0, 0x80000001, null);
            try { p7.handle(b7); } catch (Throwable t) { System.out.println("7 " + t); }
            System.out.println("7 streamId=" + p7.streamId);

            // 8 ping partial
            Http2FrameHeaderParser p8 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b8 = frame(8, 6, 0, 0, new byte[]{1, 2, 3, 4});
            System.out.println("8a " + p8.handle(b8) + " parser=" + (p8.getParser() != null));
            Http2FrameHeaderParser p8b = p8;
            ByteBuffer more = ByteBuffer.wrap(new byte[]{5, 6, 7, 8});
            System.out.println("8b " + p8b.handle(more) + " finished");

            // 9 goaway 8 bytes
            Http2FrameHeaderParser p9 = new Http2FrameHeaderParser(channel, null);
            System.out.println("9 goaway: " + p9.handle(frame(8, 7, 0, 0, new byte[]{0,0,0,1,0,0,0,0})) + " parser=" + p9.getParser().getClass().getSimpleName());

            // 10 settings length 12 two entries
            Http2FrameHeaderParser p10 = new Http2FrameHeaderParser(channel, null);
            System.out.println("10 settings: " + p10.handle(frame(12, 4, 0, 0, new byte[]{0, 1, 0, 0, 0, 5, 0, 4, 0, 0, 0, 9})) + " parser=" + p10.getParser().getClass().getSimpleName());

            // 11 partial header
            Http2FrameHeaderParser p11 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b11 = ByteBuffer.wrap(new byte[]{0, 0, 0, 4, 0});
            System.out.println("11a " + p11.handle(b11) + " parser=" + p11.getParser());
            System.out.println("11b " + p11.handle(ByteBuffer.wrap(new byte[]{0, 0, 0, 0})) + " parser=" + p11.getParser().getClass().getSimpleName());

            // 12 data with end_stream and payload
            Http2FrameHeaderParser p12 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b12 = frame(3, 0, 1, 5, new byte[]{7, 8, 9});
            System.out.println("12 " + p12.handle(b12) + " frameLen=" + p12.getFrameLength() + " remaining=" + b12.remaining() + " existing=" + p12.getExistingChannel());
        } finally {
            worker.shutdownNow();
        }
    }
}
