 */
class BasicAuthenticationMechanismAuthenticateTests {

    private static final String REALM = "TestRealm";
    private static final String MECHANISM_NAME = "BASIC";

    @Test
    void noAuthorizationHeaderReturnsNotAttempted() {
        final TestIdentityManager identityManager = new TestIdentityManager(null);
        final TestSecurityContext securityContext = new TestSecurityContext();
        final BasicAuthenticationMechanism mechanism = mechanism(identityManager);

        final AuthenticationMechanismOutcome outcome = mechanism.authenticate(exchange(), securityContext);

        assertSame(NOT_ATTEMPTED, outcome);
        assertEquals(0, identityManager.verifyCount);
        assertEquals(0, securityContext.completeCount);
        assertEquals(0, securityContext.failedCount);
    }

    @Test
    void nonBasicAuthorizationHeaderReturnsNotAttempted() {
        final TestIdentityManager identityManager = new TestIdentityManager(account("alice"));
        final TestSecurityContext securityContext = new TestSecurityContext();
        final BasicAuthenticationMechanism mechanism = mechanism(identityManager);

        final HttpServerExchange exchange = exchange();
        exchange.getRequestHeaders().put(AUTHORIZATION, "Bearer some-opaque-token");

        final AuthenticationMechanismOutcome outcome = mechanism.authenticate(exchange, securityContext);

        assertSame(NOT_ATTEMPTED, outcome);
        assertEquals(0, identityManager.verifyCount);
        assertEquals(0, securityContext.completeCount);
        assertEquals(0, securityContext.failedCount);
        assertNull(securityContext.authenticatedAccount);
    }

    @Test
    void basicSchemeWithoutRequiredSpaceReturnsNotAttempted() {
        final TestIdentityManager identityManager = new TestIdentityManager(account("alice"));
        final TestSecurityContext securityContext = new TestSecurityContext();
        final BasicAuthenticationMechanism mechanism = mechanism(identityManager);

        final HttpServerExchange exchange = exchange();
        // The mechanism only recognizes the "Basic " prefix, including the trailing space.
        exchange.getRequestHeaders().put(AUTHORIZATION, "BasicdXNlcjpwYXNz");

        final AuthenticationMechanismOutcome outcome = mechanism.authenticate(exchange, securityContext);

        assertSame(NOT_ATTEMPTED, outcome);
        assertEquals(0, identityManager.verifyCount);
    }

    @Test
    void validCredentialsAreAuthenticated() {
        final Account account = account("alice");
        final TestIdentityManager identityManager = new TestIdentityManager(account);
        final TestSecurityContext securityContext = new TestSecurityContext();
        final BasicAuthenticationMechanism mechanism = mechanism(identityManager);

        final HttpServerExchange exchange = exchange();
        exchange.getRequestHeaders().put(AUTHORIZATION, basicHeader("alice:secret", StandardCharsets.UTF_8));

        final AuthenticationMechanismOutcome outcome = mechanism.authenticate(exchange, securityContext);

        assertSame(AUTHENTICATED, outcome);
        assertEquals(1, identityManager.verifyCount);
        assertEquals("alice", identityManager.lastUsername);
        assertNotNull(identityManager.lastCredential);
        assertArrayEquals("secret".toCharArray(), identityManager.lastCredential.getPassword());

        assertEquals(1, securityContext.completeCount);
        assertSame(account, securityContext.authenticatedAccount);
        assertEquals(MECHANISM_NAME, securityContext.completedMechanismName);
        assertEquals(false, securityContext.cachingRequired);
        assertEquals(0, securityContext.failedCount);
    }

    @Test
