    /**
     * A real exchange needs a connection for endExchange(). This connection is intentionally closed so
     * that endExchange() follows its quick termination path without needing an actual network channel.
     */
    private static final class StubServerConnection extends AbstractServerConnection {
        private boolean terminateRequestChannelCalled;
        private RuntimeException requestTerminationFailure;
        private Error requestTerminationError;

        private StubServerConnection() {
            super(null, null, null, OptionMap.EMPTY, 0);
        }

        @Override
        public Pool<ByteBuffer> getBufferPool() {
            return null;
        }

        @Override
        public ByteBufferPool getByteBufferPool() {
            return null;
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }

        @Override
        public XnioIoThread getIoThread() {
            return null;
        }

        @Override
        public HttpServerExchange sendOutOfBandResponse(final HttpServerExchange exchange) {
            throw new UnsupportedOperationException();
        }

        @Override
        public boolean isContinueResponseSupported() {
            return false;
        }

        @Override
        public void terminateRequestChannel(final HttpServerExchange exchange) {
            terminateRequestChannelCalled = true;
            if (requestTerminationFailure != null) {
                throw requestTerminationFailure;
            }
