        final HttpServerExchange exchange = newExchange();
        final RecordingSecurityContext securityContext = new RecordingSecurityContext();

        final AuthenticationMechanismOutcome outcome =
                newMechanism(FormParserFactory.builder(false).build(), null, null)
                        .runFormAuth(exchange, securityContext.proxy());

        assertEquals(AuthenticationMechanismOutcome.NOT_AUTHENTICATED, outcome);
        assertEquals(0, securityContext.identityManagerLookups);
        assertFalse(exchange.isComplete());
    }

