    @Test
    void authenticatesValidCredentialsUsingConfiguredIdentityManager() {
        final FormData formData = credentials("alice", "s3cret");
        final TestAccount account = new TestAccount("alice");
        final RecordingIdentityManager configuredIdentityManager = new RecordingIdentityManager(account);
        final RecordingIdentityManager contextIdentityManager = new RecordingIdentityManager(new TestAccount("wrong"));
        final RecordingSecurityContext securityContext = new RecordingSecurityContext();
        securityContext.identityManager = contextIdentityManager;
        final RedirectRecordingMechanism mechanism =
                new RedirectRecordingMechanism(factoryFor(parserFor(formData)), MECHANISM_NAME, configuredIdentityManager);
        final HttpServerExchange exchange = newExchange();

        final AuthenticationMechanismOutcome outcome = mechanism.runFormAuth(exchange, securityContext.proxy());

        assertEquals(AuthenticationMechanismOutcome.AUTHENTICATED, outcome);
        assertEquals(1, configuredIdentityManager.verifyCalls);
        assertEquals("alice", configuredIdentityManager.verifiedId);
        assertInstanceOf(PasswordCredential.class, configuredIdentityManager.verifiedCredential);
        assertArrayEquals("s3cret".toCharArray(),
                ((PasswordCredential) configuredIdentityManager.verifiedCredential).getPassword());
        assertEquals(0, contextIdentityManager.verifyCalls);
        assertEquals(0, securityContext.identityManagerLookups);
        assertSame(account, securityContext.completedAccount);
        assertEquals(MECHANISM_NAME, securityContext.completedMechanismName);
        assertEquals(Boolean.TRUE, securityContext.cachingRequired);
        assertEquals(1, mechanism.redirectBackCalls);
        assertTrue(exchange.isComplete());
    }

    @Test
