    @Test
    void successfulAuthenticationRestoresSessionAndRedirectsToOriginalLocation() {
        final FormData formData = credentials("carol", "secret");
        final TestAccount account = new TestAccount("carol");
        final RecordingIdentityManager identityManager = new RecordingIdentityManager(account);
        final RecordingSecurityContext securityContext = new RecordingSecurityContext();
        securityContext.identityManager = identityManager;
        final HttpServerExchange exchange = newExchange();
        final RecordingSession recordingSession = new RecordingSession();
        recordingSession.attributes.put(FormAuthenticationMechanism.LOCATION_ATTRIBUTE, "/original/page?x=1");
        recordingSession.attributes.put(FormAuthenticationMechanism.ORIGINAL_SESSION_TIMEOUT, 45);
        recordingSession.maxInactiveInterval = 1000;
        attachSession(exchange, recordingSession.proxy());

        final AuthenticationMechanismOutcome outcome =
                newMechanism(factoryFor(parserFor(formData)), MECHANISM_NAME, null)
                        .runFormAuth(exchange, securityContext.proxy());

        assertEquals(AuthenticationMechanismOutcome.AUTHENTICATED, outcome);
        assertEquals(45, recordingSession.maxInactiveInterval);
        assertEquals(1, recordingSession.maxInactiveIntervalSetCalls);
        assertFalse(recordingSession.attributes.containsKey(FormAuthenticationMechanism.LOCATION_ATTRIBUTE));
        assertEquals("/original/page?x=1", exchange.getResponseHeaders().getFirst(Headers.LOCATION));
        assertEquals(StatusCodes.FOUND, exchange.getStatusCode());
        assertTrue(exchange.isComplete());
    }

