    private static FormData credentials(final String username, final String password) {
        final FormData formData = new FormData(10);
        formData.add("j_username", username);
        formData.add("j_password", password);
        return formData;
    }

    private static StubFormDataParser parserFor(final FormData formData) {
        return new StubFormDataParser(formData, null, null, null);
    }

    private static FormParserFactory factoryFor(final FormDataParser parser) {
        return FormParserFactory.builder(false)
                .addParser(new FormParserFactory.ParserDefinition<FormDataParser>() {
                    @Override
                    public FormDataParser create(final HttpServerExchange exchange) {
                        return parser;
                    }

                    @Override
                    public FormDataParser setDefaultEncoding(final String charset) {
                        return parser;
                    }
                })
                .build();
    }

    private static FormAuthenticationMechanism newMechanism(final FormParserFactory factory,
                                                             final String name,
                                                             final IdentityManager identityManager) {
        return new FormAuthenticationMechanism(factory, name, "/login", "/error",
                FormAuthenticationMechanism.DEFAULT_POST_LOCATION, identityManager);
    }

    private static HttpServerExchange newExchange() {
        return newExchange(new StubServerConnection());
    }

    private static HttpServerExchange newExchange(final ServerConnection connection) {
        final HttpServerExchange exchange = new HttpServerExchange(connection);
        exchange.setRequestMethod(Methods.POST);
        exchange.setRequestPath(FormAuthenticationMechanism.DEFAULT_POST_LOCATION);
        exchange.setRequestURI(FormAuthenticationMechanism.DEFAULT_POST_LOCATION);
        return exchange;
    }

    private static void attachSession(final HttpServerExchange exchange, final Session session) {
        final SessionManager sessionManager = (SessionManager) Proxy.newProxyInstance(
                SessionManager.class.getClassLoader(), new Class<?>[]{SessionManager.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("getSession")
                            && args != null && args.length == 2 && args[0] instanceof HttpServerExchange) {
                        return session;
                    }
                    return defaultValue(method.getReturnType());
                });
        final SessionConfig sessionConfig = (SessionConfig) Proxy.newProxyInstance(
                SessionConfig.class.getClassLoader(), new Class<?>[]{SessionConfig.class},
                (proxy, method, args) -> defaultValue(method.getReturnType()));
        exchange.putAttachment(SessionManager.ATTACHMENT_KEY, sessionManager);
        exchange.putAttachment(SessionConfig.ATTACHMENT_KEY, sessionConfig);
    }

    private static Object defaultValue(final Class<?> type) {
        if (!type.isPrimitive() || type == void.class) {
            return null;
        }
        if (type == boolean.class) {
            return false;
        }
        if (type == char.class) {
            return (char) 0;
        }
        if (type == byte.class) {
            return (byte) 0;
        }
        if (type == short.class) {
            return (short) 0;
        }
        if (type == int.class) {
            return 0;
        }
        if (type == long.class) {
            return 0L;
        }
        if (type == float.class) {
            return 0F;
        }
        if (type == double.class) {
            return 0D;
        }
        return null;
    }

    private static final class RedirectRecordingMechanism extends FormAuthenticationMechanism {
        private int redirectBackCalls;
        private RuntimeException redirectFailure;

        private RedirectRecordingMechanism(final FormParserFactory factory,
                                           final String name,
                                           final IdentityManager identityManager) {
            super(factory, name, "/login", "/error", DEFAULT_POST_LOCATION, identityManager);
        }

        @Override
        protected void handleRedirectBack(final HttpServerExchange exchange) {
            redirectBackCalls++;
            if (redirectFailure != null) {
                throw redirectFailure;
            }
        }
    }

    private static final class StubFormDataParser implements FormDataParser {
        private final FormData formData;
        private final IOException ioFailure;
        private final RuntimeException runtimeFailure;
        private final Error errorFailure;

        private StubFormDataParser(final FormData formData,
                                   final IOException ioFailure,
                                   final RuntimeException runtimeFailure,
                                   final Error errorFailure) {
            this.formData = formData;
            this.ioFailure = ioFailure;
            this.runtimeFailure = runtimeFailure;
            this.errorFailure = errorFailure;
        }

        @Override
        public void parse(final io.undertow.server.HttpHandler next) {
            throw new UnsupportedOperationException();
        }

        @Override
        public FormData parseBlocking() throws IOException {
            if (ioFailure != null) {
                throw ioFailure;
            }
            if (runtimeFailure != null) {
                throw runtimeFailure;
            }
            if (errorFailure != null) {
                throw errorFailure;
            }
            return formData;
        }

        @Override
        public void close() {
        }

        @Override
        public void setCharacterEncoding(final String encoding) {
        }
    }

    private static final class RecordingIdentityManager implements IdentityManager {
        private final Account account;
        private RuntimeException runtimeFailure;
        private Error errorFailure;
        private int verifyCalls;
        private String verifiedId;
        private Credential verifiedCredential;

        private RecordingIdentityManager() {
            this(null);
        }

        private RecordingIdentityManager(final Account account) {
            this.account = account;
        }

        @Override
        public Account verify(final Account account) {
            return null;
        }

        @Override
        public Account verify(final String id, final Credential credential) {
            verifyCalls++;
            verifiedId = id;
            verifiedCredential = credential;
            if (runtimeFailure != null) {
                throw runtimeFailure;
            }
            if (errorFailure != null) {
                throw errorFailure;
            }
            return account;
        }

        @Override
        public Account verify(final Credential credential) {
            return null;
        }
    }

    private static final class RecordingSecurityContext implements InvocationHandler {
        private IdentityManager identityManager;
        private int identityManagerLookups;
        private Account completedAccount;
        private String completedMechanismName;
        private Boolean cachingRequired;
        private String failedMessage;
        private String failedMechanismName;
        private RuntimeException authenticationCompleteFailure;
        private RuntimeException authenticationFailedFailure;

        private SecurityContext proxy() {
            return (SecurityContext) Proxy.newProxyInstance(
                    SecurityContext.class.getClassLoader(), new Class<?>[]{SecurityContext.class}, this);
        }

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
            final String methodName = method.getName();
            if (methodName.equals("getIdentityManager")) {
                identityManagerLookups++;
                return identityManager;
            }
            if (methodName.equals("authenticationComplete")) {
                completedAccount = (Account) args[0];
                completedMechanismName = (String) args[1];
                cachingRequired = (Boolean) args[2];
                if (authenticationCompleteFailure != null) {
                    throw authenticationCompleteFailure;
                }
                return null;
            }
            if (methodName.equals("authenticationFailed")) {
                failedMessage = (String) args[0];
                failedMechanismName = (String) args[1];
                if (authenticationFailedFailure != null) {
                    throw authenticationFailedFailure;
                }
                return null;
            }
            if (methodName.equals("toString")) {
                return "RecordingSecurityContext";
            }
            if (methodName.equals("hashCode")) {
                return System.identityHashCode(proxy);
            }
            if (methodName.equals("equals")) {
                return proxy == args[0];
            }
            return defaultValue(method.getReturnType());
        }
    }

    private static final class RecordingSession implements InvocationHandler {
        private final Map<String, Object> attributes = new HashMap<>();
        private int maxInactiveInterval;
        private int maxInactiveIntervalSetCalls;

        private Session proxy() {
            return (Session) Proxy.newProxyInstance(
                    Session.class.getClassLoader(), new Class<?>[]{Session.class}, this);
        }

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) {
            final String methodName = method.getName();
            if (methodName.equals("removeAttribute")) {
                return attributes.remove((String) args[0]);
            }
            if (methodName.equals("getAttribute")) {
                return attributes.get((String) args[0]);
            }
            if (methodName.equals("setAttribute")) {
                return attributes.put((String) args[0], args[1]);
            }
            if (methodName.equals("getAttributeNames")) {
                return new HashSet<>(attributes.keySet());
            }
            if (methodName.equals("setMaxInactiveInterval")) {
                maxInactiveIntervalSetCalls++;
                maxInactiveInterval = (Integer) args[0];
                return null;
            }
            if (methodName.equals("getMaxInactiveInterval")) {
                return maxInactiveInterval;
            }
            if (methodName.equals("getId")) {
                return "test-session";
            }
            if (methodName.equals("isInvalid")) {
                return false;
            }
            if (methodName.equals("toString")) {
                return "RecordingSession";
            }
            if (methodName.equals("hashCode")) {
                return System.identityHashCode(proxy);
            }
            if (methodName.equals("equals")) {
                return proxy == args[0];
            }
            return defaultValue(method.getReturnType());
        }
    }

