    /**
     * Source conduit that serves a fixed byte array and then reports end of stream.
     */
    private static final class TestSourceConduit implements StreamSourceConduit {

        private final byte[] data;
        private int position;
        private boolean readShutdown;
        private boolean failOnRead;

        private TestSourceConduit(byte[] data) {
            this.data = data;
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            if (failOnRead) {
                throw new IOException("read failure");
            }
            if (readShutdown || position >= data.length) {
                return -1;
            }
            int count = Math.min(dst.remaining(), data.length - position);
            dst.put(data, position, count);
            position += count;
            return count;
        }

        @Override
        public long read(ByteBuffer[] dsts, int offs, int len) throws IOException {
            long total = 0;
            for (int i = offs; i < offs + len; i++) {
                if (!dsts[i].hasRemaining()) {
                    continue;
                }
                int read = read(dsts[i]);
                if (read == -1) {
                    return total == 0 ? -1 : total;
                }
                total += read;
                if (read == 0) {
                    break;
                }
            }
            return total;
        }

        @Override
        public long transferTo(long position, long count, FileChannel target) throws IOException {
            throw new UnsupportedOperationException();
