    @Test
    void zeroMaxBufferedRequestSizeThrowsPeerUnverifiedException() {
        TestByteBufferPool pool = new TestByteBufferPool(8);
        TestServerConnection connection = new TestServerConnection(pool, new TestSourceConduit(new byte[] {1, 2, 3}), 0);
        HttpServerExchange exchange = new HttpServerExchange(connection);
        RecordingConnectionSSLSessionInfo info = new RecordingConnectionSSLSessionInfo();

        SSLPeerUnverifiedException exception = assertThrows(SSLPeerUnverifiedException.class,
                () -> info.renegotiateBufferRequest(exchange, NEW_AUTH_MODE));

        assertEquals("", exception.getMessage());
        assertEquals(0, pool.allocated.size(), "No buffer should be allocated when buffering is disabled");
        assertFalse(info.renegotiateCalled, "Renegotiation must not start when buffering is disabled");
        assertNull(Connectors.getExistingRequestChannel(exchange));
        assertNull(exchange.getAttachment(HttpServerExchange.BUFFERED_REQUEST_DATA));
    }

