        SSLPeerUnverifiedException exception = assertThrows(SSLPeerUnverifiedException.class,
                () -> info.renegotiateBufferRequest(exchange, NEW_AUTH_MODE));

        assertEquals("", exception.getMessage());
        assertEquals(0, pool.allocated.size(), "No buffer should be allocated when buffering is disabled");
        assertFalse(info.renegotiateCalled, "Renegotiation must not start when buffering is disabled");
        assertNull(Connectors.getExistingRequestChannel(exchange));
    }

    @Test
