        TestByteBufferPool pool = new TestByteBufferPool(8);
        TestSourceConduit source = new TestSourceConduit(new byte[] {10, 20, 30});
        TestServerConnection connection = new TestServerConnection(pool, source, 8);
        HttpServerExchange exchange = new HttpServerExchange(connection);
        RecordingConnectionSSLSessionInfo info = new RecordingConnectionSSLSessionInfo();

        info.renegotiateBufferRequest(exchange, NEW_AUTH_MODE);

        assertTrue(info.renegotiateCalled, "Renegotiation should be started after buffering the request");
        assertSame(exchange, info.renegotiationExchange);
