@Test
void requestExactlyMaxSizeButSmallerThanBufferIsAccepted() throws IOException {
    TestByteBufferPool pool = new TestByteBufferPool(8);
    TestSourceConduit source = new TestSourceConduit(new byte[] {1, 2, 3});
    TestServerConnection connection = new TestServerConnection(pool, source, 3);
