@Test
void defaultMaxBufferedRequestSizeIsUsedWhenNotConfigured() throws IOException {
    TestByteBufferPool pool = new TestByteBufferPool(8);
    TestSourceConduit source = new TestSourceConduit(new byte[] {4, 5, 6});
    TestServerConnection connection = new TestServerConnection(pool, source);
    HttpServerExchange exchange = new HttpServerExchange(connection);
    RecordingConnectionSSLSessionInfo info = new RecordingConnectionSSLSessionInfo();

    info.renegotiateBufferRequest(exchange, NEW_AUTH_MODE);

    assertTrue(info.renegotiateCalled);
    PooledByteBuffer[] buffered = exchange.getAttachment(HttpServerExchange.BUFFERED_REQUEST_DATA);
    int expectedBuffers = (UndertowOptions.DEFAULT_MAX_BUFFERED_REQUEST_SIZE + 7) / 8;
    assertEquals(expectedBuffers, buffered.length);
