package io.undertow.server;

import io.undertow.UndertowOptions;
import io.undertow.util.BadRequestException;
import io.undertow.util.ParameterLimitException;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Deque;
import java.util.Map;

import static org.easymock.EasyMock.createMock;
import static org.easymock.EasyMock.expect;
import static org.easymock.EasyMock.replay;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ConnectorsSetExchangeRequestPathTests {

    private static final int DEFAULT_MAX_PARAMETERS = 1000;

    @Test
    void plainPathIsStoredAsRequestPathRelativePathAndUri() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/foo/bar", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/foo/bar", exchange.getRequestPath());
        assertEquals("/foo/bar", exchange.getRelativePath());
        assertEquals("/foo/bar", exchange.getRequestURI());
        assertEquals("", exchange.getQueryString());
        assertEquals("", exchange.getDecodedQueryString());
        assertTrue(exchange.getQueryParameters().isEmpty());
        assertTrue(exchange.getPathParameters().isEmpty());
    }

    @Test
    void percentEncodedPathIsDecodedButRequestUriRemainsEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a%20b/%2Fc%2Bd", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b/%2Fc+d", exchange.getRequestPath());
        assertEquals("/a b/%2Fc+d", exchange.getRelativePath());
        assertEquals("/a%20b/%2Fc%2Bd", exchange.getRequestURI());
    }

    @Test
    void encodedSlashIsDecodedOnlyWhenSlashDecodingIsEnabled() throws Exception {
        HttpServerExchange withoutSlashDecoding = exchangeWith(OptionMap.EMPTY);
        setPath(withoutSlashDecoding, "/a%2Fb", true, true, false, DEFAULT_MAX_PARAMETERS);
        assertEquals("/a%2Fb", withoutSlashDecoding.getRequestPath());

        HttpServerExchange withSlashDecoding = exchangeWith(OptionMap.EMPTY);
        setPath(withSlashDecoding, "/a%2Fb", true, true, true, DEFAULT_MAX_PARAMETERS);
        assertEquals("/a/b", withSlashDecoding.getRequestPath());
    }

    @Test
    void plusInPathIsKeptBecauseItIsNotFormEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a+b", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a+b", exchange.getRequestPath());
        assertEquals("/a+b", exchange.getRequestURI());
    }

    @Test
    void configuredCharsetIsUsedForPathDecoding() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        Connectors.setExchangeRequestPath(exchange, "/caf%E9", "ISO-8859-1", true, true, false,
                new StringBuilder(), DEFAULT_MAX_PARAMETERS);

        assertEquals("/caf\u00e9", exchange.getRequestPath());
        assertEquals("/caf%E9", exchange.getRequestURI());
    }

    @Test
    void queryStringIsKeptEncodedWhileQueryParametersAreDecoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/items%20list?name=John+Doe&city=S%C3%A3o%20Paulo",
                true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/items list", exchange.getRequestPath());
        assertEquals("/items list", exchange.getRelativePath());
        assertEquals("/items list", exchange.getRequestURI());
        assertEquals("name=John+Doe&city=S%C3%A3o%20Paulo", exchange.getQueryString());
        assertEquals("name=John+Doe&city=S\u00e3o Paulo", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "name", "John Doe");
        assertParam(exchange.getQueryParameters(), "city", "S\u00e3o Paulo");
    }

    @Test
    void decodingTriggeredOnlyByQuerySetsDecodedQueryStringButLeavesUriEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/search?q=a+b&raw=a%20b", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/search", exchange.getRequestPath());
        assertEquals("/search", exchange.getRequestURI());
        assertEquals("q=a+b&raw=a%20b", exchange.getQueryString());
        assertEquals("q=a+b&raw=a b", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "q", "a b");
        assertParam(exchange.getQueryParameters(), "raw", "a b");
    }

    @Test
    void decodedQueryStringIsUnavailableWhenUnescapedCharactersAreNotAllowed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a%20b?x=c%20d", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("/a%20b", exchange.getRequestURI());
        assertEquals("x=c%20d", exchange.getQueryString());
        assertEquals("x=c%20d", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c d");
    }

    @Test
    void decodeQueryStringFlagControlsParametersButNotDecodedQueryString() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%20b?x=c%20d&y=e+f", true, false, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("x=c%20d&y=e+f", exchange.getQueryString());
        assertEquals("x=c d&y=e+f", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c%20d");
        assertParam(exchange.getQueryParameters(), "y", "e+f");
    }

    @Test
    void disablingPathDecodingLeavesPathEncodedButCanStillDecodeQueryParameters() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%20b?x=c%20d", false, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a%20b", exchange.getRequestPath());
        assertEquals("/a%20b", exchange.getRequestURI());
        assertEquals("x=c%20d", exchange.getQueryString());
        assertEquals("x=c%20d", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c d");
    }

    @Test
    void emptyQueryStringIsHandled() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path?", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path", exchange.getRequestPath());
        assertEquals("/path", exchange.getRequestURI());
        assertEquals("", exchange.getQueryString());
        assertEquals("", exchange.getDecodedQueryString());
        assertTrue(exchange.getQueryParameters().isEmpty());
    }

    @Test
    void slashDecodingFlagDoesNotPreventQueryParameterSlashDecoding() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%2Fb?q=x%2Fy", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a%2Fb", exchange.getRequestPath());
        assertEquals("/a%2Fb", exchange.getRequestURI());
        assertEquals("q=x%2Fy", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "q", "x/y");
    }

    @Test
    void pathParametersAreParsedAndRemovedFromRequestPath() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path;foo=bar/baz", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path/baz", exchange.getRequestPath());
        assertEquals("/path/baz", exchange.getRelativePath());
        assertEquals("/path;foo=bar/baz", exchange.getRequestURI());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertTrue(exchange.getQueryParameters().isEmpty());
    }

    @Test
    void multiplePathParameterSegmentsAreAllParsed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a;x=1/b;y=2/c", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a/b/c", exchange.getRequestPath());
        assertEquals("/a;x=1/b;y=2/c", exchange.getRequestURI());
        assertParam(exchange.getPathParameters(), "x", "1");
        assertParam(exchange.getPathParameters(), "y", "2");
    }

    @Test
    void multipleParametersInOnePathSegmentAreParsed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path;foo=bar;baz=qux/x", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path/x", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getPathParameters(), "baz", "qux");
    }

    @Test
    void pathParameterParsingStopsAtQueryString() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path;foo=bar?x=1", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path", exchange.getRequestPath());
        assertEquals("/path;foo=bar", exchange.getRequestURI());
        assertEquals("x=1", exchange.getQueryString());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getQueryParameters(), "x", "1");
    }

    @Test
    void encodedPathParametersBeforeAQueryProduceDecodedRequestUri() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%20b;foo=bar?x=1", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("/a b;foo=bar", exchange.getRequestURI());
        assertEquals("x=1", exchange.getQueryString());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getQueryParameters(), "x", "1");
    }

    @Test
    void queryParameterLimitAtBoundaryIsAccepted() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/x?a=1&b=2", true, true, false, 2);

        assertParam(exchange.getQueryParameters(), "a", "1");
        assertParam(exchange.getQueryParameters(), "b", "2");
    }

    @Test
    void exceedingQueryParameterLimitThrows() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(ParameterLimitException.class,
                () -> setPath(exchange, "/x?a=1&b=2", true, true, false, 1));
    }

    @Test
    void pathParameterLimitAtBoundaryIsAccepted() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/x;a=1;b=2", true, true, false, 2);

        assertEquals("/x", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "a", "1");
        assertParam(exchange.getPathParameters(), "b", "2");
    }

    @Test
    void exceedingPathParameterLimitThrows() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(ParameterLimitException.class,
                () -> setPath(exchange, "/x;a=1;b=2", true, true, false, 1));
    }

    @Test
    void invalidRequestTargetCharacterIsRejectedByDefault() {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(BadRequestException.class,
                () -> setPath(exchange, "/bad path", true, true, false, DEFAULT_MAX_PARAMETERS));
    }

    @Test
    void invalidRequestTargetCharacterIsAcceptedWhenOptionAllowsIt() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/bad path", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/bad path", exchange.getRequestPath());
        assertEquals("/bad path", exchange.getRequestURI());
    }

    @Test
    void semicolonOnlyParameterWithEmptyValueIsParsed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a;flag/c", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a/c", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "flag", "");
        assertFalse(exchange.getPathParameters().containsKey(""));
    }

    private static HttpServerExchange exchangeWith(OptionMap options) {
        ServerConnection connection = createMock(ServerConnection.class);
        expect(connection.getUndertowOptions()).andReturn(options);
        replay(connection);
        return new HttpServerExchange(connection);
    }

    private static OptionMap allowUnescapedCharactersInUrl(boolean allow) {
        return OptionMap.builder()
                .set(UndertowOptions.ALLOW_UNESCAPED_CHARACTERS_IN_URL, allow)
                .getMap();
    }

    private static void setPath(HttpServerExchange exchange, String encodedPath, boolean decode,
                                boolean decodeQueryString, boolean decodeSlash, int maxParameters)
            throws ParameterLimitException, BadRequestException {
        Connectors.setExchangeRequestPath(exchange, encodedPath, StandardCharsets.UTF_8.name(),
                decode, decodeQueryString, decodeSlash, new StringBuilder(), maxParameters);
    }

    private static void assertParam(Map<String, Deque<String>> parameters, String name, String... expected) {
        Deque<String> values = parameters.get(name);
        assertTrue(values != null, "Missing parameter: " + name);
        assertEquals(Arrays.asList(expected), Arrays.asList(values.toArray(new String[0])));
    }
}
