    @Test
    void decodingTriggeredOnlyByQuerySetsDecodedQueryStringButLeavesUriEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/search?q=a+b&raw=a%20b", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/search", exchange.getRequestPath());
        assertEquals("/search", exchange.getRequestURI());
        assertEquals("q=a+b&raw=a%20b", exchange.getQueryString());
        assertEquals("q=a+b&raw=a b", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "q", "a b");
        assertParam(exchange.getQueryParameters(), "raw", "a b");
    }

    @Test
    void decodedQueryStringIsUnavailableWhenUnescapedCharactersAreNotAllowed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a%20b?x=c%20d", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("/a%20b", exchange.getRequestURI());
        assertEquals("x=c%20d", exchange.getQueryString());
        assertEquals("x=c%20d", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c d");
    }

    @Test
    void decodeQueryStringFlagControlsParametersButNotDecodedQueryString() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%20b?x=c%20d&y=e+f", true, false, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("x=c%20d&y=e+f", exchange.getQueryString());
        assertEquals("x=c d&y=e+f", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c%20d");
        assertParam(exchange.getQueryParameters(), "y", "e+f");
    }

    @Test
    void disablingPathDecodingLeavesPathEncodedButCanStillDecodeQueryParameters() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%20b?x=c%20d", false, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a%20b", exchange.getRequestPath());
        assertEquals("/a%20b", exchange.getRequestURI());
        assertEquals("x=c%20d", exchange.getQueryString());
        assertEquals("x=c%20d", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "x", "c d");
    }

    @Test
    void emptyQueryStringIsHandled() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path?", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path", exchange.getRequestPath());
        assertEquals("/path", exchange.getRequestURI());
        assertEquals("", exchange.getQueryString());
        assertEquals("", exchange.getDecodedQueryString());
        assertTrue(exchange.getQueryParameters().isEmpty());
    }

    @Test
    void slashDecodingFlagDoesNotPreventQueryParameterSlashDecoding() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/a%2Fb?q=x%2Fy", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a%2Fb", exchange.getRequestPath());
        assertEquals("/a%2Fb", exchange.getRequestURI());
        assertEquals("q=x%2Fy", exchange.getDecodedQueryString());
        assertParam(exchange.getQueryParameters(), "q", "x/y");
    }

