        assertEquals("/path/baz", exchange.getRequestPath());
        assertEquals("/path/baz", exchange.getRelativePath());
        assertEquals("/path;foo=bar/baz", exchange.getRequestURI());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertTrue(exchange.getQueryParameters().isEmpty());
