        setPath(exchange, "/a;x=1/b;y=2/c", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a/b/c", exchange.getRequestPath());
        assertEquals("/a;x=1/b;y=2/c", exchange.getRequestURI());
        assertParam(exchange.getPathParameters(), "x", "1");
        assertParam(exchange.getPathParameters(), "y", "2");
    }

    @Test
    void multipleParametersInOnePathSegmentAreParsed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path;foo=bar;baz=qux/x", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path/x", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getPathParameters(), "baz", "qux");
    }

    @Test
    void pathParameterParsingStopsAtQueryString() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/path;foo=bar?x=1", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/path", exchange.getRequestPath());
        assertEquals("/path;foo=bar", exchange.getRequestURI());
        assertEquals("x=1", exchange.getQueryString());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getQueryParameters(), "x", "1");
    }

    @Test
    void encodedPathParametersBeforeAQueryProduceDecodedRequestUri() throws Exception {
