        setPath(exchange, "/a%20b;foo=bar?x=1", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b", exchange.getRequestPath());
        assertEquals("/a b;foo=bar", exchange.getRequestURI());
        assertEquals("x=1", exchange.getQueryString());
        assertParam(exchange.getPathParameters(), "foo", "bar");
        assertParam(exchange.getQueryParameters(), "x", "1");
    }

    @Test
    void queryParameterLimitAtBoundaryIsAccepted() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/x?a=1&b=2", true, true, false, 2);

        assertParam(exchange.getQueryParameters(), "a", "1");
        assertParam(exchange.getQueryParameters(), "b", "2");
    }

    @Test
    void exceedingQueryParameterLimitThrows() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(ParameterLimitException.class,
                () -> setPath(exchange, "/x?a=1&b=2", true, true, false, 1));
    }

    @Test
    void pathParameterLimitAtBoundaryIsAccepted() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/x;a=1;b=2", true, true, false, 2);

        assertEquals("/x", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "a", "1");
        assertParam(exchange.getPathParameters(), "b", "2");
    }

    @Test
    void exceedingPathParameterLimitThrows() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(ParameterLimitException.class,
                () -> setPath(exchange, "/x;a=1;b=2", true, true, false, 1));
    }

    @Test
    void invalidRequestTargetCharacterIsRejectedByDefault() {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        assertThrows(BadRequestException.class,
                () -> setPath(exchange, "/bad path", true, true, false, DEFAULT_MAX_PARAMETERS));
    }

    @Test
    void invalidRequestTargetCharacterIsAcceptedWhenOptionAllowsIt() throws Exception {
        HttpServerExchange exchange = exchangeWith(allowUnescapedCharactersInUrl(true));

        setPath(exchange, "/bad path", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/bad path", exchange.getRequestPath());
        assertEquals("/bad path", exchange.getRequestURI());
    }

    @Test
    void semicolonOnlyParameterWithEmptyValueIsParsed() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a;flag/c", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a/c", exchange.getRequestPath());
        assertParam(exchange.getPathParameters(), "flag", "");
        assertFalse(exchange.getPathParameters().containsKey(""));
    }

    private static HttpServerExchange exchangeWith(OptionMap options) {
        ServerConnection connection = createMock(ServerConnection.class);
        expect(connection.getUndertowOptions()).andReturn(options);
        replay(connection);
        return new HttpServerExchange(connection);
    }

    private static OptionMap allowUnescapedCharactersInUrl(boolean allow) {
        return OptionMap.builder()
                .set(UndertowOptions.ALLOW_UNESCAPED_CHARACTERS_IN_URL, allow)
                .getMap();
    }

    private static void setPath(HttpServerExchange exchange, String encodedPath, boolean decode,
                                boolean decodeQueryString, boolean decodeSlash, int maxParameters)
            throws ParameterLimitException, BadRequestException {
        Connectors.setExchangeRequestPath(exchange, encodedPath, StandardCharsets.UTF_8.name(),
                decode, decodeQueryString, decodeSlash, new StringBuilder(), maxParameters);
    }

    private static void assertParam(Map<String, Deque<String>> parameters, String name, String... expected) {
        Deque<String> values = parameters.get(name);
        assertTrue(values != null, "Missing parameter: " + name);
        assertEquals(Arrays.asList(expected), Arrays.asList(values.toArray(new String[0])));
    }
