package io.undertow.server.handlers;

import static io.undertow.server.handlers.ForwardedHandler.Token.BY;
import static io.undertow.server.handlers.ForwardedHandler.Token.FOR;
import static io.undertow.server.handlers.ForwardedHandler.Token.HOST;
import static io.undertow.server.handlers.ForwardedHandler.Token.PROTO;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for the package private {@code ForwardedHandler#parseHeader(String, Map)} method,
 * which parses a single RFC 7239 {@code Forwarded} header value into the supplied map.
 */
class ForwardedHandlerParseHeaderTests {

    private static Map<ForwardedHandler.Token, String> parse(final String header) {
        final Map<ForwardedHandler.Token, String> response = new HashMap<>();
        ForwardedHandler.parseHeader(header, response);
        return response;
    }

    private static Map<ForwardedHandler.Token, String> mapOf(final Object... keyValues) {
        final Map<ForwardedHandler.Token, String> map = new HashMap<>();
        for (int i = 0; i < keyValues.length; i += 2) {
            map.put((ForwardedHandler.Token) keyValues[i], (String) keyValues[i + 1]);
        }
        return map;
    }

    @Nested
    @DisplayName("Well formed headers")
    class WellFormedHeaders {

        @Test
        @DisplayName("all three parameters of the RFC example are parsed")
        void parsesAllParameters() {
            final Map<ForwardedHandler.Token, String> result = parse("for=192.0.2.60;proto=http;by=203.0.113.43");
            assertEquals(mapOf(FOR, "192.0.2.60", PROTO, "http", BY, "203.0.113.43"), result);
        }

        @Test
        @DisplayName("a single parameter without any separator is parsed")
        void parsesSingleParameter() {
            assertEquals(mapOf(HOST, "example.com"), parse("host=example.com"));
        }

        @Test
        @DisplayName("unquoted value keeps its colons (ip:port notation)")
        void unquotedValueWithPort() {
            assertEquals(mapOf(FOR, "192.0.2.60:47011"), parse("for=192.0.2.60:47011"));
        }

        @Test
        @DisplayName("quoted value is returned without the surrounding quotes")
        void quotedValue() {
            assertEquals(mapOf(FOR, "192.0.2.60:47011"), parse("for=\"192.0.2.60:47011\""));
        }

        @Test
        @DisplayName("quoted value may contain separator characters")
        void quotedValueWithSeparators() {
            assertEquals(mapOf(HOST, "a;b,c d"), parse("host=\"a;b,c d\""));
        }

        @Test
        @DisplayName("quoted brackets (ipv6 obfnode style) are kept verbatim")
        void quotedIpv6Value() {
            assertEquals(mapOf(FOR, "[2001:db8:cafe::17]:4711"), parse("for=\"[2001:db8:cafe::17]:4711\""));
        }

        @Test
        @DisplayName("an empty quoted value is stored as an empty string")
        void emptyQuotedValue() {
            final Map<ForwardedHandler.Token, String> result = parse("for=\"\"");
            assertEquals(1, result.size());
            assertEquals("", result.get(FOR));
        }

        @Test
        @DisplayName("a comma separates parameter pairs just like a semicolon")
        void commaSeparatedPairs() {
            assertEquals(mapOf(FOR, "192.0.2.60", PROTO, "https"), parse("for=192.0.2.60,proto=https"));
        }

        @Test
        @DisplayName("whitespace may surround the parameter name and the value")
        void whitespaceAroundNameAndValue() {
            assertEquals(mapOf(FOR, "192.0.2.60", PROTO, "http"),
                    parse("   for=   192.0.2.60   ;  proto=   http   "));
        }

        @Test
        @DisplayName("a trailing separator is tolerated")
        void trailingSeparator() {
            assertEquals(mapOf(FOR, "192.0.2.60"), parse("for=192.0.2.60;"));
            assertEquals(mapOf(FOR, "192.0.2.60"), parse("for=192.0.2.60,"));
        }

        @Test
        @DisplayName("names are matched case insensitively")
        void namesAreCaseInsensitive() {
            assertEquals(mapOf(FOR, "1.2.3.4", HOST, "example.com", PROTO, "http", BY, "5.6.7.8"),
                    parse("FoR=1.2.3.4;hOsT=example.com;PROTO=http;by=5.6.7.8"));
        }

        @Test
        @DisplayName("an empty header yields no entries and does not throw")
        void emptyHeader() {
            assertTrue(parse("").isEmpty());
        }

        @Test
        @DisplayName("a header consisting only of whitespace and separators yields no entries")
        void blankHeader() {
            assertTrue(parse("   ").isEmpty());
            assertTrue(parse(" ; ; ").isEmpty());
        }

        @Test
        @DisplayName("all four tokens can be collected from a single header")
        void allFourTokens() {
            final Map<ForwardedHandler.Token, String> result =
                    parse("for=1.2.3.4;proto=http;host=example.com;by=5.6.7.8");
            assertEquals(mapOf(FOR, "1.2.3.4", PROTO, "http", HOST, "example.com", BY, "5.6.7.8"), result);
        }
    }

    @Nested
    @DisplayName("Quoted value escapes")
    class EscapedValues {

        @Test
        @DisplayName("escaped double quotes are unescaped inside a quoted value")
        void escapedQuotes() {
            assertEquals(mapOf(FOR, "\"a\""), parse("for=\"\\\"a\\\"\""));
        }

        @Test
        @DisplayName("an escaped backslash collapses to a single backslash")
        void escapedBackslash() {
            assertEquals(mapOf(FOR, "a\\b"), parse("for=\"a\\\\b\""));
        }

        @Test
        @DisplayName("a backslash escapes any following character")
        void escapedRegularCharacter() {
            assertEquals(mapOf(FOR, "anb"), parse("for=\"a\\nb\""));
            assertEquals(mapOf(FOR, "a;b"), parse("for=\"a\\;b\""));
        }

        @Test
        @DisplayName("an unquoted value is not unescaped")
        void unquotedValueIsNotUnescaped() {
            assertEquals(mapOf(FOR, "a\\b"), parse("for=a\\b;"));
        }

        @Test
        @DisplayName("escape processing state does not leak into the next parameter")
        void escapeStateIsResetBetweenParameters() {
            final Map<ForwardedHandler.Token, String> result = parse("for=\"\\\"a\\\"\";proto=http");
            assertEquals(mapOf(FOR, "\"a\"", PROTO, "http"), result);
        }

        @Test
        @DisplayName("a quoted value containing a lone escape sequence is terminated by the second quote")
        void doubleQuoteTerminatesQuotedValue() {
            assertEquals(mapOf(FOR, "a\""), parse("for=\"a\\\"\""));
        }
    }

    @Nested
    @DisplayName("Ignored or partially usable input")
    class IgnoredInput {

        @Test
        @DisplayName("unknown parameter names are ignored")
        void unknownNameIsIgnored() {
            assertTrue(parse("foo=bar").isEmpty());
        }

        @Test
        @DisplayName("known parameters are still collected next to unknown ones")
        void knownParametersAreCollectedNextToUnknownOnes() {
            assertEquals(mapOf(FOR, "1.2.3.4"), parse("foo=bar;for=1.2.3.4;baz=qux"));
        }

        @Test
        @DisplayName("a name with embedded whitespace is treated as an unknown name")
        void nameWithTrailingWhitespaceIsUnknown() {
            assertTrue(parse("for =1.2.3.4").isEmpty());
        }

        @Test
        @DisplayName("the first value wins when a parameter is repeated")
        void firstValueWins() {
            assertEquals(mapOf(FOR, "1.2.3.4"), parse("for=1.2.3.4;for=5.6.7.8"));
        }

        @Test
        @DisplayName("a pre-populated entry is not overwritten")
        void existingEntryIsNotOverwritten() {
            final Map<ForwardedHandler.Token, String> response = mapOf(FOR, "9.9.9.9");
            ForwardedHandler.parseHeader("for=1.2.3.4;proto=https", response);
            assertEquals(mapOf(FOR, "9.9.9.9", PROTO, "https"), response);
        }

        @Test
        @DisplayName("repeated invocations accumulate values and keep the first one for a token")
        void repeatedInvocationsAccumulate() {
            final Map<ForwardedHandler.Token, String> response = new HashMap<>();
            ForwardedHandler.parseHeader("for=1.2.3.4", response);
            ForwardedHandler.parseHeader("for=5.6.7.8;host=example.com", response);
            assertEquals(mapOf(FOR, "1.2.3.4", HOST, "example.com"), response);
        }

        @Test
        @DisplayName("parsing is skipped completely when every token is already known")
        void fullResponseShortCircuits() {
            final Map<ForwardedHandler.Token, String> response =
                    mapOf(BY, "b", FOR, "f", HOST, "h", PROTO, "p");
            ForwardedHandler.parseHeader("for=\"unterminated", response);
            assertEquals(mapOf(BY, "b", FOR, "f", HOST, "h", PROTO, "p"), response);
        }

        @Test
        @DisplayName("a map that is already full keeps its identity and content")
        void fullResponseIsNotModified() {
            final Map<ForwardedHandler.Token, String> response =
                    mapOf(BY, "b", FOR, "f", HOST, "h", PROTO, "p");
            ForwardedHandler.parseHeader("host=other;proto=https", response);
            assertSame(response, response);
            assertEquals(4, response.size());
            assertEquals("h", response.get(HOST));
        }
    }

    @Nested
    @DisplayName("Malformed headers")
    class MalformedHeaders {

        @Test
        @DisplayName("an unterminated quoted value is rejected")
        void unterminatedQuotedValue() {
            assertThrows(IllegalArgumentException.class, () -> parse("for=\"1.2.3.4"));
        }

        @Test
        @DisplayName("an unterminated quoted value of an unknown parameter is rejected")
        void unterminatedQuotedValueOfUnknownParameter() {
            assertThrows(IllegalArgumentException.class, () -> parse("unknown=\"1.2.3.4"));
        }

        @Test
        @DisplayName("a name without an equals sign is rejected")
        void nameWithoutEqualsSign() {
            assertThrows(IllegalArgumentException.class, () -> parse("for"));
            assertThrows(IllegalArgumentException.class, () -> parse("for;proto=http"));
        }

        @Test
        @DisplayName("a name without a value is rejected")
        void nameWithoutValue() {
            assertThrows(IllegalArgumentException.class, () -> parse("for="));
            assertThrows(IllegalArgumentException.class, () -> parse("for=   "));
            assertThrows(IllegalArgumentException.class, () -> parse("for=1.2.3.4;proto="));
        }

        @Test
        @DisplayName("a header starting with a comma is rejected")
        void leadingCommaIsRejected() {
            assertThrows(IllegalArgumentException.class, () -> parse(",for=1.2.3.4"));
        }

        @Test
        @DisplayName("a null header is rejected")
        void nullHeaderIsRejected() {
            final Map<ForwardedHandler.Token, String> response = new HashMap<>();
            assertThrows(NullPointerException.class, () -> ForwardedHandler.parseHeader(null, response));
        }
    }
}
