import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ProxyPeerAddressHandlerHandleRequestTests {

    @Test
    void leavesExchangeUnchangedWhenNoForwardedHeadersArePresent() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange(null);
        InetSocketAddress originalSource = InetSocketAddress.createUnresolved("original-client", 1234);
        InetSocketAddress originalDestination = InetSocketAddress.createUnresolved("original-server", 4321);
        exchange.setSourceAddress(originalSource);
        exchange.setDestinationAddress(originalDestination);
        exchange.setRequestScheme("https");
        exchange.getRequestHeaders().put(Headers.HOST, "original.example:9443");

        RecordingNextHandler next = new RecordingNextHandler();
        new ProxyPeerAddressHandler(next, true).handleRequest(exchange);

        assertEquals(1, next.invocationCount);
        assertSame(exchange, next.receivedExchange);
        assertSame(originalSource, exchange.getSourceAddress());
        assertSame(originalDestination, exchange.getDestinationAddress());
        assertEquals("https", exchange.getRequestScheme());
        assertEquals("original.example:9443", exchange.getRequestHeaders().getFirst(Headers.HOST));
    }

    @Test
    void usesTheFirstIpv4ForwardedForAddressAndUsesPortZero() throws Exception {
