        RecordingNextHandler next = new RecordingNextHandler();
        new ProxyPeerAddressHandler(next, false).handleRequest(exchange);

        InetSocketAddress source = exchange.getSourceAddress();
        assertFalse(source.isUnresolved());
        assertEquals(InetAddress.getByName("203.0.113.7"), source.getAddress());
        assertEquals(0, source.getPort());
        assertEquals(1, next.invocationCount);
        assertSame(exchange, next.receivedExchange);
    }

    @Test
    void recognizesAnIpv6ForwardedForAddress() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.getRequestHeaders().put(Headers.X_FORWARDED_FOR, "2001:db8::42, 203.0.113.7");

        RecordingNextHandler next = new RecordingNextHandler();
        new ProxyPeerAddressHandler(next, false).handleRequest(exchange);

        InetSocketAddress source = exchange.getSourceAddress();
        assertFalse(source.isUnresolved());
        assertEquals(InetAddress.getByName("2001:db8::42"), source.getAddress());
        assertEquals(0, source.getPort());
        assertEquals(1, next.invocationCount);
    }

