    }

    @Test
    void ignoresForwardedPortWhenThereIsNoForwardedHost() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange(null);
        InetSocketAddress originalDestination = InetSocketAddress.createUnresolved("original-server", 4321);
        exchange.setDestinationAddress(originalDestination);
        exchange.getRequestHeaders().put(Headers.X_FORWARDED_PORT, "8443");

        RecordingNextHandler next = new RecordingNextHandler();
        new ProxyPeerAddressHandler(next, true).handleRequest(exchange);

        assertNull(exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertSame(originalDestination, exchange.getDestinationAddress());
        assertEquals(1, next.invocationCount);
    }

    @Test
    void doesNotChangeTheDestinationAddressWhenConfiguredToLeaveItAlone() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange(null);
        InetSocketAddress originalDestination = InetSocketAddress.createUnresolved("original-server", 4321);
        exchange.setDestinationAddress(originalDestination);
        exchange.getRequestHeaders().put(Headers.X_FORWARDED_HOST, "backend.example");
        exchange.getRequestHeaders().put(Headers.X_FORWARDED_PORT, "8443");

        RecordingNextHandler next = new RecordingNextHandler();
        new ProxyPeerAddressHandler(next, false).handleRequest(exchange);

        assertEquals("backend.example:8443", exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertSame(originalDestination, exchange.getDestinationAddress());
        assertEquals(1, next.invocationCount);
    }

    private static final class RecordingNextHandler implements HttpHandler {

        private int invocationCount;
        private HttpServerExchange receivedExchange;

        @Override
        public void handleRequest(HttpServerExchange exchange) {
            invocationCount++;
            receivedExchange = exchange;
        }
    }
