            tokens.poll();
            next = tokens.poll();
            if (next == null) {
                throw error(string, string.length(), "Unexpected end of input");
            }
            if (next.getToken().equals("{")) {
                return handleSingleArrayValue(string, token, tokens, endChar);
            }
