package io.undertow.server.handlers.builder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Deque;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

import io.undertow.server.handlers.builder.PredicatedHandlersParser.AndNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.ArrayNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.BlockNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.ExpressionNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.Node;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.NotNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.OrNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.PredicateOperatorNode;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.Token;
import io.undertow.server.handlers.builder.PredicatedHandlersParser.ValueNode;

class PredicatedHandlersParserParseTests {

    @Test
    void parsesSingleBareExpression() {
        Node node = parse("handler");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        assertEquals("handler", expression.getToken().getToken());
        assertTrue(expression.getValues().isEmpty());
    }

    @Test
    void parsesExpressionWithSingleUnnamedValue() {
        Node node = parse("rewrite('/new-path')");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        assertEquals("rewrite", expression.getToken().getToken());
        assertEquals(1, expression.getValues().size());

        ValueNode value = assertInstanceOf(ValueNode.class, expression.getValues().get(null));
        assertEquals("/new-path", value.getValue().getToken());
    }

    @Test
    void parsesExpressionWithNamedValues() {
        Node node = parse("equals(header=Host, value=example.com)");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        assertEquals("equals", expression.getToken().getToken());
        assertEquals(2, expression.getValues().size());

        ValueNode header = assertInstanceOf(ValueNode.class, expression.getValues().get("header"));
        ValueNode value = assertInstanceOf(ValueNode.class, expression.getValues().get("value"));
        assertEquals("Host", header.getValue().getToken());
        assertEquals("example.com", value.getValue().getToken());
    }

    @Test
    void parsesBracedArrayParameter() {
        Node node = parse("contains(value={one, two})");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        ArrayNode array = assertInstanceOf(ArrayNode.class, expression.getValues().get("value"));
        assertEquals(List.of("one", "two"), tokenTexts(array.getValues()));
    }

    @Test
    void parsesSingleBracedArrayValue() {
        Node node = parse("handler({one, two})");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        ArrayNode array = assertInstanceOf(ArrayNode.class, expression.getValues().get(null));
        assertEquals(List.of("one", "two"), tokenTexts(array.getValues()));
    }

    @Test
    void parsesVarArgsAsUnnamedArrayValue() {
        Node node = parse("handler(one, two)");

        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        ArrayNode array = assertInstanceOf(ArrayNode.class, expression.getValues().get(null));
        assertEquals(List.of("one", "two"), tokenTexts(array.getValues()));
    }

    @Test
    void appliesAndBeforeOr() {
        Node node = parse("a and b or c");

        OrNode or = assertInstanceOf(OrNode.class, node);
        assertEquals("or", or.getToken().getToken());
        AndNode and = assertInstanceOf(AndNode.class, or.getLeft());
        assertExpression(and.getLeft(), "a");
        assertExpression(and.getRight(), "b");
        assertExpression(or.getRight(), "c");
    }

    @Test
    void appliesParenthesesBeforeOperators() {
        Node node = parse("(a() or b()) and c()");

        AndNode and = assertInstanceOf(AndNode.class, node);
        OrNode or = assertInstanceOf(OrNode.class, and.getLeft());
        assertExpression(or.getLeft(), "a");
        assertExpression(or.getRight(), "b");
        assertExpression(and.getRight(), "c");
    }

    @Test
    void appliesNotToParenthesizedExpression() {
        Node node = parse("not (a() and b())");

        NotNode not = assertInstanceOf(NotNode.class, node);
        assertEquals("not", not.getToken().getToken());
        AndNode and = assertInstanceOf(AndNode.class, not.getNode());
        assertExpression(and.getLeft(), "a");
        assertExpression(and.getRight(), "b");
    }

    @Test
    void parsesPredicateArrowHandler() {
        Node node = parse("a -> handler");

        PredicateOperatorNode predicateOperator = assertInstanceOf(PredicateOperatorNode.class, node);
        assertEquals("->", predicateOperator.getToken().getToken());
        assertExpression(predicateOperator.getLeft(), "a");
        assertExpression(predicateOperator.getRight(), "handler");
        assertNull(predicateOperator.getElseBranch());
    }

    @Test
    void parsesElseBranchOfPredicateArrow() {
        Node node = parse("a -> handler else fallback");

        PredicateOperatorNode predicateOperator = assertInstanceOf(PredicateOperatorNode.class, node);
        assertExpression(predicateOperator.getLeft(), "a");
        assertExpression(predicateOperator.getRight(), "handler");
        assertExpression(predicateOperator.getElseBranch(), "fallback");
    }

    @Test
    void semicolonBeforeElseKeepsNestedArrowOnSameLine() {
        Node node = parse("a -> h; else b -> h2");

        PredicateOperatorNode outer = assertInstanceOf(PredicateOperatorNode.class, node);
        assertExpression(outer.getRight(), "h2");
        assertNull(outer.getElseBranch());

        PredicateOperatorNode inner = assertInstanceOf(PredicateOperatorNode.class, outer.getLeft());
        assertExpression(inner.getLeft(), "a");
        assertExpression(inner.getRight(), "h");
        assertExpression(inner.getElseBranch(), "b");
    }

    @Test
    void combinesMultipleStatementsIntoBlock() {
        Node node = parse("first; second; third");

        BlockNode block = assertInstanceOf(BlockNode.class, node);
        assertEquals("", block.getToken().getToken());
        assertEquals(0, block.getToken().getPosition());
        assertEquals(3, block.getBlock().size());
        assertExpression(block.getBlock().get(0), "first");
        assertExpression(block.getBlock().get(1), "second");
        assertExpression(block.getBlock().get(2), "third");
    }

    @Test
    void newlineBeforeOperatorContinuesCurrentExpression() {
        Node node = parse("a\nand b");

        AndNode and = assertInstanceOf(AndNode.class, node);
        assertExpression(and.getLeft(), "a");
        assertExpression(and.getRight(), "b");
    }

    @Test
    void parsesBraceDelimitedHandlerBlock() {
        Node node = parse("a -> {h1; h2}");

        PredicateOperatorNode predicateOperator = assertInstanceOf(PredicateOperatorNode.class, node);
        assertExpression(predicateOperator.getLeft(), "a");
        BlockNode handlerBlock = assertInstanceOf(BlockNode.class, predicateOperator.getRight());
        assertEquals(2, handlerBlock.getBlock().size());
        assertExpression(handlerBlock.getBlock().get(0), "h1");
        assertExpression(handlerBlock.getBlock().get(1), "h2");
    }

    @Test
    void returnsEmptyBlockForEmptyInput() {
        Node node = parse("");

        BlockNode block = assertInstanceOf(BlockNode.class, node);
        assertEquals("", block.getToken().getToken());
        assertEquals(0, block.getToken().getPosition());
        assertTrue(block.getBlock().isEmpty());
    }

    @Test
    void nonTopLevelParseStopsAtClosingBraceAndLeavesFollowingTokens() {
        String source = "a} remaining";
        Deque<Token> tokens = PredicatedHandlersParser.tokenize(source);

        Node node = PredicatedHandlersParser.parse(source, tokens, false);

        assertExpression(node, "a");
        assertNotNull(tokens.peek());
        assertEquals("remaining", tokens.peek().getToken());
    }

    @Test
    void nonTopLevelParseReturnsBlockForMultipleStatementsBeforeBrace() {
        String source = "a; b} remaining";
        Deque<Token> tokens = PredicatedHandlersParser.tokenize(source);

        Node node = PredicatedHandlersParser.parse(source, tokens, false);

        BlockNode block = assertInstanceOf(BlockNode.class, node);
        assertEquals(2, block.getBlock().size());
        assertExpression(block.getBlock().get(0), "a");
        assertExpression(block.getBlock().get(1), "b");
        assertEquals("remaining", tokens.peek().getToken());
    }

    @Test
    void rejectsUnexpectedClosingBraceAtTopLevel() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("a}"));

        assertTrue(exception.getMessage().contains("Unexpected token"));
    }

    @Test
    void rejectsUnexpectedCharacterAfterExpression() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("a )"));

        assertTrue(exception.getMessage().contains("Unexpected character"));
    }

    @Test
    void rejectsMissingClosingParenthesis() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("handler("));

        assertTrue(exception.getMessage().contains("Unexpected end of input"));
    }

    @Test
    void rejectsMalformedNamedParameter() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("handler(name value)"));

        assertTrue(exception.getMessage().contains("Unexpected token"));
    }

    private static Node parse(String source) {
        return PredicatedHandlersParser.parse(source, PredicatedHandlersParser.tokenize(source));
    }

    private static void assertExpression(Node node, String expectedName) {
        ExpressionNode expression = assertInstanceOf(ExpressionNode.class, node);
        assertEquals(expectedName, expression.getToken().getToken());
        assertTrue(expression.getValues().isEmpty());
    }

    private static List<String> tokenTexts(List<Token> tokens) {
        return tokens.stream().map(Token::getToken).toList();
    }
}

