        HttpServerExchange seedExchange = new HttpServerExchange(connection);
        seedExchange.setRequestPath(PATH);
        if (etag != null) {
            seedExchange.getResponseHeaders().put(Headers.ETAG, etag);
        }
        if (contentType != null) {
            seedExchange.getResponseHeaders().put(Headers.CONTENT_TYPE, contentType);
        }
        if (contentEncoding != null) {
            seedExchange.getResponseHeaders().put(Headers.CONTENT_ENCODING, contentEncoding);
        }
        if (contentLocation != null) {
            seedExchange.getResponseHeaders().put(Headers.CONTENT_LOCATION, contentLocation);
        }
        if (language != null) {
            seedExchange.getResponseHeaders().put(Headers.CONTENT_LANGUAGE, language);
        }
        if (lastModified != null) {
            seedExchange.getResponseHeaders().put(Headers.LAST_MODIFIED, DateUtils.toDateString(lastModified));
        }
        return new CachedHttpRequest(seedExchange);
    }

    private DirectBufferCache.CacheEntry installEntry(CachedHttpRequest key, int size) {
        DirectBufferCache.CacheEntry entry = cache.add(key, size);
        entry.enable();
        cache.setEntry(entry);
