class MCMPHandlerProcessAppCommandTests {

    private static final String CONTENT_TYPE = "text/plain; charset=ISO-8859-1";
    private static final HttpString VERSION_HEADER = new HttpString("Version");
    private static final HttpString TYPE_HEADER = new HttpString("Type");
    private static final HttpString MESSAGE_HEADER = new HttpString("Mess");
    private static final int FLAG_RESPONSE_TERMINATED = 1 << 11;
    private static final int FLAG_REQUEST_TERMINATED = 1 << 12;

    private ModClusterContainer container;
    private ModCluster modCluster;

    @Test
    void missingContextProducesMandatoryFieldError() throws Exception {
        MCMPHandler handler = newHandler();
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData(null, "node1", "host1"), MCMPHandler.MCMPAction.ENABLE);

        assertError(result, "SYNTAX", "SYNTAX: Mandatory field(s) missing in message");
        verify(container, modCluster);
    }

    @Test
    void missingJvmRouteProducesMandatoryFieldError() throws Exception {
        MCMPHandler handler = newHandler();
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", null, "host1"), MCMPHandler.MCMPAction.ENABLE);

        assertError(result, "SYNTAX", "SYNTAX: Mandatory field(s) missing in message");
        verify(container, modCluster);
    }

    @Test
    void missingAliasProducesMandatoryFieldError() throws Exception {
        MCMPHandler handler = newHandler();
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", null), MCMPHandler.MCMPAction.ENABLE);

        assertError(result, "SYNTAX", "SYNTAX: Mandatory field(s) missing in message");
        verify(container, modCluster);
    }

    @Test
    void aliasContainingOnlyCommasProducesEmptyAliasListError() throws Exception {
        MCMPHandler handler = newHandler();
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", ",,"), MCMPHandler.MCMPAction.ENABLE);

        assertError(result, "SYNTAX", "SYNTAX: Context without Alias");
        verify(container, modCluster);
    }

    @Test
    void enableContextSplitsAliasesAndReturnsOk() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.enableContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1", "host2")))).andReturn(true);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1,host2"), MCMPHandler.MCMPAction.ENABLE);

        assertOk(result);
        verify(container, modCluster);
    }

    @Test
    void enableContextFailureProducesMemoryError() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.enableContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1")))).andReturn(false);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1"), MCMPHandler.MCMPAction.ENABLE);

        assertError(result, "MEM", "MEM: Can't update or insert context");
        verify(container, modCluster);
    }

    @Test
    void disableContextReturnsOkWhenContextWasUpdated() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.disableContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1", "host2")))).andReturn(true);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1,host2"), MCMPHandler.MCMPAction.DISABLE);

        assertOk(result);
        verify(container, modCluster);
    }

    @Test
    void disableContextFailureProducesMemoryError() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.disableContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1")))).andReturn(false);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1"), MCMPHandler.MCMPAction.DISABLE);

        assertError(result, "MEM", "MEM: Can't update or insert context");
        verify(container, modCluster);
    }

    @Test
    void stopContextReturnsActiveRequestCountInResponse() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.stopContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1", "host2")))).andReturn(7);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1,host2"), MCMPHandler.MCMPAction.STOP);

        assertEquals(StatusCodes.OK, result.exchange.getStatusCode());
        assertEquals(CONTENT_TYPE, result.exchange.getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("Type=STOP-APP-RSP,JvmRoute=node1Alias=host1,host2Context=/appRequests=7", result.sender.getBody());
        assertNull(result.exchange.getResponseHeaders().getFirst(VERSION_HEADER));
        assertNull(result.exchange.getResponseHeaders().getFirst(TYPE_HEADER));
        assertNull(result.exchange.getResponseHeaders().getFirst(MESSAGE_HEADER));
        verify(container, modCluster);
    }

    @Test
    void removeContextReturnsOkWhenContextWasUpdated() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.removeContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1")))).andReturn(true);
        replay(container);
        ExchangeResult result = newExchange();

        handler.processAppCommand(result.exchange, requestData("/app", "node1", "host1"), MCMPHandler.MCMPAction.REMOVE);

        assertOk(result);
        verify(container, modCluster);
    }

    @Test
    void removeContextFailureProducesMemoryError() throws Exception {
        MCMPHandler handler = newHandler();
        expect(container.removeContext(eq("/app"), eq("node1"), eq(Arrays.asList("host1")))).andReturn(false);
        replay(container);
        ExchangeResult result = newExchange();

