class ModClusterContainerFindFailoverNodeTests {

    @Test
    void deterministicFailoverSelectsOnlyAnAvailableRegularNode() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode regularNode = node(cluster, container, "node-a", "domain-a", true, false, false, 10);
        TestNode failedNode = node(cluster, container, "node-b", "domain-a", true, true, false, 0);
        TestNode standbyNode = node(cluster, container, "node-c", "domain-a", true, false, true, 0);
        addNode(container, regularNode);
        addNode(container, failedNode);
        addNode(container, standbyNode);

        Context regularContext = enabledContext(regularNode);
        VirtualHost.HostEntry entry = entry(regularContext, enabledContext(failedNode), enabledContext(standbyNode));

        Context result = container.findFailoverNode(entry, null, "abc.ignored", null, true);

        assertSame(regularContext, result);
    }

    @Test
    void deterministicFailoverUsesSessionHashAndSortedRouteNames() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode alphaNode = node(cluster, container, "alpha", "domain-a", true, false, false, 0);
        TestNode middleNode = node(cluster, container, "middle", "domain-a", true, false, false, 0);
        TestNode zetaNode = node(cluster, container, "zeta", "domain-a", true, false, false, 0);
        addNode(container, alphaNode);
        addNode(container, middleNode);
        addNode(container, zetaNode);

        Context alphaContext = enabledContext(alphaNode);
        Context middleContext = enabledContext(middleNode);
        Context zetaContext = enabledContext(zetaNode);
        VirtualHost.HostEntry entry = entry(zetaContext, alphaContext, middleContext);

        assertSame(alphaContext, container.findFailoverNode(entry, null, "abc.suffix-is-ignored", null, true));
        assertSame(middleContext, container.findFailoverNode(entry, null, "session-3.suffix-is-ignored", null, true));
        assertSame(zetaContext, container.findFailoverNode(entry, null, "session-1.suffix-is-ignored", null, true));
    }

    @Test
    void deterministicFailoverSkipsRoutesWithoutContainerNodes() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode registeredNode = node(cluster, container, "registered", "domain-a", true, false, false, 0);
        TestNode unregisteredNode = node(cluster, container, "unregistered", "domain-a", true, false, false, 0);
        addNode(container, registeredNode);

        Context registeredContext = enabledContext(registeredNode);
        Context unregisteredContext = enabledContext(unregisteredNode);
        VirtualHost.HostEntry entry = entry(unregisteredContext, registeredContext);

        assertSame(registeredContext, container.findFailoverNode(entry, null, "abc.123", null, true));
    }

    @Test
    void deterministicFailoverFallsBackToHotStandbyNodes() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode failedRegularNode = node(cluster, container, "node-z", "domain-a", true, true, false, 0);
        TestNode failedStandbyNode = node(cluster, container, "node-a", "domain-a", true, true, true, 0);
        TestNode firstStandbyNode = node(cluster, container, "node-b", "domain-a", true, false, true, 0);
        TestNode secondStandbyNode = node(cluster, container, "node-c", "domain-a", true, false, true, 0);
        addNode(container, failedRegularNode);
        addNode(container, failedStandbyNode);
        addNode(container, firstStandbyNode);
        addNode(container, secondStandbyNode);

        Context firstStandbyContext = enabledContext(firstStandbyNode);
        VirtualHost.HostEntry entry = entry(
                enabledContext(failedRegularNode),
                enabledContext(failedStandbyNode),
                firstStandbyContext,
                enabledContext(secondStandbyNode));

        assertSame(firstStandbyContext, container.findFailoverNode(entry, null, "abc.123", null, true));
    }

    @Test
    void deterministicFailoverReturnsNullWhenThereAreNoCandidates() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode failedNode = node(cluster, container, "node-a", "domain-a", true, true, false, 0);
        TestNode failedStandbyNode = node(cluster, container, "node-b", "domain-a", true, true, true, 0);
        addNode(container, failedNode);
        addNode(container, failedStandbyNode);

        VirtualHost.HostEntry entry = entry(enabledContext(failedNode), enabledContext(failedStandbyNode));

        // The candidate check happens before the session id is parsed.
        assertNull(container.findFailoverNode(entry, null, "not-a-session-id", null, true));
    }

    @Test
    void deterministicFailoverRejectsSessionWithoutRouteDelimiter() throws Exception {
        ModCluster cluster = cluster(true);
        ModClusterContainer container = cluster.getContainer();

        TestNode node = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        addNode(container, node);
        VirtualHost.HostEntry entry = entry(enabledContext(node));

        assertThrows(StringIndexOutOfBoundsException.class,
                () -> container.findFailoverNode(entry, null, "no-route-delimiter", null, true));
    }

    @Test
    void explicitFailoverDomainSelectsMatchingContext() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode matchingNode = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        TestNode otherNode = node(cluster, container, "node-b", "domain-b", true, false, false, 0);
        addNode(container, matchingNode);
        addNode(container, otherNode);

        Context matchingContext = enabledContext(matchingNode);
        VirtualHost.HostEntry entry = entry(enabledContext(otherNode), matchingContext);

        assertSame(matchingContext,
                container.findFailoverNode(entry, "domain-a", "abc.123", "node-b", true));
    }

    @Test
    void forcedStickySessionPreventsDomainFallback() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode otherDomainNode = node(cluster, container, "node-b", "domain-b", true, false, false, 0);
        addNode(container, otherDomainNode);
        Context otherDomainContext = enabledContext(otherDomainNode);
        VirtualHost.HostEntry entry = entry(otherDomainContext);

        assertNull(container.findFailoverNode(entry, "domain-a", "abc.123", "node-b", true));
        assertSame(otherDomainContext,
                container.findFailoverNode(entry, "domain-a", "abc.123", "node-b", false));
    }

    @Test
    void unknownDomainWithForcedStickySessionReturnsNull() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode availableNode = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        addNode(container, availableNode);
        VirtualHost.HostEntry entry = entry(enabledContext(availableNode));

        assertNull(container.findFailoverNode(entry, null, "abc.123", "unknown-route", true));
    }

    @Test
    void unknownDomainWithoutForcedStickySessionElectsAnyAvailableContext() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode availableNode = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        addNode(container, availableNode);
        Context availableContext = enabledContext(availableNode);
        VirtualHost.HostEntry entry = entry(availableContext);

        assertSame(availableContext,
                container.findFailoverNode(entry, null, "abc.123", "unknown-route", false));
    }

    @Test
    void originalNodeConfigurationSuppliesMissingFailoverDomain() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode originalNode = node(cluster, container, "original-route", "domain-a", true, false, false, 0);
        TestNode targetNode = node(cluster, container, "target-route", "domain-a", true, false, false, 0);
        TestNode otherNode = node(cluster, container, "other-route", "domain-b", true, false, false, 0);
        addNode(container, originalNode);
        addNode(container, targetNode);
        addNode(container, otherNode);

        Context targetContext = enabledContext(targetNode);
        VirtualHost.HostEntry entry = entry(enabledContext(otherNode), targetContext);

        assertSame(targetContext,
                container.findFailoverNode(entry, null, "abc.123", "original-route", true));
    }

    @Test
    void cachedFailoverDomainIsUsedWhenOriginalNodeIsGone() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode targetNode = node(cluster, container, "target-route", "domain-a", true, false, false, 0);
        addNode(container, targetNode);
        Context targetContext = enabledContext(targetNode);
        VirtualHost.HostEntry entry = entry(targetContext);
        cacheFailoverDomain(container, "removed-route", "domain-a");

        assertSame(targetContext,
                container.findFailoverNode(entry, null, "abc.123", "removed-route", true));
    }

    @Test
    void cachedFailoverDomainIsUsedWhenOriginalNodeHasNoDomain() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode originalNode = node(cluster, container, "original-route", null, true, false, false, 0);
        TestNode targetNode = node(cluster, container, "target-route", "domain-a", true, false, false, 0);
        addNode(container, originalNode);
        addNode(container, targetNode);
        Context targetContext = enabledContext(targetNode);
        VirtualHost.HostEntry entry = entry(targetContext);
        cacheFailoverDomain(container, "original-route", "domain-a");

        assertSame(targetContext,
                container.findFailoverNode(entry, null, "abc.123", "original-route", true));
    }

    @Test
    void regularNodeIsPreferredOverHotStandbyNodeInDomainElection() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode regularNode = node(cluster, container, "regular", "domain-a", true, false, false, 100);
        TestNode standbyNode = node(cluster, container, "standby", "domain-a", true, false, true, 0);
        addNode(container, regularNode);
        addNode(container, standbyNode);

        Context regularContext = enabledContext(regularNode);
        Context standbyContext = enabledContext(standbyNode);
        VirtualHost.HostEntry standbyFirstEntry = entry(standbyContext, regularContext);

        assertSame(regularContext,
                container.findFailoverNode(standbyFirstEntry, "domain-a", "abc.123", "missing", true));
    }

    @Test
    void hotStandbyNodeIsElectedWhenRegularNodesAreUnavailable() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode unavailableRegularNode = node(cluster, container, "regular", "domain-a", false, false, false, 0);
        TestNode standbyNode = node(cluster, container, "standby", "domain-a", true, false, true, 0);
        addNode(container, unavailableRegularNode);
        addNode(container, standbyNode);

        Context standbyContext = enabledContext(standbyNode);
        VirtualHost.HostEntry entry = entry(enabledContext(unavailableRegularNode), standbyContext);

        assertSame(standbyContext,
                container.findFailoverNode(entry, "domain-a", "abc.123", "missing", true));
    }

    @Test
    void disabledContextIsUsableForExistingSessionFailover() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode node = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        addNode(container, node);
        Context disabledContext = enabledContext(node);
        disabledContext.disable();
        VirtualHost.HostEntry entry = entry(disabledContext);

        assertSame(disabledContext,
                container.findFailoverNode(entry, "domain-a", "abc.123", "missing", true));
    }

    @Test
    void stoppedContextIsNotUsableForExistingSessionFailover() throws Exception {
        ModCluster cluster = cluster(false);
        ModClusterContainer container = cluster.getContainer();

        TestNode node = node(cluster, container, "node-a", "domain-a", true, false, false, 0);
        addNode(container, node);
        Context stoppedContext = enabledContext(node);
        stoppedContext.stop();
        VirtualHost.HostEntry entry = entry(stoppedContext);

        assertNull(container.findFailoverNode(entry, "domain-a", "abc.123", "missing", true));
    }

    private static ModCluster cluster(boolean deterministicFailover) {
        return ModCluster.builder(null, null, null)
                .setDeterministicFailover(deterministicFailover)
                .build();
    }

    private static TestNode node(ModCluster cluster, ModClusterContainer container, String route, String domain,
                                 boolean available, boolean inError, boolean hotStandby, int loadStatus) throws Exception {
        NodeConfig config = NodeConfig.builder(cluster)
                .setJvmRoute(route)
                .setBalancer("test-balancer")
                .setHostname("127.0.0.1")
                .setPort(8080)
                .setDomain(domain)
                .build();
        return new TestNode(container, config, available, inError, hotStandby, loadStatus);
    }

    private static Context enabledContext(TestNode node) {
        Context context = new Context("/", null, node);
        context.enable();
        return context;
    }

    private static VirtualHost.HostEntry entry(Context... contexts) {
        VirtualHost virtualHost = new VirtualHost();
        for (Context context : contexts) {
            virtualHost.registerContext("/", context.getJVMRoute(), context);
        }
        return virtualHost.match("/").getValue();
    }

    @SuppressWarnings("unchecked")
    private static void addNode(ModClusterContainer container, Node node) throws Exception {
        Field nodesField = ModClusterContainer.class.getDeclaredField("nodes");
        nodesField.setAccessible(true);
        ((Map<String, Node>) nodesField.get(container)).put(node.getJvmRoute(), node);
    }

    @SuppressWarnings("unchecked")
    private static void cacheFailoverDomain(ModClusterContainer container, String jvmRoute, String domain) throws Exception {
        Field failoverDomainsField = ModClusterContainer.class.getDeclaredField("failoverDomains");
        failoverDomainsField.setAccessible(true);
        ((LRUCache<String, String>) failoverDomainsField.get(container)).add(jvmRoute, domain);
    }

    private static final class TestNode extends Node {

        private final boolean available;
        private final boolean inError;
        private final boolean hotStandby;
        private final int loadStatus;

        private TestNode(ModClusterContainer container, NodeConfig config, boolean available,
                         boolean inError, boolean hotStandby, int loadStatus) {
            super(config, Balancer.builder().build(), null, null, container);
            this.available = available;
            this.inError = inError;
            this.hotStandby = hotStandby;
            this.loadStatus = loadStatus;
        }

        @Override
        protected boolean checkAvailable(boolean existingSession) {
            return available;
        }

        @Override
        protected boolean isInErrorState() {
            return inError;
        }

        @Override
        boolean isHotStandby() {
            return hotStandby;
        }

        @Override
        public int getLoadStatus() {
            return loadStatus;
        }
    }
}
