    @Test
    public void servesFullCachedContentAndKeepsPooledBuffersUnchanged() throws Exception {
        DirectBufferCache dataCache = newDataCache();
        StubRangeAwareResource underlying = new StubRangeAwareResource(CONTENT.length());
        CachingResourceManager manager = manager(dataCache, underlying, CONTENT.length());
        CachedResource resource = assertNotNullAndGet(manager.getResource(PATH));
        DirectBufferCache.CacheEntry entry = cachedEntry(dataCache, manager, CONTENT);
        LimitedBufferSlicePool.PooledByteBuffer[] pooled = entry.buffers();
        int[] positions = new int[pooled.length];
        int[] limits = new int[pooled.length];
        for (int i = 0; i < pooled.length; i++) {
            positions[i] = pooled[i].getBuffer().position();
            limits[i] = pooled[i].getBuffer().limit();
        }

        CapturingSender sender = new CapturingSender();
        resource.serveRange(sender, null, 0, CONTENT.length() - 1, new RecordingCallback());

        assertEquals(1, sender.arraySendCount);
        assertEquals(CONTENT, sender.body());
        for (int i = 0; i < pooled.length; i++) {
            assertEquals(positions[i], pooled[i].getBuffer().position());
            assertEquals(limits[i], pooled[i].getBuffer().limit());
        }
    }

    @Test
    public void completionCallbackIsForwardedAndReleasesCacheReference() throws Exception {
        DirectBufferCache dataCache = newDataCache();
        StubRangeAwareResource underlying = new StubRangeAwareResource(CONTENT.length());
        CachingResourceManager manager = manager(dataCache, underlying);
        CachedResource resource = assertNotNullAndGet(manager.getResource(PATH));
        DirectBufferCache.CacheEntry entry = cachedEntry(dataCache, manager, CONTENT);

        CapturingSender sender = new CapturingSender();
        RecordingCallback callback = new RecordingCallback();
        HttpServerExchange exchange = new HttpServerExchange(null);
        resource.serveRange(sender, exchange, 0, 0, callback);

        assertSame(callback, sender.callback);
        sender.callback.onComplete(exchange, sender);

        assertEquals(1, callback.completeCount);
        assertSame(exchange, callback.lastExchange);
        assertSame(sender, callback.lastSender);
        // serveRange added one reference and the callback released it; the cache's original reference remains.
        assertFalse(entry.buffers().length == 0);
        assertTrue(entry.dereference());
        assertEquals(0, entry.buffers().length);
    }

    @Test
    public void exceptionCallbackIsForwardedAndReleasesCacheReference() throws Exception {
        DirectBufferCache dataCache = newDataCache();
        StubRangeAwareResource underlying = new StubRangeAwareResource(CONTENT.length());
        CachingResourceManager manager = manager(dataCache, underlying);
        CachedResource resource = assertNotNullAndGet(manager.getResource(PATH));
        DirectBufferCache.CacheEntry entry = cachedEntry(dataCache, manager, CONTENT);

        CapturingSender sender = new CapturingSender();
        RecordingCallback callback = new RecordingCallback();
        HttpServerExchange exchange = new HttpServerExchange(null);
        resource.serveRange(sender, exchange, 0, 1, callback);

        IOException failure = new IOException("send failed");
        sender.callback.onException(exchange, sender, failure);

        assertEquals(1, callback.exceptionCount);
        assertSame(exchange, callback.lastExchange);
        assertSame(sender, callback.lastSender);
        assertSame(failure, callback.lastException);
        assertFalse(entry.buffers().length == 0);
        assertTrue(entry.dereference());
        assertEquals(0, entry.buffers().length);
    }

    private static DirectBufferCache newDataCache() {
        return new DirectBufferCache(SLICE_SIZE, 2, 1024);
    }

    private static CachingResourceManager manager(DirectBufferCache dataCache, StubRangeAwareResource underlying) {
        return manager(dataCache, underlying, MAX_FILE_SIZE);
    }

    private static CachingResourceManager manager(DirectBufferCache dataCache, StubRangeAwareResource underlying,
                                                  long maxFileSize) {
        return new CachingResourceManager(16, maxFileSize, dataCache,
                new StubResourceManager(underlying), CachingResourceManager.MAX_AGE_NO_EXPIRY);
    }

    private static CachedResource.CacheKey cacheKey(CachingResourceManager manager) {
        return new CachedResource.CacheKey(manager, CACHE_KEY);
    }

    private static DirectBufferCache.CacheEntry cachedEntry(DirectBufferCache dataCache,
                                                            CachingResourceManager manager,
                                                            String content) {
        DirectBufferCache.CacheEntry entry = dataCache.add(cacheKey(manager), content.length(),
                DirectBufferCache.MAX_AGE_NO_EXPIRY);
        assertTrue(entry.allocate());
        fill(entry, content);
        entry.enable();
        assertTrue(entry.enabled());
        return entry;
    }

    private static void fill(DirectBufferCache.CacheEntry entry, String content) {
        int offset = 0;
        for (LimitedBufferSlicePool.PooledByteBuffer pooled : entry.buffers()) {
            ByteBuffer buffer = pooled.getBuffer();
            int amount = Math.min(buffer.remaining(), content.length() - offset);
            buffer.put(content.substring(offset, offset + amount).getBytes(StandardCharsets.US_ASCII));
            buffer.flip();
            offset += amount;
        }
        assertEquals(content.length(), offset);
    }

    private static CachedResource assertNotNullAndGet(CachedResource resource) {
        assertNotNull(resource);
        return resource;
    }

