    private static final class CapturingSender implements Sender {
        private ByteBuffer[] buffers;
        private IoCallback callback;
        private int arraySendCount;

        @Override
        public void send(ByteBuffer[] buffers, IoCallback callback) {
            this.buffers = buffers;
            this.callback = callback;
            arraySendCount++;
        }

        private String body() {
            StringBuilder result = new StringBuilder();
            for (ByteBuffer buffer : buffers) {
                ByteBuffer copy = buffer.duplicate();
                while (copy.hasRemaining()) {
                    result.append((char) copy.get());
                }
            }
            return result.toString();
        }

        @Override
        public void send(ByteBuffer buffer, IoCallback callback) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void send(ByteBuffer buffer) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void send(ByteBuffer[] buffer) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void send(String data, IoCallback callback) {
            throw new UnsupportedOperationException();
        }

        @Override
