            throw new UnsupportedOperationException();
        }

        @Override
        public void send(String data, Charset charset) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void transferFrom(FileChannel channel, IoCallback callback) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void close(IoCallback callback) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void close() {
            throw new UnsupportedOperationException();
        }
    }

    private static final class RecordingCallback implements IoCallback {
        private int completeCount;
        private int exceptionCount;
        private HttpServerExchange lastExchange;
        private Sender lastSender;
        private IOException lastException;

        @Override
        public void onComplete(HttpServerExchange exchange, Sender sender) {
            completeCount++;
            lastExchange = exchange;
            lastSender = sender;
        }

        @Override
        public void onException(HttpServerExchange exchange, Sender sender, IOException exception) {
            exceptionCount++;
            lastExchange = exchange;
            lastSender = sender;
            lastException = exception;
        }
    }
