import io.undertow.io.IoCallback;
import io.undertow.io.Sender;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.handlers.cache.DirectBufferCache;
import io.undertow.util.ETag;
import io.undertow.util.MimeMappings;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * Tests for {@link CachingResourceManager#getResource(String)}.
 */
class CachingResourceManagerGetResourceTests {

    private static final long LAST_MODIFIED = 1_000_000L;
    private static final long NEW_LAST_MODIFIED = 2_000_000L;
    private static final int SHORT_MAX_AGE = 20;
    private static final int LONG_MAX_AGE = 60_000;

    private TestResourceManager underlying;

    @BeforeEach
    void setUp() {
        underlying = new TestResourceManager();
    }

    @Test
    void nullPathReturnsNullWithoutConsultingUnderlying() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);
        underlying.failure = new IOException("underlying must not be consulted for a null path");

        assertNull(manager.getResource(null));

        assertEquals(0, underlying.getResourceCalls);
        assertTrue(underlying.requestedPaths.isEmpty());
    }

    @ParameterizedTest(name = "request [{0}] looks up [{1}]")
    @MethodSource("pathMappings")
    void onlyTheFirstLeadingSlashIsRemoved(String requestedPath, String expectedLookupPath) throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);
        registerResource(expectedLookupPath);

        CachedResource resource = manager.getResource(requestedPath);

        assertNotNull(resource);
        assertEquals(List.of(expectedLookupPath), underlying.requestedPaths);
        assertEquals(expectedLookupPath, resource.getPath());
        assertEquals(1, underlying.getResourceCalls);
    }

    static Stream<Arguments> pathMappings() {
        return Stream.of(
                Arguments.of("foo.txt", "foo.txt"),
                Arguments.of("/foo.txt", "foo.txt"),
                Arguments.of("dir/file.txt", "dir/file.txt"),
                Arguments.of("/dir/file.txt", "dir/file.txt"),
                Arguments.of("/", ""),
                Arguments.of("//foo.txt", "/foo.txt"));
    }

    @Test
    void missingResourceIsNotRequestedAgainWhileNegativelyCached() throws IOException {
        CachingResourceManager manager = newManager(LONG_MAX_AGE);

        assertNull(manager.getResource("missing.txt"));
        registerResource("missing.txt");

        assertNull(manager.getResource("missing.txt"));
        assertEquals(1, underlying.getResourceCalls);
        assertEquals(List.of("missing.txt"), underlying.requestedPaths);
    }

    @Test
    void negativeCacheUsesTheNormalizedPathAsItsKey() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);

        assertNull(manager.getResource("/missing.txt"));
        assertNull(manager.getResource("missing.txt"));

        assertEquals(1, underlying.getResourceCalls);
        assertEquals(List.of("missing.txt"), underlying.requestedPaths);
    }

    @Test
    void missingResourceIsNotCachedWhenMaxAgeDisablesCaching() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_CACHING);
        registerResource("missing.txt");

        assertNull(manager.getResource("missing.txt"));
        assertNull(manager.getResource("missing.txt"));

        assertEquals(2, underlying.getResourceCalls);
        assertEquals(List.of("missing.txt", "missing.txt"), underlying.requestedPaths);
    }

    @Test
    void missingResourceIsCachedForeverWhenMaxAgeIsNoExpiry() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);

        assertNull(manager.getResource("missing.txt"));
        registerResource("missing.txt");
        assertNull(manager.getResource("missing.txt"));

        assertEquals(1, underlying.getResourceCalls);
    }

    @Test
    void cachedMissExpiresAndALaterLookupFindsTheNewResource() throws IOException {
        CachingResourceManager manager = newManager(SHORT_MAX_AGE);
        assertNull(manager.getResource("late.txt"));

        registerResource("late.txt");
        awaitCacheExpiry();

        CachedResource resource = manager.getResource("late.txt");

        assertNotNull(resource);
        assertEquals("late.txt", resource.getPath());
        assertEquals(2, underlying.getResourceCalls);
        assertEquals(List.of("late.txt", "late.txt"), underlying.requestedPaths);
    }

    @Test
    void existingResourceIsCachedAndMetadataIsDelegated() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);
        TestResource original = registerResource("foo.txt");

        CachedResource first = manager.getResource("/foo.txt");
        CachedResource second = manager.getResource("foo.txt");

        assertNotNull(first);
        assertSame(first, second);
        assertEquals(1, underlying.getResourceCalls);
        assertEquals(List.of("foo.txt"), underlying.requestedPaths);
        assertEquals(original.getPath(), first.getPath());
        assertEquals(original.getName(), first.getName());
        assertEquals(original.getLastModified(), first.getLastModified());
        assertEquals(original.getContentLength(), first.getContentLength());
        assertEquals("text/plain", first.getContentType(null));
        assertFalse(first.isDirectory());
    }

    @Test
    void existingResourceIsCachedWhilePositiveMaxAgeHasNotExpired() throws IOException {
        CachingResourceManager manager = newManager(LONG_MAX_AGE);
        registerResource("foo.txt");

        CachedResource first = manager.getResource("foo.txt");
        CachedResource second = manager.getResource("foo.txt");

        assertNotNull(first);
        assertSame(first, second);
        assertEquals(1, underlying.getResourceCalls);
    }

    @Test
    void existingResourceIsNotCachedWhenMaxAgeDisablesCaching() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_CACHING);
        registerResource("foo.txt");

        CachedResource first = manager.getResource("foo.txt");
        CachedResource second = manager.getResource("foo.txt");

        assertNotNull(first);
        assertNotNull(second);
        assertNotSame(first, second);
        assertEquals(2, underlying.getResourceCalls);
    }

    @Test
    void cachedResourceIsReloadedOncePositiveMaxAgeHasExpired() throws IOException {
        CachingResourceManager manager = newManager(SHORT_MAX_AGE);
        TestResource original = registerResource("foo.txt");
        CachedResource first = manager.getResource("foo.txt");

        original.setLastModified(new Date(NEW_LAST_MODIFIED));
        awaitCacheExpiry();

        CachedResource second = manager.getResource("foo.txt");

        assertNotNull(first);
        assertNotNull(second);
        assertNotSame(first, second);
        assertEquals(new Date(NEW_LAST_MODIFIED), second.getLastModified());
        assertEquals(2, underlying.getResourceCalls);
    }

    @Test
    void cachedResourceIsReloadedAfterExpiryEvenWhenUnderlyingIsUnchanged() throws IOException {
        CachingResourceManager manager = newManager(SHORT_MAX_AGE);
        registerResource("foo.txt");
        CachedResource first = manager.getResource("foo.txt");

        awaitCacheExpiry();

        CachedResource second = manager.getResource("foo.txt");

        assertNotNull(first);
        assertNotNull(second);
        assertNotSame(first, second);
        assertEquals(new Date(LAST_MODIFIED), second.getLastModified());
        assertEquals(2, underlying.getResourceCalls);
    }

    @Test
