    void nullPathReturnsNullWithoutConsultingUnderlying() throws IOException {
        CachingResourceManager manager = newManager(CachingResourceManager.MAX_AGE_NO_EXPIRY);
        underlying.failure = new IOException("underlying must not be consulted for a null path");

        assertNull(manager.getResource(null));

        assertEquals(0, underlying.getResourceCalls);
        assertTrue(underlying.requestedPaths.isEmpty());
    }

}

