    @Test
    public void parseRequestWithNamedAndCodedHeadersAddsThemToTheExchange() throws Exception {
        byte[] data = requestHead("/with/headers", 0)
                .int16(2)
                .codedHeader(0x07).string("text/html")
                .header("X-Custom", "some-value")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 100, false), data);

        assertEquals("text/html", exchange.getRequestHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("some-value", exchange.getRequestHeaders().getFirst(new HttpString("X-Custom")));
        assertEquals(2, exchange.getRequestHeaders().size());
    }

    @Test
    public void parseRequestWithTooManyHeadersMarksBadRequestAndIgnoresHeaders() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = requestHead("/too/many/headers", 0)
                .int16(2)
                .codedHeader(0x07).string("text/html")
                .header("X-Custom", "some-value")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 1, false), data, state);

        assertTrue(state.isComplete());
        assertTrue(state.badRequest);
        assertEquals(2, state.numHeaders);
        assertTrue(exchange.getRequestHeaders().isEmpty());
        assertEquals("/too/many/headers", exchange.getRequestURI());
    }

    @Test
    public void parseByteByByteProducesTheSameResultAsParsingInOneGo() throws Exception {
        byte[] data = requestHeader(4)
                .string("HTTP/1.1")
                .string("/byte/wise")
                .string("192.168.0.5")
                .string("")
                .string("bytehost")
                .int16(8443)
                .raw(1)
                .int16(1)
                .codedHeader(0x09).string("session=abc")
                .attribute(1, "/context")
                .endAttributes()
                .build();

        AjpRequestParseState incrementalState = new AjpRequestParseState();
        HttpServerExchange incremental = parseByteByByte(defaultParser(), data, incrementalState);
        AjpRequestParseState wholeState = new AjpRequestParseState();
        HttpServerExchange whole = parseInOneGo(defaultParser(), data, wholeState);

        assertTrue(incrementalState.isComplete());
        assertEquals(1, incrementalState.readHeaders);
        assertEquals(wholeState.serverPort, incrementalState.serverPort);
        assertEquals(wholeState.remoteAddress, incrementalState.remoteAddress);
        assertEquals(wholeState.attributes, incrementalState.attributes);

        assertEquals(Methods.POST, incremental.getRequestMethod());
        assertEquals(Protocols.HTTP_1_1, incremental.getProtocol());
        assertEquals("/byte/wise", incremental.getRequestURI());
        assertEquals("https", incremental.getRequestScheme());
        assertEquals("session=abc", incremental.getRequestHeaders().getFirst(Headers.COOKIE));
        assertEquals("192.168.0.5", incrementalState.remoteAddress);
        assertEquals(8443, incrementalState.serverPort);
        assertEquals("/context", incrementalState.attributes.get(AjpRequestParser.CONTEXT));

        assertEquals(whole.getRequestMethod(), incremental.getRequestMethod());
        assertEquals(whole.getRequestURI(), incremental.getRequestURI());
        assertEquals(whole.getRequestPath(), incremental.getRequestPath());
        assertEquals("session=abc", whole.getRequestHeaders().getFirst(Headers.COOKIE));
    }

    @Test
    public void parseRequestWithEmptyAndNullStrings() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = requestHeader(3)
                .string("HTTP/1.0")
                .string("/nulls")
                .nullString()
                .string("")
                .nullString()
                .int16(SERVER_PORT)
                .raw(0)
                .int16(0)
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertNull(state.remoteAddress);
        assertNull(state.serverAddress);
        assertEquals(Protocols.HTTP_1_0, exchange.getProtocol());
        assertEquals("/nulls", exchange.getRequestURI());
    }

    @Test
