                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 100, false), data);

        assertEquals("/foo%20bar", exchange.getRequestURI());
        assertEquals("/foo bar", exchange.getRequestPath());
        assertEquals("/foo bar", exchange.getRelativePath());
    }

    @Test
    public void parseRequestWithEncodedUriAndDecodingDisabledKeepsEncodedPath() throws Exception {
        byte[] data = requestWithUri("/foo%20bar")
                .endAttributes()
