        assertEquals("/foo%20bar", exchange.getRequestPath());
    }

    @Test
    public void parseRequestWithUnencodedUriCharactersThrowsWhenNotAllowed() {
        byte[] data = requestWithUri("/caf").build();
        // rebuild with raw high bytes in the URI
        byte[] uriData = requestHeader(2)
                .string("HTTP/1.1")
                .stringBytes(new byte[] { '/', 'c', 'a', 'f', (byte) 0xC3, (byte) 0xA9 })
                .string("127.0.0.1")
                .string("")
                .string("localhost")
                .int16(SERVER_PORT)
                .raw(0)
                .int16(0)
                .endAttributes()
                .build();
        assertTrue(data.length > 0);

        assertThrows(BadRequestException.class, () -> parseInOneGo(parser(true, 100, 100, false), uriData));
    }

    @Test
    public void parseRequestWithUnencodedUriCharactersIsAcceptedWhenAllowed() throws Exception {
        byte[] data = requestHeader(2)
                .string("HTTP/1.1")
                .stringBytes(new byte[] { '/', 'c', 'a', 'f', (byte) 0xC3, (byte) 0xA9 })
                .string("127.0.0.1")
                .string("")
                .string("localhost")
                .int16(SERVER_PORT)
                .raw(0)
                .int16(0)
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 100, true), data);

        assertEquals("/caf\u00e9", exchange.getRequestURI());
        assertEquals("/caf\u00e9", exchange.getRequestPath());
        assertEquals("/caf\u00e9", exchange.getRelativePath());
    }

    @Test
    public void parseRequestWithPathParametersExtractsThemAndKeepsThePath() throws Exception {
