    @Test
    void headerWithPackedIndexIsResolvedFromHeaderTable() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        ByteBuffer buf = buffer(0x01, 0x08);

        StringHolder holder = parser().parseString(buf, state, StringType.HEADER);

        assertNull(holder.value);
        assertSame(Headers.CONTENT_LENGTH, holder.header);
        assertTrue(holder.readComplete);
        assertFalse(holder.containsUrlCharacters);
        assertFalse(holder.containsUnencodedCharacters);
        assertEquals(-1, state.stringLength);
        assertEquals(2, buf.position());
    }

    @Test
