    private static final class RecordingSessionListener implements SessionListener {

        private final List<Session> created = new ArrayList<>();
        private final List<HttpServerExchange> createdExchanges = new ArrayList<>();
        private final List<Session> destroyed = new ArrayList<>();
        private final List<HttpServerExchange> destroyExchanges = new ArrayList<>();
        private final List<SessionDestroyedReason> destroyReasons = new ArrayList<>();

        @Override
        public void sessionCreated(final Session session, final HttpServerExchange exchange) {
            created.add(session);
            createdExchanges.add(exchange);
        }

        @Override
        public void sessionDestroyed(final Session session, final HttpServerExchange exchange,
                final SessionDestroyedReason reason) {
            destroyed.add(session);
            destroyExchanges.add(exchange);
            destroyReasons.add(reason);
        }
    }

    private static final class TestSessionConfig implements SessionConfig {

        private static final AttachmentKey<String> SESSION_ID = AttachmentKey.create(String.class);

        private final String requestedSessionId;
        private int setSessionIdCount;
        private String lastSetSessionId;
        private int clearSessionCount;

        TestSessionConfig() {
            this(null);
        }

        TestSessionConfig(final String requestedSessionId) {
            this.requestedSessionId = requestedSessionId;
        }

        @Override
        public void setSessionId(final HttpServerExchange exchange, final String sessionId) {
            this.setSessionIdCount++;
            this.lastSetSessionId = sessionId;
            exchange.putAttachment(SESSION_ID, sessionId);
        }

        @Override
        public void clearSession(final HttpServerExchange exchange, final String sessionId) {
            this.clearSessionCount++;
            exchange.removeAttachment(SESSION_ID);
        }

        @Override
        public String findSessionId(final HttpServerExchange exchange) {
            final String attached = exchange.getAttachment(SESSION_ID);
            return attached != null ? attached : requestedSessionId;
        }

        @Override
        public SessionCookieSource sessionCookieSource(final HttpServerExchange exchange) {
            return SessionCookieSource.COOKIE;
        }

        @Override
        public String rewriteUrl(final String originalUrl, final String sessionId) {
            return originalUrl + ";jsessionid=" + sessionId;
        }
    }
