        final AtomicInteger counter = new AtomicInteger();
        final InMemorySessionManager sessionManager = manager(countingIdGenerator("generated-", counter), -1, false, true);
        final HttpServerExchange exchange = newExchange();
        final TestSessionConfig config = new TestSessionConfig();

        final Session session = sessionManager.createSession(exchange, config);

        assertNotNull(session);
        assertEquals("generated-1", session.getId());
        assertSame(session, sessionManager.getSession("generated-1"));
        assertEquals(1L, sessionManager.getActiveSessionCount());
        assertEquals(1L, sessionManager.getCreatedSessionCount());
        assertSame(sessionManager, session.getSessionManager());
        assertFalse(session.isInvalid());
