    @Test
    void invalidatedSessionsFreeUpCapacityWhenExpiryIsEnabled() {
        final InMemorySessionManager sessionManager = manager(countingIdGenerator("s-", new AtomicInteger()), 1, true, true);
        final Session first = sessionManager.createSession(newExchange(), new TestSessionConfig());
