        final AtomicInteger counter = new AtomicInteger();
        final SessionIdGenerator collidingGenerator = () -> {
            counter.incrementAndGet();
            return "collision";
        };
        final InMemorySessionManager sessionManager = manager(collidingGenerator, -1, false, true);
        sessionManager.createSession(newExchange(), new TestSessionConfig("collision"));

