        assertEquals("s-2", second.getId());
        assertEquals("s-3", third.getId());
        assertEquals(3L, sessionManager.getActiveSessionCount());
        assertEquals(3, sessionManager.getAllSessions().size());
        assertTrue(sessionManager.getAllSessions().contains("s-1"));
