package io.undertow.util;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Instant;

import io.undertow.server.handlers.Cookie;

import org.junit.jupiter.api.Test;

/**
 * Tests for {@link Cookies#parseSetCookieHeader(String)}.
 */
public class CookiesParseSetCookieHeaderTests {

    @Test
    public void testSimpleNameValuePairUsesCookieDefaults() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=bar");

        assertNotNull(cookie);
        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
        assertNull(cookie.getPath());
        assertNull(cookie.getDomain());
        assertNull(cookie.getExpires());
        assertNull(cookie.getComment());
        assertNull(cookie.getSameSiteMode());
        assertEquals(Integer.valueOf(-1), cookie.getMaxAge());
        assertEquals(0, cookie.getVersion());
        assertFalse(cookie.isSecure());
        assertFalse(cookie.isHttpOnly());
        assertFalse(cookie.isDiscard());
        assertTrue(cookie.getAttributes().isEmpty(), "no attributes expected, got " + cookie.getAttributes());
    }

    @Test
    public void testAllStandardAttributesAreParsed() {
        Cookie cookie = Cookies.parseSetCookieHeader(
                "foo=bar; Path=/x; Domain=example.com; Max-Age=100; Secure; HttpOnly; Discard");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
        assertEquals("/x", cookie.getPath());
        assertEquals("example.com", cookie.getDomain());
        assertEquals(Integer.valueOf(100), cookie.getMaxAge());
        assertTrue(cookie.isSecure());
        assertTrue(cookie.isHttpOnly());
        assertTrue(cookie.isDiscard());

        assertEquals("/x", cookie.getAttribute("Path"));
        assertEquals("example.com", cookie.getAttribute("Domain"));
        assertEquals("100", cookie.getAttribute("Max-Age"));
        assertEquals("true", cookie.getAttribute("Secure"));
        assertEquals("true", cookie.getAttribute("HttpOnly"));
        assertEquals("true", cookie.getAttribute("Discard"));
    }

    @Test
    public void testAttributeNamesAreMatchedCaseInsensitively() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=bar; PATH=/Upper; dOmAiN=Example.COM; mAx-AgE=7; sEcUrE");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
        assertEquals("/Upper", cookie.getPath());
        assertEquals("Example.COM", cookie.getDomain());
        assertEquals(Integer.valueOf(7), cookie.getMaxAge());
        assertTrue(cookie.isSecure());
    }

    @Test
    public void testVersionAndCommentAttributes() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=bar; Version=1; Comment=hello world");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
        assertEquals(1, cookie.getVersion());
        assertEquals("hello world", cookie.getComment());
        assertEquals("hello world", cookie.getAttribute("Comment"));
    }

    @Test
    public void testExpiresAttributeIsConvertedToDate() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=bar; Expires=Wed, 09 Jun 2021 10:18:14 GMT");

        assertNotNull(cookie.getExpires());
        assertEquals(Instant.parse("2021-06-09T10:18:14Z").toEpochMilli(), cookie.getExpires().getTime());
        assertEquals("Wed, 09 Jun 2021 10:18:14 GMT", cookie.getAttribute("Expires"));
    }

    @Test
    public void testUnparsableExpiresLeavesExpiresUnset() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=bar; Expires=not-a-date");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
        assertNull(cookie.getExpires());
        assertNull(cookie.getAttribute("Expires"));
        assertTrue(cookie.getAttributes().isEmpty(), "no attributes expected, got " + cookie.getAttributes());
    }

    @Test
    public void testQuotedValueIsUnquoted() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=\"bar\"");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
    }

    @Test
    public void testQuotedValueKeepsSeparatorsAndSpaces() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=\"a; b=c d\"; Path=/q");

        assertEquals("foo", cookie.getName());
        assertEquals("a; b=c d", cookie.getValue());
        assertEquals("/q", cookie.getPath());
    }

    @Test
    public void testQuotedValueThatIsNotTerminatedConsumesRestOfHeader() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=\"bar");

        assertEquals("foo", cookie.getName());
        assertEquals("bar", cookie.getValue());
    }

    @Test
    public void testEmptyQuotedValue() {
        Cookie cookie = Cookies.parseSetCookieHeader("foo=\"\"; Path=/p");

        assertEquals("foo", cookie.getName());
        assertEquals("", cookie.getValue());
        assertEquals("/p", cookie.getPath());
    }

