 */
class ETagUtilsParseETagListTests {

    private static List<ETag> parse(final String header) {
        return ETagUtils.parseETagList(header);
    }

    private static ETag strong(final String tag) {
        return new ETag(false, tag);
    }

    private static ETag weak(final String tag) {
        return new ETag(true, tag);
    }

    @Test
    @DisplayName("A single strong quoted entity tag is parsed")
    void parsesSingleStrongTag() {
        assertEquals(Collections.singletonList(strong("tag")), parse("\"tag\""));
    }

    @Test
    @DisplayName("A single weak entity tag is parsed")
    void parsesSingleWeakTag() {
        assertEquals(Collections.singletonList(weak("tag")), parse("W/\"tag\""));
    }

    @Test
    @DisplayName("The weak marker without a slash is still treated as weak")
    void parsesWeakTagWithoutSlash() {
        assertEquals(Collections.singletonList(weak("tag")), parse("W\"tag\""));
    }

    @Test
    @DisplayName("Multiple comma separated strong tags are parsed in order")
    void parsesMultipleStrongTagsInOrder() {
        assertEquals(Arrays.asList(strong("one"), strong("two"), strong("three")),
                parse("\"one\", \"two\", \"three\""));
    }

    @Test
    @DisplayName("Mixed weak and strong tags are parsed in order")
    void parsesMixedWeakAndStrongTagsInOrder() {
        assertEquals(Arrays.asList(strong("a"), weak("b"), strong("c"), weak("d")),
                parse("\"a\", W/\"b\", \"c\", W/\"d\""));
    }

    @Test
    @DisplayName("Leading, trailing, and repeated commas and whitespace are ignored")
    void ignoresDelimitersAndWhitespace() {
        assertEquals(Arrays.asList(strong("a"), strong("b")),
                parse("  ,,  \"a\" ,, \t \"b\" ,,  "));
    }

    @Test
    @DisplayName("Surrounding whitespace inside the quotes is trimmed")
    void trimsWhitespaceInsideQuotes() {
        assertEquals(Collections.singletonList(strong("tag")), parse("\"   tag   \""));
    }

    @Test
    @DisplayName("Internal whitespace inside a tag is preserved")
    void preservesInternalWhitespace() {
        assertEquals(Collections.singletonList(strong("a b\tc")), parse("\"a b\tc\""));
    }

    @Test
    @DisplayName("A tag whose content is only whitespace becomes empty")
    void whitespaceOnlyTagBecomesEmpty() {
        assertEquals(Collections.singletonList(strong("")), parse("\"   \""));
    }

    @Test
    @DisplayName("An empty quoted tag is parsed as an empty tag")
    void parsesEmptyTag() {
        assertEquals(Collections.singletonList(strong("")), parse("\"\""));
    }

    @Test
    @DisplayName("A comma inside the quotes does not split the tag")
    void commaInsideQuotesIsPartOfTag() {
        assertEquals(Collections.singletonList(strong("a,b")), parse("\"a,b\""));
    }

    @Test
    @DisplayName("An unterminated strong tag is captured up to the end of the header")
    void parsesUnterminatedStrongTag() {
        assertEquals(Collections.singletonList(strong("tag")), parse("\"tag"));
    }

    @Test
    @DisplayName("An unterminated weak tag is captured up to the end of the header")
    void parsesUnterminatedWeakTag() {
        assertEquals(Collections.singletonList(weak("tag")), parse("W/\"tag"));
    }

    @Test
    @DisplayName("A trailing comma does not create an extra tag")
    void ignoresTrailingComma() {
        assertEquals(Collections.singletonList(strong("a")), parse("\"a\","));
    }

    @Test
    @DisplayName("Text after a closed quoted tag is ignored until the next quote")
    void ignoresTrailingTextAfterClosedTag() {
        assertEquals(Collections.singletonList(strong("a")), parse("\"a\"junk"));
    }

    @Test
    @DisplayName("An unquoted token is not a valid entity tag and is ignored")
    void ignoresUnquotedToken() {
        assertTrue(parse("token").isEmpty());
    }

    @Test
    @DisplayName("A wildcard is not an entity tag and is ignored")
    void ignoresWildcard() {
        assertTrue(parse("*").isEmpty());
    }

    @Test
    @DisplayName("An empty header produces an empty list")
    void emptyHeaderProducesEmptyList() {
        assertTrue(parse("").isEmpty());
    }

    @Test
    @DisplayName("A header containing only whitespace and commas produces an empty list")
    void blankHeaderProducesEmptyList() {
        assertTrue(parse("   ,  ,\t ").isEmpty());
    }

    @Test
    @DisplayName("A malformed weak tag without the slash produces no tag")
    void malformedWeakTagProducesNoTag() {
        assertTrue(parse("Wx\"tag\"").isEmpty());
    }

    @Test
    @DisplayName("A dangling weak marker produces no tag")
    void danglingWeakMarkerProducesNoTag() {
        assertTrue(parse("W/").isEmpty());
    }

    @Test
    @DisplayName("A null header is rejected with a NullPointerException")
    void nullHeaderThrows() {
        assertThrows(NullPointerException.class, () -> parse(null));
