/**
 * Tests for {@link ETagUtils#getETag(HttpServerExchange)}.
 *
 * <p>The method reads the first {@code ETag} response header of the given exchange and returns the
 * entity tag it represents, or {@code null} when the header is absent or cannot be interpreted.</p>
 */
class ETagUtilsGetETagTests {

    private static final String STRONG = "\"abc\"";
    private static final String WEAK = "W/\"abc\"";

    private static HttpServerExchange exchangeWithResponseETag(final String headerValue) {
        final HttpServerExchange exchange = new HttpServerExchange(null);
        if (headerValue != null) {
            exchange.getResponseHeaders().put(Headers.ETAG, headerValue);
        }
        return exchange;
    }

    private static ETag parse(final String headerValue) {
        return ETagUtils.getETag(exchangeWithResponseETag(headerValue));
    }

    private static void assertParsedETag(final String headerValue, final boolean expectedWeak, final String expectedTag) {
        final ETag eTag = parse(headerValue);
        assertNotNull(eTag, () -> "Expected an ETag to be parsed from response header <" + headerValue + ">");
        assertEquals(expectedWeak, eTag.isWeak(), () -> "Unexpected weakness for response header <" + headerValue + ">");
        assertEquals(expectedTag, eTag.getTag(), () -> "Unexpected tag for response header <" + headerValue + ">");
        final String expectedToString = expectedWeak ? "W/\"" + expectedTag + "\"" : "\"" + expectedTag + "\"";
        assertEquals(expectedToString, eTag.toString(), () -> "toString mismatch for response header <" + headerValue + ">");
    }

    private static void assertNotParsed(final String headerValue) {
        assertNull(parse(headerValue), () -> "Expected no ETag for malformed response header <" + headerValue + ">");
    }

    // ------------------------------------------------------------------ absence

    @Test
    @DisplayName("No ETag response header yields null")
    void noETagResponseHeaderYieldsNull() {
        assertNull(ETagUtils.getETag(new HttpServerExchange(null)));
    }

    @Test
    @DisplayName("An ETag request header is ignored; only the response header is used")
    void requestETagHeaderIsIgnored() {
        final HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.getRequestHeaders().put(Headers.ETAG, STRONG);
        assertNull(ETagUtils.getETag(exchange));
    }

    @Test
    @DisplayName("Only the first of several ETag response header values is considered")
    void onlyFirstResponseHeaderValueIsUsed() {
        final HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.getResponseHeaders().add(Headers.ETAG, "\"first\"");
        exchange.getResponseHeaders().add(Headers.ETAG, "\"second\"");
        final ETag eTag = ETagUtils.getETag(exchange);
        assertNotNull(eTag);
        assertFalse(eTag.isWeak());
        assertEquals("first", eTag.getTag());
    }

    // ------------------------------------------------------------- single values

    @Test
    @DisplayName("A simple strong entity tag is parsed")
    void simpleStrongETagIsParsed() {
        assertParsedETag(STRONG, false, "abc");
    }

    @Test
    @DisplayName("A simple weak entity tag is parsed as weak")
    void simpleWeakETagIsParsed() {
        assertParsedETag(WEAK, true, "abc");
