    void whitespaceOnlyTagIsTrimmedToEmpty() {
        assertParsedETag("\"    \"", false, "");
    }

    @Test
    @DisplayName("Inner whitespace of a tag is preserved")
    void innerWhitespaceOfTagIsPreserved() {
        assertParsedETag("\"a b c\"", false, "a b c");
    }

    @Test
    @DisplayName("A comma inside the quotes does not terminate the value")
    void commaInsideQuotesDoesNotTerminateValue() {
        assertParsedETag("\"a,b\"", false, "a,b");
    }

    @Test
    @DisplayName("The letter W inside the quotes has no special meaning")
    void letterWInsideQuotesIsNotSpecial() {
        assertParsedETag("\"W/abc\"", false, "W/abc");
    }

    @Test
    @DisplayName("Non ASCII characters are preserved")
    void nonAsciiCharactersArePreserved() {
        assertParsedETag("\"h\u00e9llo-\u4e16\u754c\"", false, "h\u00e9llo-\u4e16\u754c");
    }

    @Test
    @DisplayName("Leading and trailing whitespace around the header value is ignored")
    void surroundingWhitespaceOfHeaderValueIsIgnored() {
        assertParsedETag("   " + STRONG + "  ", false, "abc");
        assertParsedETag("\t " + WEAK + " \t", true, "abc");
    }

    @Test
    @DisplayName("Leading commas and whitespace are skipped")
    void leadingCommasAreSkipped() {
        assertParsedETag(", " + STRONG, false, "abc");
        assertParsedETag(" , ," + WEAK, true, "abc");
    }

    @Test
    @DisplayName("The first tag of a list is returned")
    void firstTagOfListIsReturned() {
