        assertParsedETag("W/\"abc\";ignored", true, "abc");
    }

    // ---------------------------------------------------------- unterminated tags

    @Test
    @DisplayName("A tag without a closing quote is parsed to the end of the header value")
    void unterminatedStrongTagIsParsed() {
        assertParsedETag("\"abc", false, "abc");
    }

    @Test
