        }
        return deque;
    }

    private static FastConcurrentDirectDeque.Node<String> nodeFor(
            FastConcurrentDirectDeque<String> deque, String item) {
        for (FastConcurrentDirectDeque.Node<String> node = deque.first();
             node != null;
             node = deque.succ(node)) {
            if (item.equals(node.item)) {
                return node;
            }
        }
        return fail("No node found for item " + item);
    }

