/**
 * Tests for {@link FlexBase64.Encoder#encode(java.nio.ByteBuffer, java.nio.ByteBuffer)}.
 *
 * <p>Expected values are produced with the JDK's own Base64 implementation (an independent
 * implementation of the same wire format), plus a simple model of where line breaks are placed
 * when wrapping is enabled.</p>
 */
public class FlexBase64EncodeTests {

    private static final int BIG_CAPACITY = 1024;

    /* ------------------------------------------------------------------ helpers */

    private static byte[] ascii(String value) {
        return value.getBytes(StandardCharsets.US_ASCII);
    }

    /** Deterministic byte sequence that exercises every 6 bit group value. */
    private static byte[] sequence(int length) {
        return sequence(length, 0);
    }

    private static byte[] sequence(int length, int offset) {
        byte[] data = new byte[length];
        for (int i = 0; i < length; i++) {
            data[i] = (byte) ((i + offset) * 37 + 11);
        }
        return data;
    }
    /** Reads the whole content of a flipped buffer. */
    private static String asString(ByteBuffer buffer) {
        byte[] copy = new byte[buffer.remaining()];
        buffer.duplicate().get(copy);
        return new String(copy, StandardCharsets.ISO_8859_1);
    }

    /** Reads everything that was written into a target buffer, up to its current position. */
    private static String writtenAsString(ByteBuffer target) {
        ByteBuffer copy = target.duplicate();
        copy.position(0);
        copy.limit(target.position());
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return new String(bytes, StandardCharsets.ISO_8859_1);
    }

    /**
     * Drains {@code source} through the encoder using a target buffer of {@code targetCapacity}
     * bytes per call, collecting everything that was written. Each call uses a fresh buffer, so the
     * encoder must rely on its saved state to continue.
     */
    private static String encodeChunked(FlexBase64.Encoder encoder, ByteBuffer source, int targetCapacity,
            boolean complete) {
        StringBuilder out = new StringBuilder();
        ByteBuffer target = ByteBuffer.allocate(targetCapacity);
        while (source.hasRemaining()) {
            target.clear();
            int before = source.position();
            encoder.encode(source, target);
            if (source.position() == before) {
                throw new AssertionError("encoder made no progress (position " + before
                        + ", target capacity " + targetCapacity + ")");
            }
            target.flip();
            out.append(asString(target));
        }
        if (complete) {
            ByteBuffer tail = ByteBuffer.allocate(8);
            encoder.complete(tail);
            tail.flip();
            out.append(asString(tail));
        }
        return out.toString();
    }

    private static String encodeInOneGo(FlexBase64.Encoder encoder, ByteBuffer source, boolean complete) {
        return encodeChunked(encoder, source, BIG_CAPACITY, complete);
    }

    private static String plainBase64(byte[] data, boolean url) {
        return (url ? Base64.getUrlEncoder() : Base64.getEncoder()).encodeToString(data);
    }

    /**
     * Models the documented MIME style layout: a CRLF is emitted after every group of 76 encoded
     * characters and one final CRLF terminates the encoding session.
     */
    private static String wrappedBase64(byte[] data, boolean url) {
        String plain = plainBase64(data, url);
        StringBuilder out = new StringBuilder(plain.length() + plain.length() / 76 * 2 + 2);
        for (int i = 0; i < plain.length(); i++) {
            out.append(plain.charAt(i));
            if ((i + 1) % 76 == 0) {
                out.append("\r\n");
            }
        }
        out.append('\r').append('\n');
        return out.toString();
    }

