@Test
@DisplayName("encoding resumes correctly when fed one byte at a time")
void resumesFromEveryPartialState() {
    byte[] data = sequence(7);
    FlexBase64.Encoder encoder = FlexBase64.createEncoder(false);
    StringBuilder out = new StringBuilder();

    for (int i = 0; i < data.length; i++) {
        ByteBuffer source = ByteBuffer.wrap(data);
        source.position(i);
        source.limit(i + 1);
        ByteBuffer target = ByteBuffer.allocate(4);

        encoder.encode(source, target);

        target.flip();
        out.append(asString(target));
        assertEquals(i + 1, encoder.getLastInputPosition());
    }

    ByteBuffer tail = ByteBuffer.allocate(8);
    encoder.complete(tail);
    tail.flip();
    out.append(asString(tail));

    assertEquals(plainBase64(data, false), out.toString());
}

