@Test
@DisplayName("a target too small for the pending partial quad is left untouched")
void targetTooSmallForPartialQuadIsLeftUntouched() {
    FlexBase64.Encoder encoder = FlexBase64.createEncoder(false);

    ByteBuffer firstTarget = ByteBuffer.allocate(8);
    encoder.encode(ByteBuffer.wrap(new byte[] { (byte) 'f' }), firstTarget);
    firstTarget.flip();
    // one byte only produces one character, the encoder keeps a partial state
    assertEquals("Z", asString(firstTarget));

