    assertEquals(0, encoder.getLastInputPosition());

    ByteBuffer target = ByteBuffer.allocate(3);
    encoder.encode(source, target);
    assertEquals(1, target.position());
    assertEquals(0, source.remaining());
    assertEquals(1, encoder.getLastInputPosition());

    encoder.complete(target);
    target.flip();
    assertEquals("Zg==", asString(target));
}

