@Test
@DisplayName("chunked encoding without wrapping matches the JDK base64 value")
void chunkedUnwrappedEncodingMatchesJdk() {
    byte[] data = new byte[1000];
    new Random(1234L).nextBytes(data);

    assertEquals(0, source.position());
    assertEquals(0, encoder.getLastInputPosition());

    ByteBuffer target = ByteBuffer.allocate(3);
    encoder.encode(source, target);
    assertEquals(1, target.position());
    assertEquals(0, source.remaining());
    assertEquals(1, encoder.getLastInputPosition());

    encoder.complete(target);
    target.flip();
    // the second call contributes the remaining characters and the padding
    assertEquals("m8=", asString(target));
