private static byte[] decodeStreaming(Decoder decoder, byte[] encoded, int sourceChunkSize, int targetCapacity) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    ByteBuffer source = ByteBuffer.wrap(encoded);
    int limit = Math.min(sourceChunkSize, encoded.length);
    source.limit(limit);
    int guard = 0;
    while (guard++ < 100000) {
        int startPos = source.position();
        int startLimit = source.limit();
        ByteBuffer target = ByteBuffer.allocate(targetCapacity);
        decoder.decode(source, target);
        target.flip();
        byte[] chunk = new byte[target.remaining()];
        target.get(chunk);
        out.write(chunk, 0, chunk.length);
        int pos = source.position();
        if (pos >= encoded.length) {
            // fully consumed; but decoder may hold state - one more call with empty source? not needed
            break;
        }
        if (pos == startPos && pos == startLimit) {
            // need more data
            int newLimit = Math.min(encoded.length, pos + sourceChunkSize);
            if (newLimit == pos) break;
            source.limit(newLimit);
        } else if (pos == startPos) {
            // no progress with data available -> infinite loop guard
            // expand limit to be safe
            int newLimit = Math.min(encoded.length, pos + Math.max(sourceChunkSize, 1));
            if (newLimit == source.limit()) break;
            source.limit(newLimit);
        }
    }
    if (guard >= 100000) throw new IllegalStateException("decoder made no progress");
    return out.toByteArray();
}
