                int b = source[pos++] & 0xFF;
                if (this.state == 0) {
                    target[opos++] = ENCODING_TABLE[b >>> 2];
                    this.last = (b & 0x3) << 4;
                    this.state++;
                    if (pos >= limit) {
                        break;
                    }
                    b = source[pos++] & 0xFF;
                }
                if (this.state == 1) {
                    target[opos++] = ENCODING_TABLE[this.last | (b >>> 4)];
                    this.last = (b & 0x0F) << 2;
                    this.state++;
                    if (pos >= limit) {
                        break;
                    }
                    b = source[pos++] & 0xFF;
                }
                if (this.state == 2) {
                    target[opos++] = ENCODING_TABLE[this.last | (b >>> 6)];
                    target[opos++] = ENCODING_TABLE[b & 0x3F];

                    this.last = this.state = 0;
                }

