         */
        public void complete(ByteBuffer target) {
            if (state > 0) {
                target.put(encodingTable[last]);
                for (int i = state; i < 3; i++) {
                    target.put((byte)'=');
                }

                last = state = 0;
            }
            if (wrap) {
                target.putShort((short)0x0D0A);
            }

            count = 0;
        }
