    @Test
    void unwrappedOutputIsValidStandardBase64() throws IOException {
        byte[] data = data(1000);
        InputStream input = FlexBase64.createEncoderInputStream(new ByteArrayInputStream(data), 16, false);

        byte[] decoded = Base64.getDecoder().decode(readFully(input, 64));

