    @Test
    void wrappedOutputIsValidMimeBase64AndBreaksLinesAtSeventySixCharacters() throws IOException {
        byte[] data = data(200);
        InputStream input = FlexBase64.createEncoderInputStream(new ByteArrayInputStream(data), 16, true);

