    @Test
    void defaultFactoryUsesWrappedEncodingAndTheStreamCanBeReadInChunks() throws IOException {
        byte[] data = data(5000);
        InputStream input = FlexBase64.createEncoderInputStream(new ByteArrayInputStream(data));

        String encoded = asString(readFully(input, 999));

