@Test
void mixedReadSizesProduceAContinuousEncodedStream() throws IOException {
    int[] chunks = { 1, 2, 3, 4, 5, 6, 7, 8 };
    for (boolean wrap : new boolean[] { false, true }) {
        byte[] data = data(3000);
        InputStream input = FlexBase64.createEncoderInputStream(new ByteArrayInputStream(data), 8, wrap);
        ByteArrayOutputStream output = new ByteArrayOutputStream();

