package io.undertow.util;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Tests for {@link Headers#extractQuotedValueFromHeader(String, String)}.
 */
@DisplayName("Headers.extractQuotedValueFromHeader")
class HeadersExtractQuotedValueFromHeaderTests {

    @ParameterizedTest(name = "header [{0}], key [{1}] -> [{2}]")
    @CsvSource(delimiter = '|', value = {
            // Typical quoted and unquoted parameter values.
            "form-data; name=\"file\"; filename=\"foo.txt\"|filename|foo.txt",
            "form-data; filename=foo.txt|filename|foo.txt",
            "filename=foo.txt;|filename|foo.txt",
            // Quoted values keep spaces, semicolons and equals signs.
            "filename=\"foo bar.txt\"|filename|foo bar.txt",
            "filename=\"foo;bar\"|filename|foo;bar",
            "filename=\"a=b\"|filename|a=b",
            "foo=1; filename=\"a=b\"|filename|a=b",
            // Unquoted values stop at the '=' character? No: '=' is not a delimiter.
            "filename=a=b|filename|a=b",
            // Semicolon may be followed directly by the parameter name or by whitespace.
            "name=x;filename=\"foo\"|filename|foo",
            "name=\"a\"; filename=\"b\"|filename|b",
            // The requested parameter is selected from several parameters.
            "name=\"a\"; filename=\"b\"|name|a",
            "text/html;charset=utf-8|charset|utf-8",
            "text/html; charset=utf-8|charset|utf-8",
            // A prefix of the key followed by a non-'=' character does not stop the search.
            "filenameX=1; filename=\"foo\"|filename|foo",
            // Occurrences inside quoted values are ignored.
            "foo=\"filename=bar\"; filename=\"baz\"|filename|baz",
            // The first matching assignment wins.
            "filename=\"a\" filename=\"b\"|filename|a",
            // An unterminated quoted value yields the remainder of the header.
            "filename=\"foo|filename|foo",
            // Non-ASCII content is preserved.
            "filename=\"caf\u00e9\"|filename|caf\u00e9"
    })
    void extractsValueFromHeader(String header, String key, String expected) {
        assertEquals(expected, Headers.extractQuotedValueFromHeader(header, key));
    }

    @ParameterizedTest(name = "header [{0}] has no extractable filename parameter")
    @ValueSource(strings = {
            "",
            "a",
            "noequal",
            "filename",
            "filename; charset=utf-8",
            "xfilename=\"foo\"",
            "prefixfilename=\"foo\"",
            "foo=\"filename=bar\"",
            "filenameX=1; other=y"
    })
    void returnsNullWhenKeyIsNotAnAssignableParameter(String header) {
        assertNull(Headers.extractQuotedValueFromHeader(header, "filename"));
    }

    @Test
    @DisplayName("returns null when the key is absent from a populated header")
    void returnsNullWhenKeyIsAbsent() {
        assertNull(Headers.extractQuotedValueFromHeader(
                "form-data; name=\"file\"; filename=\"foo.txt\"", "charset"));
    }

    @Test
    @DisplayName("key matching is case sensitive")
    void keyMatchingIsCaseSensitive() {
        assertNull(Headers.extractQuotedValueFromHeader("charset=UTF-8", "CHARSET"));
        assertNull(Headers.extractQuotedValueFromHeader("Charset=UTF-8", "charset"));
        assertEquals("UTF-8", Headers.extractQuotedValueFromHeader("Charset=UTF-8", "Charset"));
    }

    @Test
    @DisplayName("quoted empty value is returned as an empty string")
    void quotedEmptyValueReturnsEmptyString() {
        assertEquals("", Headers.extractQuotedValueFromHeader("filename=\"\"", "filename"));
        assertEquals("", Headers.extractQuotedValueFromHeader(
                "form-data; name=\"file\"; filename=\"\"", "filename"));
    }

    @Test
    @DisplayName("an empty unquoted value is returned as an empty string")
    void emptyUnquotedValueReturnsEmptyString() {
        assertEquals("", Headers.extractQuotedValueFromHeader("filename= ; foo=bar", "filename"));
        assertEquals("", Headers.extractQuotedValueFromHeader("filename=;foo=bar", "filename"));
    }

    @Test
    @DisplayName("space terminates an unquoted value")
    void spaceTerminatesUnquotedValue() {
        assertEquals("foo", Headers.extractQuotedValueFromHeader("filename=foo bar", "filename"));
    }

    @Test
    @DisplayName("tab terminates an unquoted value")
    void tabTerminatesUnquotedValue() {
        assertEquals("foo", Headers.extractQuotedValueFromHeader("filename=foo\tbar", "filename"));
    }

    @Test
    @DisplayName("semicolon terminates an unquoted value")
    void semicolonTerminatesUnquotedValue() {
        assertEquals("foo", Headers.extractQuotedValueFromHeader(
                "filename=foo; charset=utf-8", "filename"));
    }

    @Test
    @DisplayName("comma is not treated as an unquoted value terminator")
    void commaIsNotAnUnquotedValueTerminator() {
        assertEquals("utf-8,", Headers.extractQuotedValueFromHeader(
                "charset=utf-8, foo=bar", "charset"));
    }

    @Test
