            "name=\"a\"; filename=\"b\"|name|a",
            "text/html;charset=utf-8|charset|utf-8",
            "text/html; charset=utf-8|charset|utf-8",
            // A prefix of the key followed by a non-'=' character does not stop the search.
            "filenameX=1; filename=\"foo\"|filename|foo",
            // Occurrences inside quoted values are ignored.
            "foo=\"filename=bar\"; filename=\"baz\"|filename|baz",
            // The first matching assignment wins.
            "filename=\"a\" filename=\"b\"|filename|a",
