        assertEquals("utf-8,", Headers.extractQuotedValueFromHeader(
                "charset=utf-8, foo=bar", "charset"));
    }

    @Test
    @DisplayName("a key at the very beginning of the header is matched")
    void keyAtBeginningOfHeaderIsMatched() {
        assertEquals("foo", Headers.extractQuotedValueFromHeader("filename=\"foo\"", "filename"));
    }

