    }

    @Test
    public void testValuesAreSortedAcrossMultipleHeaders() {
        assertEquals("[deflate/0.9] [a/0.5]", parseAndRender("a;q=0.5", "deflate;q=0.9"));
    }

    @Test
    public void testQValueZeroIsKeptAsItsOwnGroup() {
        assertEquals("[c/1] [a/0] [b/0.5]", parseAndRender("a;q=0, b;q=0.5, c"));
    }

    @Test
    public void testMultipleZeroQValuesKeepTheirOrder() {
        assertEquals("[identity/0,*/0]", parseAndRender("identity;q=0, *;q=0"));
    }

    @Test
    public void testWildcardWithoutQValue() {
        assertEquals("[*/1]", parseAndRender("*"));
    }

    @Test
    public void testWildcardIsPreferredOverLowerQValue() {
        assertEquals("[*/1] [gzip/0.5]", parseAndRender("gzip;q=0.5, *"));
    }

    @Test
    public void testSemicolonSeparatesValuesWhenNoQValueIsPresent() {
        assertEquals("[gzip/1,deflate/1]", parseAndRender("gzip;deflate"));
    }

    @Test
    public void testWhitespaceAroundSeparatorsIsIgnored() {
        assertEquals("[a/1,b/1,c/1]", parseAndRender("a, b , c"));
    }

    @Test
    public void testEmptySegmentsAreIgnored() {
        assertEquals("[a/1,b/1]", parseAndRender("a,,b"));
        assertTrue(QValueParser.parse(Collections.singletonList(",,")).isEmpty());
    }

    @Test
    public void testBlankHeadersProduceNoResults() {
        assertTrue(QValueParser.parse(Collections.singletonList("")).isEmpty());
        assertTrue(QValueParser.parse(Collections.singletonList("   ")).isEmpty());
        assertTrue(QValueParser.parse(Arrays.asList("", "  ")).isEmpty());
    }

    @Test
    public void testQValueWithoutPrecedingValueIsTreatedAsAValue() {
        assertEquals("[q=0.5/1]", parseAndRender("q=0.5"));
    }

    @Test
    public void testQValueMarkerWithoutValueBecomesAValueOfItsOwn() {
        assertEquals("[a/1,q=/1]", parseAndRender("a;q="));
    }

    @Test
    public void testQValueIsNotValidated() {
        assertEquals("[a/b]", parseAndRender("a;q=b"));
    }

    @Test
    public void testQValueIsTakenVerbatimIncludingTrailingZeroes() {
        assertEquals("[a/1.000]", parseAndRender("a;q=1.000"));
        assertEquals("[a/0.001]", parseAndRender("a;q=0.001"));
    }

    @Test
    public void testShorterQValueStringIsConsideredHigherPriority() {
        // q values are compared as strings, so the single character "0" sorts above "0.5"
        assertEquals("[b/0] [a/0.5]", parseAndRender("a;q=0.5, b;q=0"));
    }

    @Test
    public void testExplicitOneIsSortedAfterTheDefaultOne() {
        assertEquals("[a/1] [b/1.0]", parseAndRender("a, b;q=1.0"));
    }

    @Test
    public void testQValuesThatDifferAfterFiveCharactersSharePrecedenceButNotGroup() {
        // only the first five characters are compared, so the relative order of the values is kept
        assertEquals("[a/0.123456] [b/0.123457]", parseAndRender("a;q=0.123456, b;q=0.123457"));
    }

    @Test
    public void testLanguageRangesAreParsed() {
        assertEquals("[en/0.8] [en-US/0.7]", parseAndRender("en-US;q=0.7,en;q=0.8"));
    }

    @Test
    public void testDuplicateValuesArePreserved() {
        assertEquals("[a/1,a/1]", parseAndRender("a, a"));
        assertEquals("[a/0.5,a/0.5]", parseAndRender("a;q=0.5, a;q=0.5"));
    }

    @Test
    public void testNullHeaderIsRejected() {
        assertThrows(NullPointerException.class, () -> QValueParser.parse(Collections.singletonList((String) null)));
    }

    @Test
    public void testNullHeaderListIsRejected() {
        assertThrows(NullPointerException.class, () -> QValueParser.parse(null));
    }
}
