package io.undertow.websockets.core;

import static org.easymock.EasyMock.createNiceMock;
import static org.easymock.EasyMock.expect;
import static org.easymock.EasyMock.replay;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link WebSocketFramePriority#insertFrame(StreamSinkFrameChannel, List)}.
 *
 * <p>The tests use a lightweight controllable {@link StreamSinkFrameChannel} implementation so
 * that frame type, fragmentation state, writability shutdown state, open state and brokenness can
 * all be observed directly.</p>
 */
class WebSocketFramePriorityInsertFrameTests {

    private WebSocketFramePriority priority;
    private List<StreamSinkFrameChannel> pendingFrames;
    private WebSocketChannel openChannel;
    private WebSocketChannel remotelyClosedChannel;

    @BeforeEach
    void setUp() {
        priority = new WebSocketFramePriority();
        pendingFrames = new ArrayList<>();

        openChannel = createNiceMock(WebSocketChannel.class);
        expect(openChannel.isCloseFrameReceived()).andReturn(false).anyTimes();
        replay(openChannel);

        remotelyClosedChannel = createNiceMock(WebSocketChannel.class);
        expect(remotelyClosedChannel.isCloseFrameReceived()).andReturn(true).anyTimes();
        replay(remotelyClosedChannel);
    }

    // ------------------------------------------------------------------
    // Simple, non-fragmented insertion
    // ------------------------------------------------------------------

    @Test
    @DisplayName("A regular frame is appended when no frames are pending")
    void regularFrameIsAppendedToEmptyPendingFrames() {
        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.TEXT);

        assertTrue(priority.insertFrame(frame, pendingFrames), "a normal frame must be accepted");

        assertEquals(1, pendingFrames.size());
        assertSame(frame, pendingFrames.get(0));
        assertFalse(frame.broken, "an accepted frame must not be marked broken");
        assertFalse(priority.closed);
    }

    @Test
    @DisplayName("Regular frames are appended in insertion order when no fragmentation is active")
    void regularFramesAreAppendedInOrder() {
        TestStreamSinkFrameChannel first = frame(WebSocketFrameType.TEXT).writesShutdown(true);
        TestStreamSinkFrameChannel second = frame(WebSocketFrameType.BINARY).writesShutdown(true);

        assertTrue(priority.insertFrame(first, pendingFrames));
        assertTrue(priority.insertFrame(second, pendingFrames));

        assertEquals(List.of(first, second), pendingFrames);
        assertFalse(first.broken);
        assertFalse(second.broken);
    }

    @Test
    @DisplayName("A frame is dropped and marked broken when the priority is already closed")
    void frameIsDroppedWhenPriorityIsClosed() {
        priority.closed = true;
        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.TEXT);

        assertTrue(priority.insertFrame(frame, pendingFrames), "closed priority still reports the frame as consumed");

        assertTrue(pendingFrames.isEmpty(), "a dropped frame must not be queued");
        assertTrue(frame.broken, "a dropped frame must be marked broken");
    }

    @Test
    @DisplayName("Control frames are also dropped when the priority is closed")
    void controlFrameIsDroppedWhenPriorityIsClosed() {
        priority.closed = true;
        TestStreamSinkFrameChannel ping = frame(WebSocketFrameType.PING).writesShutdown(true);

        assertTrue(priority.insertFrame(ping, pendingFrames));

        assertTrue(pendingFrames.isEmpty());
        assertTrue(ping.broken);
    }

    @Test
    @DisplayName("A close frame is queued and closes the priority for later frames")
    void closeFrameClosesPriority() {
        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed, "a close frame must close the priority");

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.TEXT);
        assertTrue(priority.insertFrame(later, pendingFrames));

        assertEquals(List.of(close), pendingFrames, "frames after close must not be queued");
        assertTrue(later.broken, "frames after close must be marked broken");
    }

    // ------------------------------------------------------------------
    // Strict ordering queue
    // ------------------------------------------------------------------

    @Test
    @DisplayName("A non-control frame is rejected while another stream's strict-order frame is open")
    void nonControlFrameIsRejectedWhileStrictOrderFrameIsOpen() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.BINARY);

        assertFalse(priority.insertFrame(frame, pendingFrames),
                "strict ordering must reject a frame that is not at the head of the order queue");
        assertTrue(pendingFrames.isEmpty());
        assertFalse(frame.broken, "a rejected frame must not be marked broken");
    }

    @Test
    @DisplayName("A non-control frame is accepted when the head strict-order frame is no longer open")
    void nonControlFrameIsAcceptedWhenStrictOrderFrameIsClosed() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(false);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.BINARY);

        assertTrue(priority.insertFrame(frame, pendingFrames));
        assertEquals(List.of(frame), pendingFrames);
    }

    @Test
    @DisplayName("A close frame is rejected while ordering is outstanding and no remote close was received")
    void closeFrameIsRejectedWhileStrictOrderFrameIsOpenAndNoRemoteClose() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, remotelyClosedChannel);

        assertFalse(priority.insertFrame(close, pendingFrames));
        assertTrue(pendingFrames.isEmpty());
        assertFalse(priority.closed, "a rejected close frame must not close the priority");
    }

    @Test
    @DisplayName("A close frame is accepted while ordering is outstanding once the remote close was received")
    void closeFrameIsAcceptedAfterRemoteCloseReceived() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, remotelyClosedChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed);
    }

    @Test
    @DisplayName("A close frame is accepted while ordering is outstanding when immediate close is enabled")
    void closeFrameIsAcceptedWhenImmediateCloseFrameIsEnabled() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);
        priority.immediateCloseFrame();

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, openChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed);
    }

    @Test
    @DisplayName("A close frame is accepted when the outstanding strict-order frame is closed")
    void closeFrameIsAcceptedWhenStrictOrderFrameIsClosed() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(false);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, openChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed);
    }

    @Test
    @DisplayName("The strict-order head is removed when its final fragment is inserted")
    void finalFragmentOfStrictOrderHeadIsPolled() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT)
                .open(true).finalFragment(true).writesShutdown(true);
        priority.addToOrderQueue(order);

        assertTrue(priority.insertFrame(order, pendingFrames));
        assertEquals(List.of(order), pendingFrames);

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.BINARY);
        assertTrue(priority.insertFrame(later, pendingFrames),
                "after the order head is polled, later frames must be accepted");
        assertEquals(List.of(order, later), pendingFrames);
    }

    @Test
    @DisplayName("The strict-order head stays queued when its inserted frame is not final")
    void nonFinalFragmentOfStrictOrderHeadRemainsQueued() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT)
                .open(true).finalFragment(false).writesShutdown(true);
        priority.addToOrderQueue(order);

        assertTrue(priority.insertFrame(order, pendingFrames));
        assertEquals(List.of(order), pendingFrames);

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.BINARY);
        assertFalse(priority.insertFrame(later, pendingFrames),
                "the non-final order head must continue to block other streams");
        assertEquals(List.of(order), pendingFrames);
    }

    @Test
    @DisplayName("Control frames bypass the strict ordering queue")
    void controlFrameBypassesStrictOrderQueue() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel ping = frame(WebSocketFrameType.PING).writesShutdown(true);

        assertTrue(priority.insertFrame(ping, pendingFrames));
        assertEquals(List.of(ping), pendingFrames);
    }

    // ------------------------------------------------------------------
    // Control frame placement in the pending list
    // ------------------------------------------------------------------

    @Test
    @DisplayName("A control frame is inserted before the first non-control pending frame")
    void controlFrameIsInsertedBeforeFirstNonControlFrame() {
        TestStreamSinkFrameChannel inFlight = frame(WebSocketFrameType.BINARY).writesShutdown(true);
        TestStreamSinkFrameChannel pendingPing = frame(WebSocketFrameType.PING).writesShutdown(true);
        TestStreamSinkFrameChannel pendingPong = frame(WebSocketFrameType.PONG).writesShutdown(true);
        TestStreamSinkFrameChannel pendingText = frame(WebSocketFrameType.TEXT).writesShutdown(true);
        pendingFrames.add(inFlight);
        pendingFrames.add(pendingPing);
        pendingFrames.add(pendingPong);
        pendingFrames.add(pendingText);

        TestStreamSinkFrameChannel newPing = frame(WebSocketFrameType.PING).writesShutdown(true);

        assertTrue(priority.insertFrame(newPing, pendingFrames));

        assertEquals(List.of(inFlight, pendingPing, pendingPong, newPing, pendingText), pendingFrames);
    }

    @Test
    @DisplayName("A control frame is appended when the pending list contains only one frame")
    void controlFrameIsAppendedWhenPendingListHasSingleFrame() {
        TestStreamSinkFrameChannel inFlight = frame(WebSocketFrameType.TEXT).writesShutdown(true);
        pendingFrames.add(inFlight);

        TestStreamSinkFrameChannel pong = frame(WebSocketFrameType.PONG).writesShutdown(true);

        assertTrue(priority.insertFrame(pong, pendingFrames));

        assertEquals(List.of(inFlight, pong), pendingFrames);
    }

    @Test
    @DisplayName("A control frame is appended when no non-control frame follows index zero")
    void controlFrameIsAppendedWhenAllPendingFramesAreControlFrames() {
        TestStreamSinkFrameChannel firstPing = frame(WebSocketFrameType.PING).writesShutdown(true);
        TestStreamSinkFrameChannel secondPong = frame(WebSocketFrameType.PONG).writesShutdown(true);
        pendingFrames.add(firstPing);
        pendingFrames.add(secondPong);

        TestStreamSinkFrameChannel newPong = frame(WebSocketFrameType.PONG).writesShutdown(true);

        assertTrue(priority.insertFrame(newPong, pendingFrames));

        assertEquals(List.of(firstPing, secondPong, newPong), pendingFrames);
    }

    // ------------------------------------------------------------------
    // Fragmented sends
    // ------------------------------------------------------------------

    @Test
    @DisplayName("A non-final frame starts a fragmented send")
    void nonFinalFrameStartsFragmentedSend() {
        TestStreamSinkFrameChannel fragmenter = frame(WebSocketFrameType.TEXT)
                .finalFragment(false).writesShutdown(false);

        assertTrue(priority.insertFrame(fragmenter, pendingFrames));
        assertEquals(List.of(fragmenter), pendingFrames);

        TestStreamSinkFrameChannel other = frame(WebSocketFrameType.BINARY);
        assertFalse(priority.insertFrame(other, pendingFrames),
                "another stream must be rejected while a fragmented send is active");
        assertEquals(List.of(fragmenter), pendingFrames);
        assertFalse(other.broken);
    }

    @Test
    @DisplayName("A frame whose writes are already shut down does not start a fragmented send")
    void writesShutdownFrameDoesNotStartFragmentedSend() {
        TestStreamSinkFrameChannel first = frame(WebSocketFrameType.TEXT).writesShutdown(true);
        TestStreamSinkFrameChannel second = frame(WebSocketFrameType.TEXT);

        assertTrue(priority.insertFrame(first, pendingFrames));
        assertTrue(priority.insertFrame(second, pendingFrames),
                "no fragmented send should be active after a writes-shutdown frame");

        assertEquals(List.of(first, second), pendingFrames);
    }

    @Test
    @DisplayName("A control frame is inserted at index one during a fragmented send")
    void controlFrameIsInsertedAfterInFlightFrameDuringFragmentation() {
        TestStreamSinkFrameChannel fragmenter = frame(WebSocketFrameType.TEXT)
                .finalFragment(false).writesShutdown(false);
        assertTrue(priority.insertFrame(fragmenter, pendingFrames));

        TestStreamSinkFrameChannel ping = frame(WebSocketFrameType.PING).writesShutdown(true);
        assertTrue(priority.insertFrame(ping, pendingFrames));

        assertEquals(List.of(fragmenter, ping), pendingFrames);

        TestStreamSinkFrameChannel other = frame(WebSocketFrameType.BINARY);
        assertFalse(priority.insertFrame(other, pendingFrames));
        assertEquals(List.of(fragmenter, ping), pendingFrames);
    }

    @Test
    @DisplayName("A control frame is appended during fragmentation when the pending list is empty")
    void controlFrameIsAppendedDuringFragmentationWhenPendingListIsEmpty() {
        TestStreamSinkFrameChannel fragmenter = frame(WebSocketFrameType.TEXT)
                .finalFragment(false).writesShutdown(false);
        assertTrue(priority.insertFrame(fragmenter, pendingFrames));

        pendingFrames.clear();

        TestStreamSinkFrameChannel pong = frame(WebSocketFrameType.PONG).writesShutdown(true);
        assertTrue(priority.insertFrame(pong, pendingFrames));

        assertEquals(List.of(pong), pendingFrames);
    }

    @Test
    @DisplayName("The same sender may continue a fragmented send with non-final frames")
    void sameFragmentSenderCanContinueWithNonFinalFragment() {
        TestStreamSinkFrameChannel fragmenter = frame(WebSocketFrameType.TEXT)
                .finalFragment(false).writesShutdown(false);
        assertTrue(priority.insertFrame(fragmenter, pendingFrames));

        assertTrue(priority.insertFrame(fragmenter, pendingFrames));
        assertEquals(List.of(fragmenter, fragmenter), pendingFrames);

        TestStreamSinkFrameChannel other = frame(WebSocketFrameType.TEXT);
        assertFalse(priority.insertFrame(other, pendingFrames),
                "the fragmented send must remain active after a non-final fragment");
    }

    @Test
    @DisplayName("A final fragment from the fragmented sender ends the fragmented send")
    void finalFragmentEndsFragmentedSend() {
