        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> Base64.encodeBytesToBytes(new byte[3], 2, 2, Base64.NO_OPTIONS));

        assertEquals("Cannot have offset of 2 and length of 2 with array of length 3", exception.getMessage());
    }

    @Test
    public void rejectsOffsetBeyondArrayEvenForZeroLength() {
        assertThrows(IllegalArgumentException.class,
                () -> Base64.encodeBytesToBytes(new byte[3], 4, 0, Base64.NO_OPTIONS));
    }
}

