    private final List<StreamSourceFrameChannel> createdChannels = new ArrayList<>();
    private final List<WebSocketChannel> createdWebSocketChannels = new ArrayList<>();

    @BeforeEach
    public void setUp() {
        bufferPool = new DefaultByteBufferPool(false, 1024);
        openConnections = new HashSet<>();

        sourceChannel = EasyMock.createNiceMock(StreamSourceChannel.class);
        sinkChannel = EasyMock.createNiceMock(StreamSinkChannel.class);
        connection = EasyMock.createNiceMock(StreamConnection.class);

        EasyMock.expect(connection.getSourceChannel()).andReturn(sourceChannel).anyTimes();
        EasyMock.expect(connection.getSinkChannel()).andReturn(sinkChannel).anyTimes();
        EasyMock.expect(sourceChannel.getReadSetter())
                .andReturn(new ChannelListener.SimpleSetter<StreamSourceChannel>()).anyTimes();
        EasyMock.expect(sinkChannel.getWriteSetter())
                .andReturn(new ChannelListener.SimpleSetter<StreamSinkChannel>()).anyTimes();
        EasyMock.expect(sourceChannel.getCloseSetter())
                .andReturn(new ChannelListener.SimpleSetter<StreamSourceChannel>()).anyTimes();
        EasyMock.expect(sinkChannel.getCloseSetter())
                .andReturn(new ChannelListener.SimpleSetter<StreamSinkChannel>()).anyTimes();

        EasyMock.replay(connection, sourceChannel, sinkChannel);
    }

    @AfterEach
    public void tearDown() {
        for (StreamSourceFrameChannel channel : createdChannels) {
            IoUtils.safeClose(channel);
        }
        createdChannels.clear();
        for (WebSocketChannel channel : createdWebSocketChannels) {
            IoUtils.safeClose(channel);
        }
        createdWebSocketChannels.clear();
        bufferPool.close();
        EasyMock.verify(connection, sourceChannel, sinkChannel);
        EasyMock.reset(connection, sourceChannel, sinkChannel);
    }

