    @Test
    public void testMaskedPingFrameCreatesPingSourceChannel() throws Exception {
        WebSocket07Channel channel = newChannel(false, false, NoopExtensionFunction.INSTANCE);
        WebSocket07Channel.WebSocketFrameHeader header = parse(channel,
                FIN_BIT | OPCODE_PING, MASK_BIT, 0x01, 0x02, 0x03, 0x04);

        StreamSourceFrameChannel source = createChannel(header);

        assertInstanceOf(WebSocket07PingFrameSourceChannel.class, source);
