    void cookieWithTooFewTokensThrowsInvalidFlags() {
        IllegalArgumentException exception = assertInvalidFlags("cookie=onlyname");
        assertTrue(exception.getMessage().contains(LINE));

        assertInvalidFlags("CO=onlyname");
        // A trailing empty value is not counted as a token by StringTokenizer.
        assertInvalidFlags("cookie=name:");
    }

