    void environmentLongFormSplitsOnFirstColon() {
        RewriteRule rule = newRule();
        RewriteConfigFactory.parseRuleFlag(LINE, rule, "env=MY_NAME:some:value");

        assertTrue(rule.isEnv());
        assertEquals(1, rule.getEnvSize());
        assertEquals("MY_NAME", rule.getEnvName(0));
        assertEquals("some:value", rule.getEnvValue(0));
    }

