 19	package io.undertow.servlet.compat.rewrite;
 20	
 21	import java.util.Collections;
 22	import java.util.HashMap;
 23	import java.util.Map;
 24	import java.util.regex.PatternSyntaxException;
 25	
 26	import org.junit.jupiter.api.Test;
 27	
 28	import static org.junit.jupiter.api.Assertions.assertEquals;
 29	import static org.junit.jupiter.api.Assertions.assertNotNull;
 30	import static org.junit.jupiter.api.Assertions.assertNull;
 31	import static org.junit.jupiter.api.Assertions.assertSame;
 32	import static org.junit.jupiter.api.Assertions.assertThrows;
 33	
 34	/**
 35	 * Tests for {@link RewriteRule#evaluate(CharSequence, Resolver)}.
 36	 */
 37	public class RewriteRuleEvaluateTests {
 38	
 39	    private static final Map<String, RewriteMap> NO_MAPS = Collections.emptyMap();
 40	
 41	    /**
 42	     * Simple resolver which serves values from in-memory maps and never touches global state.
 43	     */
 44	    private static final class TestResolver extends Resolver {
 45	
 46	        private final Map<String, String> serverVariables = new HashMap<>();
 47	        private final Map<String, String> envVariables = new HashMap<>();
 48	        private final Map<String, String> sslVariables = new HashMap<>();
 49	        private final Map<String, String> httpVariables = new HashMap<>();
 50	
 51	        @Override
 52	        public String resolve(String key) {
 53	            return serverVariables.get(key);
 54	        }
 55	
 56	        @Override
 57	        public String resolveEnv(String key) {
 58	            return envVariables.get(key);
 59	        }
 60	
 61	        @Override
 62	        public String resolveSsl(String key) {
 63	            return sslVariables.get(key);
 64	        }
 65	
 66	        @Override
 67	        public String resolveHttp(String key) {
 68	            return httpVariables.get(key);
 69	        }
 70	
 71	        @Override
 72	        public boolean resolveResource(int type, String name) {
 73	            return false;
 74	        }
 75	    }
 76	
 77	    private static RewriteRule rule(String patternString, String substitutionString, RewriteCond... conditions) {
 78	        RewriteRule rule = new RewriteRule();
 79	        rule.setPatternString(patternString);
 80	        rule.setSubstitutionString(substitutionString);
 81	        for (RewriteCond condition : conditions) {
 82	            rule.addCondition(condition);
 83	        }
 84	        rule.parse(NO_MAPS);
 85	        return rule;
 86	    }
 87	
 88	    private static RewriteCond condition(String testString, String condPattern) {
 89	        RewriteCond condition = new RewriteCond();
 90	        condition.setTestString(testString);
 91	        condition.setCondPattern(condPattern);
 92	        condition.setOrnext(false);
 93	        return condition;
 94	    }
 95	
 96	    private static RewriteCond orNextCondition(String testString, String condPattern) {
 97	        RewriteCond condition = condition(testString, condPattern);
 98	        condition.setOrnext(true);
 99	        return condition;
100	    }
101	
102	    @Test
103	    public void evaluateReturnsNullWhenPatternDoesNotMatch() {
104	        RewriteRule rule = rule("/foo/(.*)", "/bar/$1");
105	        TestResolver resolver = new TestResolver();
106	
107	        assertNull(rule.evaluate("/other/value", resolver));
108	        assertNull(rule.evaluate("/foo", resolver));
109	    }
110	
111	    @Test
112	    public void evaluateRewritesMatchedUrlUsingSubstitutionBackReferences() {
113	        RewriteRule rule = rule("/(.*)/(.*)\\.html", "/pages/$2/$1.html");
114	        TestResolver resolver = new TestResolver();
115	
116	        CharSequence result = rule.evaluate("/docs/manual.html", resolver);
117	
118	        assertNotNull(result);
119	        assertEquals("/pages/manual/docs.html", result.toString());
120	    }

120	    }
121	
122	    @Test
123	    public void evaluateReturnsOriginalUrlInstanceWhenSubstitutionIsDash() {
124	        RewriteRule rule = rule("/(.*)", "-");
125	        TestResolver resolver = new TestResolver();
126	        CharSequence url = new StringBuilder("/some/path");
127	
128	        CharSequence result = rule.evaluate(url, resolver);
129	
130	        assertSame(url, result);
131	    }
132	
133	    @Test
134	    public void evaluateReturnsOriginalUrlInstanceWhenParseWasNotCalled() {
135	        // The pattern is compiled lazily by evaluate(), but without parse() no substitution exists.
136	        RewriteRule rule = new RewriteRule();
137	        rule.setPatternString("/(.*)");
138	        rule.setSubstitutionString("/rewritten/$1");
139	        TestResolver resolver = new TestResolver();
140	        CharSequence url = "/some/path";
141	
142	        CharSequence result = rule.evaluate(url, resolver);
143	
144	        assertSame(url, result);
145	    }
146	
147	    @Test
148	    public void evaluateUsesServerVariableFromResolverInSubstitution() {
149	        RewriteRule rule = rule("/(.*)", "/target/%{HTTP_HOST}/$1");
150	        TestResolver resolver = new TestResolver();
151	        resolver.serverVariables.put("HTTP_HOST", "example.com");
152	
153	        CharSequence result = rule.evaluate("/a", resolver);
154	
155	        assertEquals("/target/example.com/a", result.toString());
156	    }
157	
158	    @Test
159	    public void evaluateIgnoresCaseWhenNocaseFlagIsSet() {
160	        RewriteRule rule = new RewriteRule();
161	        rule.setPatternString("/FOO/BAR");
162	        rule.setSubstitutionString("/lower");
163	        rule.setNocase(true);
164	        rule.parse(NO_MAPS);
165	
166	        CharSequence result = rule.evaluate("/foo/bar", new TestResolver());
167	
168	        assertEquals("/lower", result.toString());
169	    }
170	
171	    @Test
172	    public void evaluateIsCaseSensitiveByDefault() {
173	        RewriteRule rule = rule("/FOO/BAR", "/lower");
174	
175	        assertNull(rule.evaluate("/foo/bar", new TestResolver()));
176	        assertEquals("/lower", rule.evaluate("/FOO/BAR", new TestResolver()).toString());
177	    }
178	
179	    @Test
180	    public void evaluateReusesCachedPatternForSubsequentInvocations() {
181	        RewriteRule rule = rule("/a", "-");
182	        TestResolver resolver = new TestResolver();
183	
184	        assertSame("/a", rule.evaluate("/a", resolver));
185	
186	        // Changing the raw pattern string does not matter: the compiled pattern is cached per thread.
187	        rule.setPatternString("/b");
188	        assertNull(rule.evaluate("/b", resolver));
189	        assertEquals("/a", rule.evaluate("/a", resolver).toString());
190	    }
191	
192	    @Test
193	    public void evaluateThrowsPatternSyntaxExceptionForInvalidPattern() {
194	        RewriteRule rule = new RewriteRule();
195	        rule.setPatternString("/foo(");
196	        rule.setSubstitutionString("/bar");
197	
198	        assertThrows(PatternSyntaxException.class, () -> rule.evaluate("/foo", new TestResolver()));
199	    }
200	
201	    @Test
202	    public void evaluateThrowsNullPointerExceptionForNullUrl() {
203	        RewriteRule rule = rule("/(.*)", "/bar/$1");
204	
205	        assertThrows(NullPointerException.class, () -> rule.evaluate(null, new TestResolver()));
206	    }
207	
208	    @Test
209	    public void evaluateAppliesSubstitutionWhenSingleConditionMatches() {
210	        RewriteRule rule = rule("/(.*)", "/x/$1", condition("$1", "old"));
211	        TestResolver resolver = new TestResolver();
212	
213	        CharSequence result = rule.evaluate("/old", resolver);
214	
215	        assertNotNull(result);
216	        assertEquals("/x/old", result.toString());
217	    }
218	
219	    @Test
220	    public void evaluateReturnsNullWhenSingleConditionDoesNotMatch() {
221	        RewriteRule rule = rule("/(.*)", "/x/$1", condition("$1", "nomatch"));
222	
223	        assertNull(rule.evaluate("/old", new TestResolver()));
224	    }
225	
226	    @Test
227	    public void evaluateRequiresAllNonOrNextConditionsToMatch() {
228	        RewriteRule rule = rule("/(.*)", "/x/$1",
229	                condition("$1", "old"),
230	                condition("$1", "never"));
231	        TestResolver resolver = new TestResolver();
232	
233	        // First condition matches, second does not: the rule must not rewrite.
234	        assertNull(rule.evaluate("/old", resolver));
235	    }
236	
237	    @Test
238	    public void evaluatePassesConditionMatcherToSubsequentCondition() {
239	        RewriteRule rule = rule("/(.*)", "/matched/$1",
240	                condition("$1", "(o.d)"),
241	                condition("%1", "old"));
242	        TestResolver resolver = new TestResolver();
243	
244	        CharSequence result = rule.evaluate("/old", resolver);
245	
246	        assertNotNull(result);
247	        assertEquals("/matched/old", result.toString());
248	    }
249	
250	    @Test
251	    public void evaluateShortCircuitsOrNextChainWhenConditionMatches() {
252	        // The second condition would fail with an IndexOutOfBoundsException if it were evaluated.
253	        RewriteRule rule = rule("/(.*)", "/x/$1",
254	                orNextCondition("$1", "old"),
255	                condition("%5", "never"));
256	        TestResolver resolver = new TestResolver();
257	
258	        // The first condition matches and is flagged ornext, so the second one is skipped.
259	        CharSequence result = rule.evaluate("/old", resolver);
260	
261	        assertNotNull(result);
262	        assertEquals("/x/old", result.toString());
263	    }
264	
265	    @Test
266	    public void evaluateFallsThroughOrNextChainWhenConditionDoesNotMatch() {
267	        RewriteRule rule = rule("/(.*)", "/x/$1",
268	                orNextCondition("$1", "nomatch"),
269	                condition("$1", "old"));
270	        TestResolver resolver = new TestResolver();
271	
272	        CharSequence result = rule.evaluate("/old", resolver);
273	
274	        assertNotNull(result);
275	        assertEquals("/x/old", result.toString());
276	    }
277	
278	    @Test
279	    public void evaluateReturnsNullWhenOrNextChainFailsCompletely() {
280	        RewriteRule rule = rule("/(.*)", "/x/$1",
281	                orNextCondition("$1", "nomatch"),
282	                orNextCondition("$1", "alsonot"),
283	                condition("$1", "stillnot"));
284	
285	        assertNull(rule.evaluate("/old", new TestResolver()));
286	    }
287	
288	    @Test
289	    public void evaluateFallsBackToFollowingConditionAfterFailedOrNextChain() {
290	        RewriteRule rule = rule("/(.*)", "/x/$1",
291	                orNextCondition("$1", "nomatch"),
292	                orNextCondition("$1", "alsonot"),
293	                condition("$1", "old"));
294	        TestResolver resolver = new TestResolver();
295	
296	        CharSequence result = rule.evaluate("/old", resolver);
297	
298	        assertEquals("/x/old", result.toString());
299	    }
300	
301	    @Test
302	    public void evaluateSetsEnvResultWhenRewriteIsSuccessful() {
303	        RewriteRule rule = new RewriteRule();
304	        rule.setPatternString("/(.*)");
305	        rule.setSubstitutionString("-");
306	        rule.setEnv(true);
307	        rule.addEnvName("MY_VAR");
308	        rule.addEnvValue("env-$1");
