319	    public void evaluateSetsEnvResultUsingConditionBackReference() {
320	        RewriteRule rule = new RewriteRule();
321	        rule.setPatternString("/(.*)");
322	        rule.setSubstitutionString("-");
323	        rule.setEnv(true);
324	        rule.addEnvName("MY_VAR");
325	        rule.addEnvValue("m-%1");
326	        rule.addCondition(condition("$1", "(o.d)"));
327	        rule.parse(NO_MAPS);
