337	    public void evaluateSetsCookieResultWhenRewriteIsSuccessful() {
338	        RewriteRule rule = new RewriteRule();
339	        rule.setPatternString("/(.*)");
340	        rule.setSubstitutionString("-");
341	        rule.setCookie(true);
