349	        assertEquals("cookie-bar", rule.getCookieResult());
350	    }
351	
352	    @Test
353	    public void evaluateSetsEnvAndCookieResultsAndReturnsSubstitution() {
354	        RewriteRule rule = new RewriteRule();
355	        rule.setPatternString("/(.*)");
356	        rule.setSubstitutionString("/dest/$1");
