    private void assertCalendarBasedVariable(String key, int calendarField) {
        int before = Calendar.getInstance().get(calendarField);
        String value = resolver.resolve(key);
        int after = Calendar.getInstance().get(calendarField);

        assertNotNull(value, key + " should not resolve to null");
        int actual;
        try {
            actual = Integer.parseInt(value);
        } catch (NumberFormatException e) {
            throw new AssertionError(key + " should resolve to a numeric value but was '" + value + "'", e);
        }
        assertTrue(actual == before || actual == after,
                key + " resolved to " + actual + " which is not within [" + before + ", " + after + "]");
    }

    private static Date parseRfc1123(String value) {
        SimpleDateFormat format = new SimpleDateFormat(RFC1123_PATTERN, Locale.US);
        format.setTimeZone(TimeZone.getTimeZone("GMT"));
        try {
            return format.parse(value);
        } catch (ParseException e) {
            throw new AssertionError("Value '" + value + "' is not an RFC1123 date", e);
        }
    }
