/**
 * Unit tests for {@link ApplicationListeners#addListener(ManagedListener)}.
 * <p>
 * The registration is verified both by inspecting the internal per-event-type arrays and by invoking
 * the public event dispatch methods and observing which listeners actually receive the events.
 */
class ApplicationListenersAddListenerTests {

    private static final String[] LISTENER_ARRAY_FIELDS = {
            "servletContextListeners",
            "servletContextAttributeListeners",
            "servletRequestListeners",
            "servletRequestAttributeListeners",
            "httpSessionListeners",
            "httpSessionAttributeListeners",
            "httpSessionIdListeners"
    };

    private List<String> calls;
    private ServletContext servletContext;
    private ServletRequest servletRequest;
    private HttpServletRequest httpServletRequest;
    private HttpSession httpSession;
    private ApplicationListeners listeners;

    @BeforeEach
    void setUp() {
        calls = new ArrayList<>();
        servletContext = stub(ServletContext.class);
        servletRequest = stub(ServletRequest.class);
        httpServletRequest = stub(HttpServletRequest.class);
        httpSession = stub(HttpSession.class);
        listeners = new ApplicationListeners(new ArrayList<ManagedListener>(), servletContext);
    }

    @Test
    void addListenerWithContextListenerOnlyRegistersForContextEvents() {
        RecordingContextListener listener = new RecordingContextListener("ctx", calls);
        ManagedListener managed = managed(ServletContextListener.class, listener);

        listeners.addListener(managed);

        assertSame(managed, listenersOf("servletContextListeners")[0]);
        assertEquals(1, listenersOf("servletContextListeners").length);
        for (int i = 1; i < LISTENER_ARRAY_FIELDS.length; i++) {
            assertEquals(0, listenersOf(LISTENER_ARRAY_FIELDS[i]).length,
                    "listener must not be registered in " + LISTENER_ARRAY_FIELDS[i]);
        }
        assertEquals(1, allListeners().size());
        assertSame(managed, allListeners().get(0));

        listeners.start();
        invokeAllEventTypes();
        assertEquals(List.of("ctx:contextInitialized"), calls);
    }

    @Test
    void addListenerImplementingEveryListenerTypeIsRegisteredInEveryArray() {
        MultiListener listener = new MultiListener(calls);
        ManagedListener managed = managed(MultiListener.class, listener);

        listeners.addListener(managed);

        for (String field : LISTENER_ARRAY_FIELDS) {
            assertEquals(1, listenersOf(field).length, "listener must be registered in " + field);
            assertSame(managed, listenersOf(field)[0], "wrong array entry in " + field);
        }
        assertEquals(1, allListeners().size());
        assertSame(managed, allListeners().get(0));

        listeners.start();
        invokeAllEventTypes();

        assertEquals(List.of(
                "contextInitialized",
                "contextAttributeAdded",
                "requestInitialized",
                "requestAttributeAdded",
                "sessionCreated",
                "sessionAttributeAdded",
                "sessionIdChanged"), calls);
    }

    @Test
    void addListenerWithPartialMatchRegistersOnlyForMatchingEvents() {
        ContextAndSessionListener listener = new ContextAndSessionListener(calls);
        ManagedListener managed = managed(ContextAndSessionListener.class, listener);

        listeners.addListener(managed);

        assertEquals(1, listenersOf("servletContextListeners").length);
        assertEquals(1, listenersOf("httpSessionListeners").length);
        assertEquals(1, listenersOf("servletContextAttributeListeners").length == 0 ? 1 : 0,
                "context attribute listener array must stay empty");
        assertEquals(0, listenersOf("servletContextAttributeListeners").length);
        assertEquals(0, listenersOf("servletRequestListeners").length);
        assertEquals(0, listenersOf("servletRequestAttributeListeners").length);
        assertEquals(0, listenersOf("httpSessionAttributeListeners").length);
        assertEquals(0, listenersOf("httpSessionIdListeners").length);

        listeners.start();
        listeners.contextInitialized();
        listeners.requestInitialized(servletRequest);
        listeners.sessionCreated(httpSession);

        assertEquals(List.of("contextInitialized", "sessionCreated"), calls);
    }

    @Test
    void addListenerKeepsRegistrationOrderForSeveralListeners() {
        RecordingContextListener first = new RecordingContextListener("first", calls);
        RecordingContextListener second = new RecordingContextListener("second", calls);
        ManagedListener managedFirst = managed(ServletContextListener.class, first);
        ManagedListener managedSecond = managed(ServletContextListener.class, second);

        listeners.addListener(managedFirst);
        listeners.addListener(managedSecond);

        assertEquals(2, listenersOf("servletContextListeners").length);
        assertSame(managedFirst, listenersOf("servletContextListeners")[0]);
        assertSame(managedSecond, listenersOf("servletContextListeners")[1]);
        assertEquals(2, allListeners().size());
        assertSame(managedFirst, allListeners().get(0));
        assertSame(managedSecond, allListeners().get(1));

        listeners.start();
        listeners.contextInitialized();
        assertEquals(List.of("first:contextInitialized", "second:contextInitialized"), calls);

        listeners.contextDestroyed();
        assertEquals(List.of(
                "first:contextInitialized",
                "second:contextInitialized",
                "second:contextDestroyed",
                "first:contextDestroyed"), calls);
    }

    @Test
