        FixedInstanceFactory<RecordingContextListener> factory = new FixedInstanceFactory<>(listener);
        ManagedListener managed = new ManagedListener(new ListenerInfo(ServletContextListener.class, factory), false);

        listeners.addListener(managed);

        assertFalse(listeners.isStarted());
        assertFalse(managed.isStarted());
        assertEquals(0, factory.createCount.get());
        assertEquals(1, listenersOf("servletContextListeners").length);

        listeners.start();

        assertTrue(managed.isStarted());
        assertEquals(1, factory.createCount.get());
        assertSame(listener, managed.instance());

        listeners.contextInitialized();
        assertEquals(List.of("ctx:contextInitialized"), calls);
    }

    @Test
    void addListenerAfterStartStartsTheListenerImmediately() {
        listeners.start();
        assertTrue(listeners.isStarted());

        RecordingContextListener listener = new RecordingContextListener("ctx", calls);
        FixedInstanceFactory<RecordingContextListener> factory = new FixedInstanceFactory<>(listener);
        ManagedListener managed = new ManagedListener(new ListenerInfo(ServletContextListener.class, factory), false);

        listeners.addListener(managed);

        assertTrue(managed.isStarted());
        assertEquals(1, factory.createCount.get());
        assertSame(listener, managed.instance());
        assertEquals(1, listenersOf("servletContextListeners").length);
        assertSame(managed, listenersOf("servletContextListeners")[0]);

        listeners.contextInitialized();
        assertEquals(List.of("ctx:contextInitialized"), calls);
    }

    @Test
    void addListenerAfterStartWhenStartingFailsThrowsRuntimeExceptionWrappingServletException() {
        listeners.start();

        ManagedListener managed = new ManagedListener(new ListenerInfo(FailingConstructorListener.class), false);

        RuntimeException thrown = assertThrows(RuntimeException.class, () -> listeners.addListener(managed));

        assertInstanceOf(ServletException.class, thrown.getCause());
        assertFalse(managed.isStarted());
        // the listener has already been registered before the start attempt is made
        assertEquals(1, listenersOf("servletContextListeners").length);
        assertSame(managed, listenersOf("servletContextListeners")[0]);
        assertEquals(1, allListeners().size());
    }

