        ManagedListener managed = new ManagedListener(new MaskedListenerInfo(unrelated), false);

        listeners.addListener(managed);

        for (String field : LISTENER_ARRAY_FIELDS) {
            assertEquals(0, listenersOf(field).length, "listener must not be registered in " + field);
