        assertThrows(NullPointerException.class, () -> listeners.addListener(null));
        assertEquals(0, allListeners().size());
    }

    private void invokeAllEventTypes() {
        listeners.contextInitialized();
        listeners.servletContextAttributeAdded("name", "value");
        listeners.requestInitialized(servletRequest);
        listeners.servletRequestAttributeAdded(httpServletRequest, "name", "value");
        listeners.sessionCreated(httpSession);
        listeners.httpSessionAttributeAdded(httpSession, "name", "value");
        listeners.httpSessionIdChanged(httpSession, "oldId");
    }

    private ManagedListener[] listenersOf(String fieldName) {
        try {
            Field field = ApplicationListeners.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            return (ManagedListener[]) field.get(listeners);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("could not read " + fieldName, e);
        }
    }

    @SuppressWarnings("unchecked")
    private List<ManagedListener> allListeners() {
        try {
            Field field = ApplicationListeners.class.getDeclaredField("allListeners");
            field.setAccessible(true);
            return (List<ManagedListener>) field.get(listeners);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("could not read allListeners", e);
        }
    }

    private static <T extends EventListener> ManagedListener managed(Class<? extends EventListener> listenerClass, T instance) {
        return new ManagedListener(new ListenerInfo(listenerClass, new FixedInstanceFactory<>(instance)), false);
    }

    private static <T> T stub(final Class<T> type) {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, new InvocationHandler() {
            @Override
            public Object invoke(Object proxy, Method method, Object[] args) {
                switch (method.getName()) {
                    case "toString":
                        return type.getSimpleName() + "Stub";
                    case "hashCode":
                        return System.identityHashCode(proxy);
                    case "equals":
                        return proxy == args[0];
                    default:
                        break;
                }
                Class<?> returnType = method.getReturnType();
                if (returnType == boolean.class) {
                    return Boolean.FALSE;
                }
                if (returnType == int.class) {
                    return Integer.valueOf(0);
                }
                if (returnType == long.class) {
                    return Long.valueOf(0L);
                }
                return null;
            }
        }));
    }

    private static final class FixedInstanceFactory<T extends EventListener> implements InstanceFactory<T> {

        private final T instance;
        private final AtomicInteger createCount = new AtomicInteger();

        FixedInstanceFactory(T instance) {
            this.instance = instance;
        }

        @Override
        public InstanceHandle<T> createInstance() {
            createCount.incrementAndGet();
            return new InstanceHandle<T>() {
                @Override
                public T getInstance() {
                    return instance;
                }

                @Override
                public void release() {
                }
            };
        }
    }

