     */
    private static final class MaskedListenerInfo extends ListenerInfo {

        MaskedListenerInfo(EventListener instance) {
            super(ServletContextListener.class, new FixedInstanceFactory<>(instance));
        }

        @Override
        public Class<? extends EventListener> getListenerClass() {
            return UnrelatedListener.class;
        }
    }

