class ServletContextImplParseContentTypeTests {

    private ServletContextImpl servletContext;

    @BeforeEach
    void setUp() {
        DeploymentInfo deploymentInfo = new DeploymentInfo()
                .setContextPath("/test")
                .setContentTypeCacheSize(10)
                .setDefaultSessionTimeout(60);
        servletContext = new ServletContextImpl(null, deployment(deploymentInfo));
    }

    @Test
    void plainContentTypeIsReturnedUnchanged() {
        ContentTypeInfo info = servletContext.parseContentType("text/html");

        assertEquals("text/html", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void contentTypeWithoutCharsetKeepsAdditionalParametersUnchanged() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;foo=bar");

        assertEquals("text/html;foo=bar", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html;foo=bar", info.getContentType());
    }

    @Test
    void charsetIsExtractedAndNormalizedInHeader() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=UTF-8");

        assertEquals("text/html;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void whitespaceBeforeCharsetParameterIsAccepted() {
        ContentTypeInfo info = servletContext.parseContentType("text/html; charset=UTF-8");

        assertEquals("text/html;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void surroundingQuotesAreRemovedFromCharset() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=\"UTF-8\"");

        assertEquals("text/html;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void unterminatedSurroundingQuoteIsKeptInCharset() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=\"UTF-8");

        assertEquals("text/html;charset=\"UTF-8", info.getHeader());
        assertEquals("\"UTF-8", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void parametersAfterCharsetArePreserved() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=UTF-8;foo=bar");

        assertEquals("text/html;foo=bar;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html;foo=bar", info.getContentType());
    }

    @Test
    void parametersBeforeCharsetArePreserved() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;foo=bar;charset=UTF-8");

        assertEquals("text/html;foo=bar;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html;foo=bar", info.getContentType());
    }

    @Test
    void trailingSemicolonIsRemovedWhenNoCharsetIsPresent() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;");

        assertEquals("text/html", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void trailingWhitespaceAndSemicolonAreRemovedWhenNoCharsetIsPresent() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;  ");

        assertEquals("text/html", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void onlyTheLastTrailingSemicolonIsRemovedWhenNoCharsetIsPresent() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;;");

        assertEquals("text/html;", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html;", info.getContentType());
    }

    @Test
    void semicolonFollowingCharsetDoesNotRemainInContentType() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=UTF-8;");

        assertEquals("text/html;charset=UTF-8", info.getHeader());
        assertEquals("UTF-8", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void emptyCharsetTerminatedBySemicolonIsReportedAsEmptyString() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;charset=;");

        assertEquals("text/html;charset=", info.getHeader());
        assertEquals("", info.getCharset());
        assertEquals("text/html", info.getContentType());
    }

    @Test
    void charsetParameterNameIsCaseSensitive() {
        ContentTypeInfo info = servletContext.parseContentType("text/html;Charset=UTF-8");

        assertEquals("text/html;Charset=UTF-8", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/html;Charset=UTF-8", info.getContentType());
    }

    @Test
    void charsetParameterRequiresAPrecedingSemicolon() {
        ContentTypeInfo info = servletContext.parseContentType("text/htmlcharset=UTF-8");

        assertEquals("text/htmlcharset=UTF-8", info.getHeader());
        assertNull(info.getCharset());
        assertEquals("text/htmlcharset=UTF-8", info.getContentType());
    }

    @Test
    void emptyCharsetAtEndOfValueThrows() {
        assertThrows(StringIndexOutOfBoundsException.class,
                () -> servletContext.parseContentType("text/html;charset="));
    }

    @Test
    void charsetParameterWithoutPrecedingSemicolonThrows() {
        assertThrows(StringIndexOutOfBoundsException.class,
                () -> servletContext.parseContentType("charset=UTF-8;foo=bar"));
    }

    @Test
    void repeatedParsesOfTheSameValueReturnTheCachedInstance() {
        ContentTypeInfo first = servletContext.parseContentType("text/html; charset=UTF-8");
        ContentTypeInfo second = servletContext.parseContentType("text/html; charset=UTF-8");

        assertSame(first, second);
    }

    @Test
    void equivalentButTextuallyDifferentValuesUseDistinctCacheEntries() {
        ContentTypeInfo spaced = servletContext.parseContentType("text/html; charset=UTF-8");
        ContentTypeInfo compact = servletContext.parseContentType("text/html;charset=UTF-8");

        assertNotSame(spaced, compact);
        assertEquals("text/html;charset=UTF-8", spaced.getHeader());
        assertEquals(spaced.getHeader(), compact.getHeader());
        assertEquals(spaced.getCharset(), compact.getCharset());
        assertEquals(spaced.getContentType(), compact.getContentType());
    }

    private static Deployment deployment(DeploymentInfo deploymentInfo) {
        return (Deployment) Proxy.newProxyInstance(
                Deployment.class.getClassLoader(),
                new Class<?>[] { Deployment.class },
                (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "getDeploymentInfo":
                            return deploymentInfo;
                        case "toString":
                            return "DeploymentStub";
                        case "hashCode":
                            return System.identityHashCode(proxy);
                        case "equals":
                            return proxy == args[0];
                        default:
                            return defaultValue(method.getReturnType());
                    }
                });
    }

    private static Object defaultValue(Class<?> returnType) {
        if (returnType == boolean.class) {
            return Boolean.FALSE;
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0F;
        }
        if (returnType == double.class) {
            return 0D;
        }
        if (returnType == char.class) {
            return (char) 0;
        }
        return null;
    }
}
