@Override
public void write(ByteBuffer[] buffers) throws IOException {
    if (anyAreSet(state, FLAG_CLOSED) || servletRequestContext.getOriginalResponse().isTreatAsCommitted()) {
        throw UndertowServletMessages.MESSAGES.streamIsClosed();
    }
