            setFlags(FLAG_WRITE_STARTED);
        } else {
            ByteBuffer buffer = buffer();
            if (len < buffer.remaining()) {
                Buffers.copy(buffer, buffers, 0, buffers.length);
            } else {
                if (channel == null) {
                    channel = servletRequestContext.getExchange().getResponseChannel();
                }
