class ServletOutputStreamImplWriteTests {

    private static final int FLAG_CLOSED = 1;
    private static final int FLAG_READY = 1 << 2;

    private ServletRequestContext servletRequestContext;
    private HttpServletResponseImpl originalResponse;
    private HttpServerExchange exchange;
