        when(channel.write(any(ByteBuffer[].class))).thenAnswer(invocation ->
                recorder.record(invocation.<ByteBuffer[]>getArgument(0)));
        when(channel.write(any(ByteBuffer.class))).thenAnswer(invocation ->
                recorder.record(invocation.<ByteBuffer>getArgument(0)));
    }

    @Test
    void writeThrowsWhenStreamIsClosed() throws Exception {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext);
        setIntField(stream, "state", FLAG_CLOSED);

        IOException exception = assertThrows(IOException.class,
                () -> stream.write(buffers("ignored")));

        assertTrue(exception.getMessage().contains("UT010029"),
                "The stream-is-closed message should be reported");
        assertEquals(0, recorder.callCount);
        verify(exchange, never()).getResponseChannel();
    }

    @Test
    void writeThrowsWhenResponseTreatsItselfAsCommitted() {
        when(originalResponse.isTreatAsCommitted()).thenReturn(true);
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext);

        IOException exception = assertThrows(IOException.class,
                () -> stream.write(buffers("ignored")));

        assertTrue(exception.getMessage().contains("UT010029"),
                "A committed response must reject further stream writes");
        assertEquals(0, recorder.callCount);
        verify(exchange, never()).getResponseChannel();
    }

    @Test
    void writeWithNoBuffersReturnsWithoutAcquiringAChannel() throws IOException {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext);

        stream.write(new ByteBuffer[0]);

        assertEquals(0, recorder.callCount);
        verify(exchange, never()).getResponseChannel();
        verify(originalResponse, never()).setContentFullyWritten();
    }

    @Test
    void writeWithOnlyEmptyBuffersReturnsWithoutAcquiringAChannel() throws IOException {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext);

        stream.write(new ByteBuffer[] {
                ByteBuffer.allocate(0),
                ByteBuffer.wrap(new byte[0])
        });

        assertEquals(0, recorder.callCount);
        verify(exchange, never()).getResponseChannel();
        verify(originalResponse, never()).setContentFullyWritten();
    }

    @Test
    void writeExactContentLengthWritesAllBuffersDirectly() throws IOException {
        when(originalResponse.getContentLength()).thenReturn(7L);
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext);

        stream.write(buffers("hello", "!!"));

        assertEquals("hello!!", recorder.text());
        verify(exchange).getResponseChannel();
        verify(originalResponse).setContentFullyWritten();
    }

    @Test
    void bufferSmallWriteThenFlushCombinedBuffers() throws IOException {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 8);

        stream.write(buffers("abc"));

