        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 4);

        stream.write(buffers("abcd"));

        assertEquals("abcd", recorder.text());
        verify(exchange).getResponseChannel();
    }

    @Test
    void writeDirectlyWhenPayloadIsLargerThanInternalBuffer() throws IOException {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 4);

        stream.write(buffers("abcdef"));

        assertEquals("abcdef", recorder.text());
        verify(exchange).getResponseChannel();
    }

    @Test
    void asyncWriteThrowsWhenStreamIsNotReady() throws Exception {
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 8);
        setField(stream, "listener", mock(WriteListener.class));

        IllegalStateException exception = assertThrows(IllegalStateException.class,
