        when(originalResponse.getContentLength()).thenReturn(6L);
        recorder.zeroOnFirstCall = true;
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 4);
        makeAsyncReady(stream);

