        }
        return result;
    }

    private static String remainingText(ByteBuffer[] buffers) {
        StringBuilder result = new StringBuilder();
        for (ByteBuffer buffer : buffers) {
            ByteBuffer duplicate = buffer.duplicate();
            while (duplicate.hasRemaining()) {
                result.append((char) duplicate.get());
            }
        }
        return result.toString();
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static void setIntField(Object target, String fieldName, int value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.setInt(target, value);
    }

    private static Object getField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private static final class Recorder {
        private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        private int callCount;
        private int maxBytesPerCall = Integer.MAX_VALUE;
        private boolean zeroOnFirstCall;

        long record(ByteBuffer[] buffers, int offset, int length) {
            callCount++;
            if (zeroOnFirstCall) {
                zeroOnFirstCall = false;
                return 0;
            }
            int remainingAllowance = maxBytesPerCall;
            long written = 0;
            for (int i = offset; i < offset + length && remainingAllowance > 0; i++) {
                ByteBuffer buffer = buffers[i];
                int toWrite = Math.min(buffer.remaining(), remainingAllowance);
                if (toWrite > 0) {
                    byte[] copy = new byte[toWrite];
                    buffer.get(copy);
                    bytes.write(copy, 0, copy.length);
                    written += toWrite;
                    remainingAllowance -= toWrite;
                }
            }
            return written;
        }

        long record(ByteBuffer[] buffers) {
            return record(buffers, 0, buffers.length);
        }

        int record(ByteBuffer buffer) {
            int toWrite = Math.min(buffer.remaining(), maxBytesPerCall);
            byte[] copy = new byte[toWrite];
            buffer.get(copy);
            bytes.write(copy, 0, copy.length);
            callCount++;
            return toWrite;
        }

        String text() {
            return new String(bytes.toByteArray(), StandardCharsets.US_ASCII);
        }
    }
