        exchange = mock(HttpServerExchange.class);
        channel = mock(StreamSinkChannel.class);
        recorder = new Recorder();

        when(servletRequestContext.getOriginalResponse()).thenReturn(originalResponse);
        when(servletRequestContext.getExchange()).thenReturn(exchange);
        when(originalResponse.isTreatAsCommitted()).thenReturn(false);
        when(originalResponse.getContentLength()).thenReturn(-1L);
        when(exchange.getResponseChannel()).thenReturn(channel);
        when(channel.write(any(ByteBuffer[].class), anyInt(), anyInt())).thenAnswer(invocation ->
                recorder.record(invocation.getArgument(0), invocation.getArgument(1), invocation.getArgument(2)));
        when(channel.write(any(ByteBuffer[].class))).thenAnswer(invocation ->
                recorder.record(invocation.<ByteBuffer[]>getArgument(0)));
        when(channel.write(any(ByteBuffer.class))).thenAnswer(invocation ->
                recorder.record(invocation.<ByteBuffer>getArgument(0)));
