        assertTrue(exception.getMessage().contains("UT010035"),
                "An async write is only legal while the stream is ready");
        assertEquals(0, recorder.callCount);
    }

    @Test
    void asyncWriteBuffersPayloadThatFitsInTheInternalBuffer() throws Exception {
        when(originalResponse.getContentLength()).thenReturn(2L);
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 8);
        makeAsyncReady(stream);

