        verify(exchange).getResponseChannel();
    }

    @Test
    void asyncWriteContinuesUntilAllChannelWritesComplete() throws Exception {
        recorder.maxBytesPerCall = 2;
        ServletOutputStreamImpl stream = new ServletOutputStreamImpl(servletRequestContext, 4);
        makeAsyncReady(stream);

        stream.write(buffers("abcdef"));

        assertEquals("abcdef", recorder.text());
        assertEquals(3, recorder.callCount,
                "The async write loop must continue after partial channel writes");
    }

    @Test
    void asyncWriteQueuesRemainingDataAndResumesWritesWhenChannelBlocks() throws Exception {
