package io.undertow.servlet.spec;

import static java.nio.charset.StandardCharsets.ISO_8859_1;
import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;

import org.junit.jupiter.api.Test;

/**
 * Tests for {@link ServletPrintWriter#write(CharBuffer)}.
 */
public class ServletPrintWriterWriteTests {

    @Test
    public void writesAsciiAndUpdatesWrittenByteCount() throws Exception {
        final TestOutputStream output = new TestOutputStream(32);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("hello");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(5, output.written);
        assertEquals(1, output.updateCalls);
        assertEquals(0, input.remaining());
        assertEquals(0, output.flushInternalCalls);
        assertArrayEquals("hello".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void writesMultibyteCharactersUsingUtf8() throws Exception {
        final TestOutputStream output = new TestOutputStream(32);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final String value = "h\u00E9llo \u2713";
        final CharBuffer input = CharBuffer.wrap(value);

        writer.write(input);

        final byte[] expected = value.getBytes(UTF_8);
        assertFalse(writer.checkError());
        assertEquals(expected.length, output.written);
        assertEquals(0, input.remaining());
        assertArrayEquals(expected, output.allBytes());
    }

    @Test
    public void writesWithIso88591() throws Exception {
        final TestOutputStream output = new TestOutputStream(16);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "ISO-8859-1");
        final CharBuffer input = CharBuffer.wrap("\u00E9");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(1, output.written);
        assertArrayEquals(new byte[] { (byte) 0xE9 }, output.allBytes());
    }

    @Test
    public void replacesUnmappableCharactersInsteadOfReportingAnError() throws Exception {
        final TestOutputStream output = new TestOutputStream(16);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "ISO-8859-1");
        final CharBuffer input = CharBuffer.wrap("\u20AC");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(1, output.written);
        assertArrayEquals(new byte[] { (byte) '?' }, output.allBytes());
    }

    @Test
    public void combinesUnderflowFromIncompleteSurrogateWithNextWrite() throws Exception {
        final TestOutputStream output = new TestOutputStream(32);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer highSurrogate = CharBuffer.wrap(new char[] { '\uD83D' });

        writer.write(highSurrogate);

        assertFalse(writer.checkError());
        assertEquals(0, output.written);
        assertEquals(0, output.allBytes().length);
        assertEquals(0, highSurrogate.remaining());

        writer.write(CharBuffer.wrap(new char[] { '\uDE00' }));

        assertFalse(writer.checkError());
        assertEquals(4, output.written);
        assertArrayEquals("\uD83D\uDE00".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void marksErrorWhenUnderlyingBufferIsUnavailable() throws Exception {
        final TestOutputStream output = new TestOutputStream(16);
        output.closed = true;
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("ignored");

        writer.write(input);

        assertTrue(writer.checkError());
        assertEquals(0, output.written);
        assertEquals(0, output.allBytes().length);
        assertEquals(4, input.remaining());
    }

    @Test
    public void flushesOnceWhenBufferStartsFullAndThenWrites() throws Exception {
        final TestOutputStream output = new TestOutputStream(ByteBuffer.allocate(8));
        output.buffer.put("old".getBytes(UTF_8));
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");

        writer.write(CharBuffer.wrap("abc"));

        assertFalse(writer.checkError());
        assertEquals(3, output.written);
        assertEquals(1, output.flushInternalCalls);
        assertArrayEquals("oldabc".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void marksErrorWhenInitialFlushMakesNoRoom() throws Exception {
        final TestOutputStream output = new TestOutputStream(ByteBuffer.allocate(4));
        output.buffer.put("full".getBytes(UTF_8));
        output.flushWithoutChangingBuffer = true;
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");

        writer.write(CharBuffer.wrap("a"));

        assertTrue(writer.checkError());
        assertEquals(0, output.written);
        assertEquals(1, output.flushInternalCalls);
        assertArrayEquals("full".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void flushesAndContinuesWhenEncoderOutputOverflows() throws Exception {
        final TestOutputStream output = new TestOutputStream(2);
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("hello");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(5, output.written);
        assertEquals(2, output.flushInternalCalls);
        assertEquals(0, input.remaining());
        assertArrayEquals("hello".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void marksErrorWhenOverflowFlushMakesNoProgress() throws Exception {
        final TestOutputStream output = new TestOutputStream(2);
        output.flushWithoutChangingBuffer = true;
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("abc");

        writer.write(input);

        assertTrue(writer.checkError());
        assertEquals(2, output.written);
        assertEquals(1, output.flushInternalCalls);
        assertArrayEquals("ab".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void limitsOutputToRemainingContentLength() throws Exception {
        final TestOutputStream output = new TestOutputStream(32);
        output.remainingContentLength = 3;
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("abcdef");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(3, output.written);
        assertEquals(0, input.remaining());
        assertArrayEquals("abc".getBytes(UTF_8), output.allBytes());
    }

    @Test
    public void writesNothingWhenContentLengthIsAlreadyExhausted() throws Exception {
        final TestOutputStream output = new TestOutputStream(16);
        output.remainingContentLength = 0;
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");
        final CharBuffer input = CharBuffer.wrap("abc");

        writer.write(input);

        assertFalse(writer.checkError());
        assertEquals(0, output.written);
        assertEquals(0, output.flushInternalCalls);
        assertEquals(3, input.remaining());
        assertEquals(0, output.allBytes().length);
    }

    @Test
    public void catchesIoExceptionFromStreamFlush() throws Exception {
        final TestOutputStream output = new TestOutputStream(ByteBuffer.allocate(2));
        output.buffer.put("xx".getBytes(UTF_8));
        output.flushException = new IOException("flush failed");
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");

        writer.write(CharBuffer.wrap("a"));

        assertTrue(writer.checkError());
        assertEquals(1, output.flushInternalCalls);
        assertEquals(0, output.written);
    }

    @Test
    public void catchesIoExceptionFromContentLengthLookup() throws Exception {
        final TestOutputStream output = new TestOutputStream(16);
        output.contentLengthException = new IOException("content length failed");
        final ServletPrintWriter writer = new ServletPrintWriter(output, "UTF-8");

        writer.write(CharBuffer.wrap("a"));

        assertTrue(writer.checkError());
        assertEquals(0, output.written);
        assertEquals(0, output.allBytes().length);
    }

    private static final class TestOutputStream extends ServletOutputStreamImpl {

        private ByteBuffer buffer;
        private boolean closed;
        private long remainingContentLength = Long.MAX_VALUE;
        private long written;
        private int updateCalls;
        private int flushInternalCalls;
        private boolean flushWithoutChangingBuffer;
        private IOException flushException;
        private IOException contentLengthException;
        private final ByteArrayOutputStream flushed = new ByteArrayOutputStream();

        private TestOutputStream(final int capacity) {
            this(ByteBuffer.allocate(capacity));
        }

        private TestOutputStream(final ByteBuffer buffer) {
            super(null);
            this.buffer = buffer;
        }

        @Override
        ByteBuffer underlyingBuffer() {
            return closed ? null : buffer;
        }

        @Override
        long remainingContentLength() throws IOException {
            if (contentLengthException != null) {
                throw contentLengthException;
            }
            return remainingContentLength;
        }

        @Override
        void updateWritten(final long len) {
            written += len;
            updateCalls++;
        }

        @Override
        void flushInternal() throws IOException {
            flushInternalCalls++;
            if (flushException != null) {
                throw flushException;
            }
            if (flushWithoutChangingBuffer) {
                return;
            }
            buffer.flip();
            final byte[] bytes = new byte[buffer.remaining()];
            buffer.get(bytes);
            flushed.write(bytes, 0, bytes.length);
            buffer.clear();
        }

        @Override
        public void flush() {
            // The tests inspect success via checkError(); a no-op flush keeps
            // the state deterministic and does not disturb the fake buffer.
        }

        private byte[] allBytes() {
            final ByteBuffer copy = buffer.duplicate();
            copy.flip();
            final byte[] buffered = new byte[copy.remaining()];
            copy.get(buffered);
            final byte[] done = flushed.toByteArray();
            final byte[] result = new byte[done.length + buffered.length];
            System.arraycopy(done, 0, result, 0, done.length);
            System.arraycopy(buffered, 0, result, done.length, buffered.length);
            return result;
        }
    }
}
